//	    fmt.Printf("使用配置的端口: %d\n", port)
//	} else {
//	    fmt.Println("端口配置不存在，使用默认值")
//	}
//
//	// 检查可选配置
//	if tool.Exists("feature.new_ui") {
//	    enabled := tool.ValueBool("feature.new_ui")
//	    if enabled {
//	        // 启用新 UI
//	    }
//	}
//
//	// 条件性配置加载
//	if tool.Exists("cache.redis") {
//	    // 使用 Redis 缓存
//	    redisConfig := tool.ValueMap("cache.redis")
//	    // ...
//	} else {
//	    // 使用内存缓存
//	}
//
// 注意事项:
//   - 该方法只检查键是否存在，不检查值是否为 nil
//   - 如果配置值为 nil，该方法仍然返回 true
//   - 该方法是线程安全的
func Exists(key string) bool {
	_, exists := Value(key)
	return exists
}

// RequireKeys 验证必需的配置键是否存在
// 用于程序启动时验证必需的配置项，确保配置完整性
//
// 参数:
//   - keys: 必需的配置键列表，支持可变参数
//
// 返回:
//   - error: 如果有配置缺失，返回包含所有缺失配置的错误；全部存在返回 nil
//
// 使用示例:
//
//	// 验证必需的配置项
//	if err := tool.RequireKeys(
//	    "app.name",
//	    "app.port",
//	    "database.host",
//	    "database.port",
//	    "database.username",
//	); err != nil {
//	    log.Fatalf("[RequireKeys] 配置验证失败: %v", err)
//	}
//
//	// 分组验证
//	// 验证应用配置
//	if err := tool.RequireKeys("app.name", "app.version"); err != nil {
//	    log.Fatalf("[RequireKeys] 应用配置不完整: %v", err)
//	}
//
//	// 验证数据库配置
//	if err := tool.RequireKeys("database.host", "database.port"); err != nil {
//	    log.Fatalf("[RequireKeys] 数据库配置不完整: %v", err)
//	}
//
//	// 条件性验证
//	if tool.ValueBool("feature.cache_enabled") {
//	    if err := tool.RequireKeys("cache.redis.host", "cache.redis.port"); err != nil {
//	        log.Fatalf("[RequireKeys] 缓存配置不完整: %v", err)
//	    }
//	}
//
// 注意事项:
//   - 建议在程序启动时调用，尽早发现配置问题
//   - 错误信息会列出所有缺失的配置项
//   - 该方法是线程安全的
func RequireKeys(keys ...string) error {
	var missing []string
	for _, key := range keys {
		if !Exists(key) {
			missing = append(missing, key)
		}
	}
	if len(missing) > 0 {
		return fmt.Errorf("缺少必需的配置项: %s", strings.Join(missing, ", "))
	}
	return nil
}

// AllKeys 返回所有配置键（扁平化）
// 用于调试、配置导出或配置检查
//
// 返回:
//   - []string: 所有配置键的列表，使用点分隔表示嵌套关系
//
// 使用示例:
//
//	// 打印所有配置键
//	keys := tool.AllKeys()
//	fmt.Println("所有配置项:")
//	for _, key := range keys {
//	    fmt.Printf("  - %s\n", key)
//	}
//
//	// 检查配置完整性
//	keys := tool.AllKeys()
//	fmt.Printf("共有 %d 个配置项\n", len(keys))
//
//	// 导出配置清单
//	keys := tool.AllKeys()
//	for _, key := range keys {
//	    val, _ := tool.Value(key)
//	    fmt.Printf("%s = %v\n", key, val)
//	}
//
//	// 查找特定前缀的配置
//	keys := tool.AllKeys()
//	for _, key := range keys {
//	    if strings.HasPrefix(key, "database.") {
//	        fmt.Printf("数据库配置: %s\n", key)
//	    }
//	}
//
// 注意事项:
//   - 返回的键是扁平化的，嵌套配置使用点分隔
//   - 只返回叶子节点的键，不包含中间节点
//   - 配置未加载时返回 nil
//   - 该方法是线程安全的，使用读锁保护
func AllKeys() []string {
	configLock.RLock()
	defer configLock.RUnlock()

	if config == nil {
		return nil
	}

	return config.allKeys("", config.data)
}

// Config 配置结构，使用 map 存储以支持灵活的键值访问
// 内部使用 map[string]interface{} 存储配置数据，支持动态键访问和嵌套结构
//
// 字段说明:
//   - data: 存储配置数据的 map，键为字符串，值为任意类型
//
// 注意事项:
//   - 该结构体不应直接实例化，应使用 NewConfig 或 Load 方法
//   - 配置数据是从 YAML 文件解析而来
//   - 支持嵌套的 map 结构，可以表示复杂的配置层次
type Config struct {
	data map[string]interface{}
}

// NewConfig 从文件加载配置
// 读取 YAML 配置文件并解析为 Config 对象
//
// 参数:
//   - file: 配置文件路径，支持相对路径和绝对路径
//
// 返回:
//   - *Config: 配置对象指针
//   - error: 读取或解析失败时返回错误
//
// 使用示例:
//
//	// 加载配置文件
//	config, err := tool.NewConfig("config.yaml")
//	if err != nil {
//	    log.Fatalf("[NewConfig] 加载配置失败: %v", err)
//	}
//
//	// 获取配置值
//	val, exists := config.get("app.port")
//	if exists {
//	    fmt.Printf("端口: %v\n", val)
//	}
//
//	// 通常不需要直接调用此方法，使用 Load 方法即可
//	if err := tool.Load("config.yaml"); err != nil {
//	    log.Fatalf("[Load] 加载配置失败: %v", err)
//	}
//
// 配置文件示例 (config.yaml):
//
//	app:
//	  name: "MyApp"
//	  version: "1.0.0"
//	  port: 8080
//	  debug: false
//	database:
//	  host: "localhost"
//	  port: 3306
//	  username: "root"
//	  password: "123456"
//	redis:
//	  host: "localhost"
//	  port: 6379
//
// 注意事项:
//   - 配置文件必须是有效的 YAML 格式
//   - 文件不存在或格式错误时会返回详细的错误信息
//   - 该方法不会缓存配置，每次调用都会重新读取文件
//   - 通常应该使用 Load 方法而不是直接调用此方法
func NewConfig(file string) (*Config, error) {
	data, err := os.ReadFile(file)
	if err != nil {
		return nil, fmt.Errorf("读取配置文件失败: %w", err)
	}

	// 解析为 map 以支持动态键访问
	var rawData map[string]interface{}
	if err = yaml.Unmarshal(data, &rawData); err != nil {
		return nil, fmt.Errorf("解析配置文件失败: %w", err)
	}

	cfg := &Config{
		data: rawData,
	}

	return cfg, nil
}

// get 通过点分隔的键获取值
// 支持多层嵌套访问，逐层解析配置路径
//
// 参数:
//   - key: 配置键，使用点分隔表示嵌套关系，如 "app.database.host"
//
// 返回:
//   - interface{}: 配置值，保持原始类型
//   - bool: 配置键是否存在，true 表示存在，false 表示不存在
//
// 工作原理:
//  1. 将键按点分隔符拆分为多个部分
//  2. 从根 map 开始，逐层访问嵌套的 map
//  3. 如果任何一层不存在或类型不是 map，返回 (nil, false)
//  4. 成功访问到最后一层时，返回 (value, true)
//
// 使用示例:
//
//	// 简单键访问
//	val, exists := config.get("port")
//	// 访问: data["port"]
//
//	// 嵌套键访问
//	val, exists := config.get("app.database.host")
//	// 访问: data["app"]["database"]["host"]
//
//	// 深层嵌套访问
//	val, exists := config.get("services.payment.api.endpoint")
//	// 访问: data["services"]["payment"]["api"]["endpoint"]
//
// 注意事项:
//   - 返回 (value, exists) 可以区分"不存在"和"值为 nil"
//   - 如果中间任何一层不是 map 类型，会返回 (nil, false)
//   - 该方法不会修改配置数据，是只读操作
//   - 键名区分大小写
func (c *Config) get(key string) (interface{}, bool) {
	if c.data == nil {
		return nil, false
	}

	// 分割键，支持多层嵌套访问
	keys := strings.Split(key, ".")
	var current interface{} = c.data

	// 逐层访问嵌套的 map
	for _, k := range keys {
		// 确保当前值是 map 类型
		m, ok := current.(map[string]interface{})
		if !ok {
			return nil, false
		}

		// 获取下一层的值
		current, ok = m[k]
		if !ok {
			return nil, false
		}
	}

	return current, true
}

// allKeys 递归获取所有配置键
// 遍历配置树，返回所有叶子节点的完整路径
//
// 参数:
//   - prefix: 当前路径前缀，用于构建完整的键路径
//   - data: 当前层级的配置数据
//
// 返回:
//   - []string: 所有配置键的列表，使用点分隔表示嵌套关系
//
// 工作原理:
//  1. 遍历当前层级的所有键值对
//  2. 如果值是 map 类型，递归处理（中间节点）
//  3. 如果值不是 map 类型，添加到结果列表（叶子节点）
//  4. 使用 prefix 构建完整的键路径
//
// 使用示例:
//
//	// 配置结构:
//	// app:
//	//   name: "MyApp"
//	//   database:
//	//     host: "localhost"
//	//     port: 3306
//	//
//	// 返回结果:
//	// ["app.name", "app.database.host", "app.database.port"]
//
//	keys := config.allKeys("", config.data)
//	for _, key := range keys {
//	    fmt.Println(key)
//	}
//	// 输出:
//	// app.name
//	// app.database.host
//	// app.database.port
//
// 注意事项:
//   - 只返回叶子节点的键，不包含中间节点
//   - 返回的键顺序不保证，因为 map 是无序的
//   - 该方法是递归实现，配置层级过深可能影响性能
//   - 空 map 不会产生任何键
func (c *Config) allKeys(prefix string, data map[string]interface{}) []string {
	var keys []string
	for k, v := range data {
		fullKey := k
		if prefix != "" {
			fullKey = prefix + "." + k
		}

		if m, ok := v.(map[string]interface{}); ok {
			// 递归处理嵌套 map
			keys = append(keys, c.allKeys(fullKey, m)...)
		} else {
			keys = append(keys, fullKey)
		}
	}
	return keys
}

package database_parser

import (
	"context"
	"fmt"

	"strings"

	"github.com/LingoJack/model_infrax/internal/conf"
	"github.com/LingoJack/model_infrax/internal/infra/db_infra"
	"github.com/LingoJack/model_infrax/internal/model"
	"github.com/LingoJack/model_infrax/internal/tool"
	"github.com/samber/lo"
)

type mysqlTable struct {
	Name          string  `json:"ColumnName"`      // 表名
	Engine        string  `json:"Engine"`          // 存储引擎
	Version       int     `json:"Version"`         // 版本号
	RowFormat     string  `json:"Row_format"`      // 行格式
	Rows          int64   `json:"Rows"`            // 行数（估算值）
	AvgRowLength  int64   `json:"Avg_row_length"`  // 平均行长度
	DataLength    int64   `json:"Data_length"`     // 数据长度
	MaxDataLength int64   `json:"Max_data_length"` // 最大数据长度
	IndexLength   int64   `json:"Index_length"`    // 索引长度
	DataFree      int64   `json:"Data_free"`       // 空闲空间
	AutoIncrement *int64  `json:"Auto_increment"`  // 自增值（可能为null）
	CreateTime    *string `json:"Create_time"`     // 创建时间（可能为null）
	UpdateTime    *string `json:"Update_time"`     // 更新时间（可能为null）
	CheckTime     *string `json:"Check_time"`      // 检查时间（可能为null）
	Collation     string  `json:"Collation"`       // 字符集校对规则
	Checksum      *int64  `json:"Checksum"`        // 校验和（可能为null）
	CreateOptions string  `json:"Create_options"`  // 创建选项
	Comment       string  `json:"Comment"`         // 表注释
}

type mysqlField struct {
	Field      string  `json:"Field"`      // 字段名
	Type       string  `json:"Type"`       // 字段类型
	Collation  *string `json:"Collation"`  // 字符集校对规则（可能为null）
	Null       string  `json:"Null"`       // 是否允许为NULL（YES/NO）
	Key        string  `json:"Key"`        // 键类型（PRI/UNI/MUL等）
	Default    *string `json:"Default"`    // 默认值（可能为null）
	Extra      string  `json:"Extra"`      // 额外信息（如auto_increment）
	Privileges string  `json:"Privileges"` // 权限信息
	Comment    string  `json:"Comment"`    // 字段注释
}

// mysqlIndex MySQL索引信息结构体
type mysqlIndex struct {
	Table        string  `json:"Table"`         // 表名
	NonUnique    int     `json:"Non_unique"`    // 是否非唯一索引（0=唯一索引，1=非唯一索引）
	KeyName      string  `json:"Key_name"`      // 索引名称
	SeqInIndex   int     `json:"Seq_in_index"`  // 字段在索引中的序号（从1开始）
	ColumnName   string  `json:"Column_name"`   // 列名
	Collation    *string `json:"Collation"`     // 排序方式（A=升序，D=降序，NULL=未排序）
	Cardinality  *int64  `json:"Cardinality"`   // 索引中唯一值的数量估算（可能为null）
	SubPart      *int    `json:"Sub_part"`      // 索引前缀长度（可能为null）
	Packed       *string `json:"Packed"`        // 关键字如何被压缩（可能为null）
	Null         string  `json:"Null"`          // 列是否可以包含NULL值
	IndexType    string  `json:"Index_type"`    // 索引类型（BTREE/HASH/FULLTEXT/SPATIAL）
	Comment      string  `json:"Comment"`       // 索引注释
	IndexComment string  `json:"Index_comment"` // 索引注释（创建索引时的COMMENT）
	Visible      string  `json:"Visible"`       // 索引是否可见（YES/NO）
	Expression   *string `json:"Expression"`    // 表达式索引的表达式（可能为null）
}

// Parse 获取所有表名
func Parse(ctx context.Context) (schemas []model.Schema, err error) {
	var tables []mysqlTable
	err = db_infra.ExecSql(ctx, &tables, "show table status")
	if err != nil {
		return nil, fmt.Errorf("查询数据库表失败: %w", err)
	}

	// 使用 lo.Map 遍历所有表并构建 Schema
	schemas = lo.Map(tables, func(table mysqlTable, index int) model.Schema {
		tableName := table.Name
		tableComment := table.Comment

		// 查询表的所有字段信息
		var fields []mysqlField
		err = db_infra.ExecSql(ctx, &fields, "show full fields from ?", tableName)
		if err != nil {
			panic(err)
		}

		// 构建列信息和列名到列的映射
		var columns []model.Column
		name2Column := make(map[string]model.Column) // 初始化 map
		lo.ForEach(fields, func(field mysqlField, index int) {
			column := model.Column{
				ColumnName:      field.Field,
				Collate:         tool.Stringify(field.Collation), // Stringify 已经处理了 nil 指针
				Comment:         field.Comment,
				Type:            field.Type,
				Default:         field.Default, // 设置默认值
				IsAutoIncrement: strings.Contains(field.Extra, "auto_increment"),
				IsNullable:      field.Null == "YES",
			}
			columns = append(columns, column)
			name2Column[column.ColumnName] = column
		})

		// 查询表的所有索引信息
		var mysqlIndexes []mysqlIndex
		err = db_infra.ExecSql(ctx, &mysqlIndexes, "show index from ?", tableName)
		if err != nil {
			panic(err)
		}

		// 构建索引名到列的映射
		indexName2Columns := make(map[string][]model.Column)
		lo.ForEach(mysqlIndexes, func(index mysqlIndex, i int) {
			indexName2Columns[index.KeyName] = append(indexName2Columns[index.KeyName], name2Column[index.ColumnName])
		})

		// 构建索引名到索引对象的映射，用于后续查找
		inexName2Index := make(map[string]model.Index)

		var primaryKey model.Index
		var indexes []model.Index

		// 将 map 转换为 Index 切片
		indexes = lo.MapToSlice(indexName2Columns, func(key string, value []model.Column) model.Index {
			idx := model.Index{
				IndexName: key,
				Columns:   value,
			}
			// 识别主键
			if key == "PRIMARY" {
				primaryKey = idx
			}
			inexName2Index[key] = idx
			return idx
		})

		// 提取唯一索引
		var uniqueIndexes []model.Index
		lo.ForEach(mysqlIndexes, func(index mysqlIndex, i int) {
			if index.NonUnique == 0 {
				uniqueIndexes = append(uniqueIndexes, inexName2Index[index.KeyName])
			}
		})

		// 找到所有索引的列
		var indexedColumns []model.Column
		lo.ForEach(indexes, func(index model.Index, i int) {
			indexedColumns = append(indexedColumns, index.Columns...)
		})

		// 找到所有唯一索引的列
		var uniqueIndexedColumns []model.Column
		lo.ForEach(uniqueIndexes, func(index model.Index, i int) {
			uniqueIndexedColumns = append(uniqueIndexedColumns, index.Columns...)
		})

		// 找到所有主键的列
		var primaryKeyColumns []model.Column
		lo.ForEach(primaryKey.Columns, func(column model.Column, i int) {
			primaryKeyColumns = append(primaryKeyColumns, column)
		})

		// 标记索引列：直接在 columns 切片中更新
		for i := range columns {
			columnName := columns[i].ColumnName

			// 检查是否为索引列
			for _, indexedCol := range indexedColumns {
				if indexedCol.ColumnName == columnName {
					columns[i].IsIndexed = true
					break
				}
			}

			// 检查是否为唯一索引列
			for _, uniqueCol := range uniqueIndexedColumns {
				if uniqueCol.ColumnName == columnName {
					columns[i].IsUnique = true
					break
				}
			}

			// 检查是否为主键列
			for _, pkCol := range primaryKeyColumns {
				if pkCol.ColumnName == columnName {
					columns[i].IsPrimaryKey = true
					break
				}
			}
		}

		// 构建 Schema 对象
		return model.Schema{
			Name:        tableName,
			Comment:     tableComment,
			Columns:     columns,
			PrimaryKey:  primaryKey,
			Indexes:     indexes,
			UniqueIndex: uniqueIndexes,
		}
	})

	return
}

// Filter 根据配置文件过滤表
func Filter(schemas []model.Schema) (filtered []model.Schema) {
	if conf.ValueBool("generate_config.all_tables") {
		filtered = schemas
		return
	}
	neededTableNames := conf.ValueStrSlice("generate_config.table_names")
	filtered = lo.Filter(schemas, func(schema model.Schema, index int) bool {
		return lo.Contains(neededTableNames, schema.Name)
	})
	return
}

