	err = tmpl.Execute(&buf, templateData)
	if err != nil {
		return fmt.Errorf("执行模板失败: %w", err)
	}

	// 创建输出文件并写入格式化后的代码
	err = os.WriteFile(filePath, []byte(tool.FormatGoCode(buf.String())), 0644)
	if err != nil {
		return fmt.Errorf("写入输出文件失败: %w", err)
	}

	log.Printf("成功生成文件: %s\n", filePath)
	return nil
