}

func GenerateModelOneByOne(schemas []model.Schema) (err error) {
	for _, schema := range schemas {
		fileName := fmt.Sprintf("%s.go", schema.Name)
		err = GenerateModelAllInOne([]model.Schema{schema}, fileName)
		if err != nil {
			return err
		}
	}
	return nil
}

