func (dao *{{ $daoName }}) SelectListWithAppendConditionFunc(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}, appendConditionFunc func(ctx context.Context, db *gorm.DB) *gorm.DB) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
