// ==================== 原生SQL执行方法 ====================

// ExecSql 执行原生SQL查询
// 参数:
//   - ctx: 上下文对象
//   - recvPtr: 接收查询结果的指针（必须是指针类型）
//     - 查询单条记录时传入结构体指针，如 &entity.TNode{}
//     - 查询多条记录时传入 slice 指针，如 &[]*entity.TNode{}
//   - sql: SQL语句，支持占位符 ?
//   - args: SQL参数，按顺序对应 SQL 中的占位符
// 返回:
//   - error: 错误信息，查询失败或记录不存在时返回错误
// 使用示例:
//   // 示例1: 查询单条记录
//   var result entity.{{ $entityName }}
//   err := dao.ExecSql(ctx, &result, "SELECT * FROM {{ $schema.Name }} WHERE id = ?", 1)
//   if err != nil {
//       // 处理错误（包括记录不存在的情况）
//       return err
//   }
//
//   // 示例2: 查询多条记录
//   var resultList []*entity.{{ $entityName }}
//   err := dao.ExecSql(ctx, &resultList, "SELECT * FROM {{ $schema.Name }} WHERE skill_id = ?", "skill123")
//   if err != nil {
//       return err
//   }
//
//   // 示例3: 查询聚合结果
//   type CountResult struct {
//       SkillId string `gorm:"column:skill_id"`
//       Count   int64  `gorm:"column:count"`
//   }
//   var countList []*CountResult
//   err := dao.ExecSql(ctx, &countList, "SELECT skill_id, COUNT(*) as count FROM {{ $schema.Name }} GROUP BY skill_id")
//
// 注意事项:
//   - recvPtr 必须传指针，否则无法接收查询结果
//   - 查询单条记录时，如果返回多行，只会取第一行
//   - 查询多条记录时，如果没有结果，会返回空 slice（不是 nil）
//   - 结构体字段需要通过 gorm 标签与数据库列名匹配
//   - 如果取了别名，gorm 的 column 标签需要和 SQL 取的别名一致
//   - gorm 的 column 标签默认为下划线格式
func (dao *{{ $daoName }}) ExecSql(ctx context.Context, recvPtr any, sql string, args ...any) error {
	return dao.WithContext(ctx).Raw(sql, args...).Scan(recvPtr).Error
}

// ==================== 辅助方法 ====================

// getValidOrderByFields 获取允许排序的字段白名单
// 返回:
//   - map[string]bool: 字段白名单，key为字段名，value为true表示允许排序
func (dao *{{ $daoName }}) getValidOrderByFields() map[string]bool {
	return map[string]bool{
{{- range $schema.Columns }}
		"{{ .ColumnName }}": true,
{{- end }}
	}
}

// isValidOrderBy 验证排序字符串是否安全（基于字段白名单）
// 支持格式:
//   - 单字段: id DESC
//   - 多字段: id DESC, createTime ASC
// 参数:
//   - orderBy: 排序字符串
// 返回:
//   - true: 排序字符串合法且所有字段都在白名单中
//   - false: 排序字符串不合法或包含非白名单字段
func (dao *{{ $daoName }}) isValidOrderBy(orderBy string) bool {
	if orderBy == "" {
		return false
	}

	// 获取字段白名单
	validFields := dao.getValidOrderByFields()

	// 按逗号分割多个排序字段
	orderParts := strings.Split(orderBy, ",")

	for _, part := range orderParts {
		part = strings.TrimSpace(part)
		if part == "" {
			return false
		}

		// 按空格分割字段名和排序方向
		tokens := strings.Fields(part)
		if len(tokens) == 0 || len(tokens) > 2 {
			// 格式错误: 必须是 "字段名" 或 "字段名 方向"
			return false
		}

		// 验证字段名是否在白名单中
		fieldName := tokens[0]
		if !validFields[fieldName] {
			// 字段不在白名单中
			return false
		}

		// 如果指定了排序方向，验证是否为 ASC 或 DESC
		if len(tokens) == 2 {
			direction := strings.ToUpper(tokens[1])
			if direction != "ASC" && direction != "DESC" {
				// 排序方向无效
				return false
			}
		}
	}

	return true
}

{{- end }}

{{- /* Dao 层代码生成模板 */ -}}
package {{ .DaoPackageName }}

import (
	"context"
	"fmt"

	"strings"

	"gorm.io/gorm"
	igorm "git.woa.com/tencent-cloud-platform/go-module/itea-gorm"	// itea-go 框架提供的 db 注入
)

{{- range $schema := .Schemas }}
{{- $entityName := $schema.Name | ToPascalCase }}
{{- $daoName := printf "%sDao" $entityName }}
{{- $dtoName := printf "%sDto" $entityName }}
{{- $varName := $schema.Name | ToCamelCase }}

// {{ $daoName }} {{ $schema.Comment }}的Dao实现
type {{ $daoName }} struct {
	// itea-go 框架提供的 db 注入
	igorm.BaseDao `wired:"true"`
}

func (dao *{{ $daoName }} ) Database() string {
    // TODO 补全 db 名称
	return "@database_name"
}

// ==================== 事务支持方法 ====================

// WithTx 使用指定的事务对象创建新的 DAO 实例
// 参数:
//   - tx: GORM事务对象
// 返回:
//   - *{{ $daoName }}: 使用事务的新 DAO 实例
// 使用示例:
//   db.Transaction(func(tx *gorm.DB) error {
//       txDao := dao.WithTx(tx)
//       return txDao.Insert(ctx, poBean)
//   })
func (dao *{{ $daoName }}) WithTx(tx *gorm.DB) *{{ $daoName }} {
	newDao := &{{ $daoName }}{}
	newDao.DB = tx
	return newDao
}

// Transaction 在事务中执行操作
// 参数:
//   - ctx: 上下文对象
//   - fn: 事务处理函数，接收使用事务的 DAO 实例
// 返回:
//   - error: 错误信息
// 说明:
//   - 自动管理事务的开始、提交和回滚
//   - 如果 fn 返回 error，事务会自动回滚
//   - 如果 fn 执行成功，事务会自动提交
// 使用示例:
//   err := dao.Transaction(ctx, func(txDao *{{ $daoName }}) error {
//       if err := txDao.Insert(ctx, poBean1); err != nil {
//           return err
//       }
//       if err := txDao.Insert(ctx, poBean2); err != nil {
//           return err
//       }
//       return nil
//   })
func (dao *{{ $daoName }}) Transaction(ctx context.Context, fn func(*{{ $daoName }}) error) error {
	return dao.WithContext(ctx).Transaction(func(tx *gorm.DB) error {
		txDao := &{{ $daoName }}{}
		txDao.DB = tx
		return fn(txDao)
	})
}

// ==================== 查询条件构建 ====================

// build{{ $entityName }}QueryCondition 构建查询条件
// 参数:
//   - db: GORM数据库连接实例
//   - queryDto: 查询条件Dto对象
// 返回:
//   - *gorm.DB: 应用了查询条件的数据库连接
// 说明:
//   - 支持精确匹配、模糊查询、IN查询、范围查询等多种查询方式
//   - 零值字段会被忽略，不会作为查询条件
//   - IN 查询条件校验规则:
//     1. List 为 nil: 不添加该查询条件（正常情况，表示不按此字段过滤）
//     2. List 不为 nil 且长度 > 0: 添加 IN 查询条件
//     3. List 不为 nil 但长度 = 0: 返回错误，因为空列表的 IN 查询没有意义，应提前发现此问题
func (dao *{{ $daoName }}) build{{ $entityName }}QueryCondition(db *gorm.DB, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) *gorm.DB {
	if queryDto == nil {
		return db
	}

	// 基础字段精确查询
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if eq $goType "string" }}
	if queryDto.{{ $fieldName }} != "" {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "int" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "uint64" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "int64" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "bool" }}
	// bool类型字段：false也是有效值，这里简化处理，如需区分未设置和false，Dto应使用*bool
	if queryDto.{{ $fieldName }} {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "time.Time" }}
	if !queryDto.{{ $fieldName }}.IsZero() {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*string" }}
	if queryDto.{{ $fieldName }} != nil && *queryDto.{{ $fieldName }} != "" {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*int" }}
	if queryDto.{{ $fieldName }} != nil {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*time.Time" }}
	if queryDto.{{ $fieldName }} != nil && !queryDto.{{ $fieldName }}.IsZero() {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else }}
	if queryDto.{{ $fieldName }} != nil {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- end }}
{{- end }}

	// 模糊查询条件
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if eq $goType "string" }}
	if queryDto.{{ $fieldName }}Fuzzy != "" {
		db = db.Where("{{ .ColumnName }} LIKE ?", "%"+queryDto.{{ $fieldName }}Fuzzy+"%")
	}
{{- else if eq $goType "*string" }}
	if queryDto.{{ $fieldName }}Fuzzy != nil && *queryDto.{{ $fieldName }}Fuzzy != "" {
		db = db.Where("{{ .ColumnName }} LIKE ?", "%"+*queryDto.{{ $fieldName }}Fuzzy+"%")
	}
{{- end }}
{{- end }}

	// 日期范围查询
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if or (eq $goType "time.Time") (eq $goType "*time.Time") }}
	if !queryDto.{{ $fieldName }}Start.IsZero() {
		db = db.Where("{{ .ColumnName }} >= ?", queryDto.{{ $fieldName }}Start)
	}
	if !queryDto.{{ $fieldName }}End.IsZero() {
		db = db.Where("{{ .ColumnName }} < DATE_ADD(?, INTERVAL 1 DAY)", queryDto.{{ $fieldName }}End)
	}
{{- end }}
{{- end }}

	// IN 查询条件
{{- range $schema.Columns }}
{{- if .IsIndexed }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
	// 校验 {{ $fieldName }}List: 如果不为 nil 但长度为 0，则报错
	if queryDto != nil && queryDto.{{ $fieldName }}List != nil {
		if len(queryDto.{{ $fieldName }}List) > 0 {
            db = db.Where("{{ .ColumnName }} IN ?", queryDto.{{ $fieldName }}List)
		}
	}
{{- end }}
{{- end }}

	return db
}

// ==================== 基础查询方法 ====================

// SelectList 查询列表
// 参数:
//   - ctx: 上下文对象
//   - queryDto: 查询条件Dto对象，支持分页、排序、多条件查询
// 返回:
//   - []*{{ $.PoPackageName }}.{{ $entityName }}: 查询结果列表
//   - error: 错误信息
// 说明:
//   - IN 查询条件校验规则:
//     1. List 为 nil: 不添加该查询条件（正常情况，表示不按此字段过滤）
//     2. List 不为 nil 且长度 > 0: 添加 IN 查询条件
//     3. List 不为 nil 但长度 = 0: 返回错误，因为空列表的 IN 查询没有意义，应提前发现此问题
func (dao *{{ $daoName }}) SelectList(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	var resultList []*{{ $.PoPackageName }}.{{ $entityName }}
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).WithContext(ctx)

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	// 排序
	if queryDto != nil && queryDto.OrderBy != "" {
		if dao.isValidOrderBy(queryDto.OrderBy) {
		    // NOCA:sql_injection(在`isValidOrderBy`方法做过排序的白名单校验)
			db = db.Order(queryDto.OrderBy)
		}
	}

	// 分页
	if queryDto != nil && queryDto.PageSize > 0 {
		db = db.Offset(queryDto.PageOffset * queryDto.PageSize).Limit(queryDto.PageSize)
	}

	err := db.Find(&resultList).Error
	return resultList, err
}

// SelectCount 查询数量
// 参数:
//   - ctx: 上下文对象
//   - queryDto: 查询条件Dto对象
// 返回:
//   - int64: 符合条件的记录数量
//   - error: 错误信息
// 说明:
//   - IN 查询条件校验规则:
//     1. List 为 nil: 不添加该查询条件（正常情况，表示不按此字段过滤）
//     2. List 不为 nil 且长度 > 0: 添加 IN 查询条件
//     3. List 不为 nil 但长度 = 0: 返回错误，因为空列表的 IN 查询没有意义，应提前发现此问题
func (dao *{{ $daoName }}) SelectCount(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) (int64, error) {
	var count int64
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).WithContext(ctx)

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	err := db.Count(&count).Error
	return count, err
}

// SelectListWithAppendConditionFunc 查询列表（支持自定义条件函数）
// 参数:
//   - ctx: 上下文对象
//   - queryDto: 查询条件Dto对象，支持分页、排序、多条件查询
//   - appendConditionFunc: 自定义条件函数，用于添加额外的查询条件
//     - 如果为 nil，则不添加额外条件
//     - 函数签名: func(ctx context.Context, db *gorm.DB) *gorm.DB
// 返回:
//   - []*{{ $.PoPackageName }}.{{ $entityName }}: 查询结果列表
//   - error: 错误信息
// 使用示例:
//   // 示例1: 添加复杂的自定义条件
//   resultList, err := dao.SelectListWithAppendConditionFunc(ctx, queryDto, func(ctx context.Context, db *gorm.DB) *gorm.DB {
//       return db.Where("status IN (?, ?)", "active", "pending").
//                 Where("created_at > ?", time.Now().AddDate(0, -1, 0))
//   })
//
//   // 示例2: 不添加额外条件
//   resultList, err := dao.SelectListWithAppendConditionFunc(ctx, queryDto, nil)
//
// 说明:
//   - 自定义条件函数在基础查询条件、排序和分页之后执行
//   - 适用于需要动态添加复杂查询条件的场景
//   - IN 查询条件校验规则同 SelectList 方法
func (dao *{{ $daoName }}) SelectListWithAppendConditionFunc(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}, appendConditionFunc func(ctx context.Context, db *gorm.DB) *gorm.DB) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	var resultList []*{{ $.PoPackageName }}.{{ $entityName }}
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).WithContext(ctx)

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	// 排序
	if queryDto != nil && queryDto.OrderBy != "" {
		if dao.isValidOrderBy(queryDto.OrderBy) {
			// NOCA:sql_injection(在`isValidOrderBy`方法做过排序的白名单校验)
			db = db.Order(queryDto.OrderBy)
		}
	}

	// 分页
	if queryDto != nil && queryDto.PageSize > 0 {
		db = db.Offset(queryDto.PageOffset * queryDto.PageSize).Limit(queryDto.PageSize)
	}

	// 应用自定义条件函数
	if appendConditionFunc != nil {
		db = appendConditionFunc(ctx, db)
	}

	err := db.Find(&resultList).Error
	return resultList, err
}

// SelectCountWithAppendConditionFunc 查询数量（支持自定义条件函数）
// 参数:
//   - ctx: 上下文对象
//   - queryDto: 查询条件Dto对象
//   - appendConditionFunc: 自定义条件函数，用于添加额外的查询条件
//     - 如果为 nil，则不添加额外条件
//     - 函数签名: func(ctx context.Context, db *gorm.DB) *gorm.DB
// 返回:
