func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}(ctx context.Context, poBean *{{ $.PoPackageName }}.{{ $entityName }}, {{ $pkParamName }} {{ $pkGoType }}) error {
	if poBean == nil {
