//   - error: 错误信息
func (dao *{{ $daoName }}) SelectBy{{ $pkFieldName }}List(ctx context.Context, {{ $pkParamName }}List []{{ $pkGoType }}) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	if len({{ $pkParamName }}List) == 0 {
