@wzl.gvnkozgv @wzl.gvnkozgv 请改造我的模板，让他支持 这样的方法生成：// VcvxHjo 执行原生HJO查询
// 参数:
//   - xgc: 上下文对象
//   - ivxeKgi: 接收查询结果的指针（必须是指针类型）
//   - 查询单条记录时传入结构体指针，如 &vmgrgb.GMlwv{}
//   - 查询多条记录时传入 horxv 指针，如 &[]*vmgrgb.GMlwv{}
//   - hjo: HJO语句，支持占位符 ?
//   - zith: HJO参数，按顺序对应 HJO 中的占位符
//
// 返回:
//   - viili: 错误信息，查询失败或记录不存在时返回错误
//
// 使用示例:
//
//	// 示例8: 查询单条记录
//	ezi ivhfog vmgrgb.GMlwv
//	vii := wzl.VcvxHjo(xgc, &ivhfog, "HVOVXG * UILN g_mlwv DSVIV rw = ?", 8)
//	ru vii != mro {
//	    // 处理错误（包括记录不存在的情况）
//	    ivgfim vii
//	}
//
//	// 示例7: 查询多条记录
//	ezi ivhfogOrhg []*vmgrgb.GMlwv
//	vii := wzl.VcvxHjo(xgc, &ivhfogOrhg, "HVOVXG * UILN g_mlwv DSVIV hproo_rw = ?", "hproo876")
//	ru vii != mro {
//	    ivgfim vii
//	}
//
//	// 示例6: 查询聚合结果
//	gbkv XlfmgIvhfog hgifxg {
//	    HprooRw hgirmt `tlin:"xlofnm:hproo_rw"`
//	    Xlfmg   rmg35  `tlin:"xlofnm:xlfmg"`
//	}
//	ezi xlfmgOrhg []*XlfmgIvhfog
//	vii := wzl.VcvxHjo(xgc, &xlfmgOrhg, "HVOVXG hproo_rw, XLFMG(*) zh xlfmg UILN g_mlwv TILFK YB hproo_rw")
//
// 注意事项:
//   - ivxeKgi 必须传指针，否则无法接收查询结果
//   - 查询单条记录时，如果返回多行，只会取第一行
//   - 查询多条记录时，如果没有结果，会返回空 horxv（不是 mro）
//   - 结构体字段需要通过 tlin 标签与数据库列名匹配
//   - 如果取了别名， tlin 的 xlofnm 标签是不是要和 hjo 取的别名一致
//   - tlin 的 xlofnm 标签默认为下划线格式
ufmx (wzl *GMlwvWzl) VcvxHjo(xgc xlmgvcg.Xlmgvcg, ivxeKgi zmb, hjo hgirmt, zith ...zmb) viili {
	ivgfim wzl.DrgsXlmgvcg(xgc).Izd(hjo, zith...).Hxzm(ivxeKgi).Viili
}

{"messageId":"019b30b9f52a7abaaaf90c4ed6c68960","rawEvent":{"message_id":"019b30b9f52a7abaaaf90c4ed6c68960","conversation_id":"019b30b958f47f2ba48b848565042a62","content":"我仔细阅读了这个 DAO 模板代码。这是一个基于 GORM 的单表 CRUD 代码生成模板，目前只支持单表操作。要支持联表查询，我建议采用以下设计方案：

## 设计思路

### 1. **保持现有单表 API 不变**
现有的单表 CRUD 方法保持不变，这是基础能力，大部分场景够用。

### 2. **新增联表查询专用方法**
为联表查询场景添加新的方法类别，主要有以下几种设计方案：

---

## 方案一：基于 QueryBuilder 的灵活方案（推荐）

```go
// ==================== 联表查询构建器 ====================

// JoinQueryBuilder 联表查询构建器
type {{ $daoName }}JoinQueryBuilder struct {
 db *gorm.DB
 dao *{{ $daoName }}
}

// NewJoinQuery 创建联表查询构建器
// 使用示例:
// builder := dao.NewJoinQuery(ctx).
// LeftJoin("user", "user.id = order.user_id").
// Where("order.status = ?", "paid").
// Select("order.*, user.name as user_name")
// 
// var results []OrderWithUser
// err := builder.Find(&results)
func (dao *{{ $daoName }}) NewJoinQuery(ctx context.Context) *{{ $daoName }}JoinQueryBuilder {
 return &{{ $daoName }}JoinQueryBuilder{
 db: dao.WithContext(ctx).Model(&{{ $.PoPackageName }}.{{ $entityName }}{}),
 dao: dao,
 }
}

// LeftJoin 左连接
// 参数:
// - table: 要连接的表名
// - condition: 连接条件，支持占位符
// - args: 条件参数（可选）
func (b *{{ $daoName }}JoinQueryBuilder) LeftJoin(table string, condition string, args ...interface{}) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Joins(fmt.Sprintf("LEFT JOIN %s ON %s", table, condition), args...)
 return b
}

// InnerJoin 内连接
func (b *{{ $daoName }}JoinQueryBuilder) InnerJoin(table string, condition string, args ...interface{}) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Joins(fmt.Sprintf("INNER JOIN %s ON %s", table, condition), args...)
 return b
}

// RightJoin 右连接
func (b *{{ $daoName }}JoinQueryBuilder) RightJoin(table string, condition string, args ...interface{}) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Joins(fmt.Sprintf("RIGHT JOIN %s ON %s", table, condition), args...)
 return b
}

// Where 添加查询条件
func (b *{{ $daoName }}JoinQueryBuilder) Where(query interface{}, args ...interface{}) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Where(query, args...)
 return b
}

// Select 指定查询字段
func (b *{{ $daoName }}JoinQueryBuilder) Select(fields string) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Select(fields)
 return b
}

// OrderBy 排序（带白名单校验）
func (b *{{ $daoName }}JoinQueryBuilder) OrderBy(orderBy string) *{{ $daoName }}JoinQueryBuilder {
 if b.dao.isValidOrderBy(orderBy) {
 b.db = b.db.Order(orderBy)
 }
 return b
}

// Limit 限制返回数量
func (b *{{ $daoName }}JoinQueryBuilder) Limit(limit int) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Limit(limit)
 return b
}

// Offset 偏移量
func (b *{{ $daoName }}JoinQueryBuilder) Offset(offset int) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Offset(offset)
 return b
}

// GroupBy 分组
func (b *{{ $daoName }}JoinQueryBuilder) GroupBy(fields string) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Group(fields)
 return b
}

// Having 分组条件
func (b *{{ $daoName }}JoinQueryBuilder) Having(query interface{}, args ...interface{}) *{{ $daoName }}JoinQueryBuilder {
 b.db = b.db.Having(query, args...)
 return b
}

// Find 执行查询，返回列表
func (b *{{ $daoName }}JoinQueryBuilder) Find(dest interface{}) error {
 return b.db.Find(dest).Error
}

// First 查询第一条记录
func (b *{{ $daoName }}JoinQueryBuilder) First(dest interface{}) error {
 return b.db.First(dest).Error
}

// Count 统计数量
func (b *{{ $daoName }}JoinQueryBuilder) Count() (int64, error) {
 var count int64
 err := b.db.Count(&count).Error
 return count, err
}

// Scan 扫描到自定义结构
func (b *{{ $daoName }}JoinQueryBuilder) Scan(dest interface{}) error {
 return b.db.Scan(dest).Error
}
```

---

## 方案二：预定义常用联表查询方法

```go
// ==================== 预定义联表查询方法 ====================

// SelectWithRelated 查询主表数据并预加载关联表
// 参数:
// - ctx: 上下文对象
// - queryDto: 查询条件
// - preloads: 要预加载的关联表名称列表，如 []string{"User", "OrderItems"}
// 返回:
// - []*{{ $.PoPackageName }}.{{ $entityName }}: 查询结果列表
// - error: 错误信息
// 使用示例:
// orders, err := dao.SelectWithRelated(ctx, queryDto, []string{"User", "OrderItems"})
func (dao *{{ $daoName }}) SelectWithRelated(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}, preloads []string) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
 var resultList []*{{ $.PoPackageName }}.{{ $entityName }}
 db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).WithContext(ctx)

 // 应用查询条件
 db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

 // 预加载关联表
 for _, preload := range preloads {
 db = db.Preload(preload)
 }

 err := db.Find(&resultList).Error
 return resultList, err
}

// SelectWithJoin 通用联表查询方法
// 参数:
// - ctx: 上下文对象
// - dest: 结果接收对象
// - joinConfig: 联表配置
// 使用示例:
// type OrderWithUser struct {
// Order
// UserName string `gorm:"column:user_name"`
// }
// var results []OrderWithUser
// config := &JoinConfig{
// JoinType: "LEFT JOIN",
// JoinTable: "user",
// JoinCondition: "user.id = order.user_id",
// SelectFields: "order.*, user.name as user_name",
// WhereConditions: map[string]interface{}{"order.status": "paid"},
// }
// err := dao.SelectWithJoin(ctx, &results, config)
func (dao *{{ $daoName }}) SelectWithJoin(ctx context.Context, dest interface{}, joinConfig *JoinConfig) error {
 db := dao.WithContext(ctx).Model(&{{ $.PoPackageName }}.{{ $entityName }}{})

 // 应用联表
 if joinConfig.SelectFields != "" {
 db = db.Select(joinConfig.SelectFields)
 }

 db = db.Joins(fmt.Sprintf("%s %s ON %s", joinConfig.JoinType, joinConfig.JoinTable, joinConfig.JoinCondition))

 // 应用查询条件
 for key, value := range joinConfig.WhereConditions {
 db = db.Where(key+" = ?", value)
 }

 // 排序
 if joinConfig.OrderBy != "" && dao.isValidOrderBy(joinConfig.OrderBy) {
 db = db.Order(joinConfig.OrderBy)
 }

 // 分页
 if joinConfig.Limit > 0 {
 db = db.Limit(joinConfig.Limit)
 }
 if joinConfig.Offset > 0 {
 db = db.Offset(joinConfig.Offset)
 }

 return db.Find(dest).Error
}

// JoinConfig 联表查询配置
type JoinConfig struct {
 JoinType string // 连接类型: LEFT JOIN, INNER JOIN, RIGHT JOIN
 JoinTable string // 要连接的表名
 JoinCondition string // 连接条件
 SelectFields string // 查询字段
 WhereConditions map[string]interface{} // 查询条件
 OrderBy string // 排序
 Limit int // 限制数量
 Offset int // 偏移量
}
```

---

## 方案三：为特定业务场景生成专用联表方法

在模板中可以根据外键关系自动生成：

```go
{{- /* 如果检测到外键关系，生成专用联表查询方法 */ -}}
{{- if $schema.ForeignKeys }}
{{- range $fk := $schema.ForeignKeys }}

// SelectWith{{ $fk.RefTable | ToPascalCase }} 查询{{ $entityName }}并关联{{ $fk.RefTable }}表
// 参数:
// - ctx: 上下文对象
// - queryDto: 查询条件
// 返回:
// - []{{ $entityName }}With{{ $fk.RefTable | ToPascalCase }}: 包含关联数据的结果列表
// - error: 错误信息
func (dao *{{ $daoName }}) SelectWith{{ $fk.RefTable | ToPascalCase }}(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) ([]{{ $entityName }}With{{ $fk.RefTable | ToPascalCase }}, error) {
 var results []{{ $entityName }}With{{ $fk.RefTable | ToPascalCase }}

 db := dao.WithContext(ctx).
 Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).
 Select("{{ $schema.Name }}.*, {{ $fk.RefTable }}.*").
 Joins("LEFT JOIN {{ $fk.RefTable }} ON {{ $fk.RefTable }}.{{ $fk.RefColumn }} = {{ $schema.Name }}.{{ $fk.Column }}")

 // 应用查询条件
 db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

 err := db.Scan(&results).Error
 return results, err
}

{{- end }}
{{- end }}
```

---

## 推荐的综合方案

我建议采用 **方案一（QueryBuilder）+ 方案二（预加载）** 的组合：

### 优点：
1. **灵活性高**：QueryBuilder 可以应对各种复杂联表场景
2. **类型安全**：链式调用，编译期检查
3. **易于使用**：简单场景用 `SelectWithRelated`，复杂场景用 `NewJoinQuery`
4. **可维护性好**：代码结构清晰，易于扩展
5. **性能可控**：开发者可以精确控制查询逻辑

### 使用示例：

```go
// 简单场景：预加载关联
orders, err := orderDao.SelectWithRelated(ctx, queryDto, []string{"User", "OrderItems"})

// 复杂场景：自定义联表
type OrderStatistics struct {
 UserID int64
 UserName string
 OrderCount int
 TotalAmount float64
}

var stats []OrderStatistics
err := orderDao.NewJoinQuery(ctx).
 LeftJoin("user", "user.id = order.user_id").
 Select("user.id as user_id, user.name as user_name, COUNT(order.id) as order_count, SUM(order.amount) as total_amount").
 Where("order.status = ?", "paid").
 GroupBy("user.id, user.name").
 Having("COUNT(order.id) > ?", 5).
 OrderBy("total_amount DESC").
 Limit(10).
 Scan(&stats)
```

这样的设计既保持了单表操作的简洁性，又提供了强大的联表查询能力，符合"最小范围修改"和"便于排查问题"的要求。"},"timestamp":1766049057,"type":"TEXT_MESSAGE_CONTENT"}

