//   - error: 错误信息
func (dao *{{ $daoName }}) SelectBy{{ $pkFieldName }}(ctx context.Context, {{ $pkParamName }} {{ $pkGoType }}) (*{{ $.PoPackageName }}.{{ $entityName }}, error) {
