func (dao *{{ $daoName }}) UpdateBy{{ $methodSuffix }}WithMap(ctx context.Context
{{- range $i, $col := $indexColumns }}, {{ $col.ColumnName | ToSafeParamName }} {{ $col | GetGoType }}{{ end }}, updatedMap map[string]interface{}) error {
