func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}WithCondition(ctx context.Context, poBean *{{ $.PoPackageName }}.{{ $entityName }}, {{ $pkParamName }} {{ $pkGoType }}, conditionMap map[string]interface{}) error {
