func (dao *{{ $daoName }}) DeleteBy{{ $pkFieldName }}(ctx context.Context, {{ $pkParamName }} {{ $pkGoType }}) error {
	return dao.WithContext(ctx).Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }}).Delete(&{{ $.PoPackageName }}.{{ $entityName }}{}).Error
