{{- /* 跳过主键索引，避免重复生成 */ -}}
{{- if ne $index.IndexName "PRIMARY" }}

// ==================== 唯一索引 {{ $index.IndexName }} 方法 ====================

// SelectBy{{ $methodSuffix }} 根据唯一索引{{ $index.IndexName }}查询单条记录
// 参数:
//   - ctx: 上下文对象
{{- range $i, $col := $indexColumns }}
//   - {{ $col.ColumnName | ToSafeParamName }}: {{ $col.Comment }}
{{- end }}
// 返回:
