// 行为说明:
//   - 使用 map 可以显式指定要更新的字段，包括零值字段
//   - 提供最灵活的更新控制方式
func (dao *{{ $daoName }}) UpdateBy{{ $methodSuffix }}WithMapAndCondition(ctx context.Context
{{- range $i, $col := $indexColumns }}, {{ $col.ColumnName | ToSafeParamName }} {{ $col | GetGoType }}{{ end }}, updatedMap map[string]interface{}, conditionMap map[string]interface{}) error {
	if len(updatedMap) == 0 {
		return fmt.Errorf("更新字段不能为空")
	}
	db := dao.WithContext(ctx).Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).Where("{{ range $i, $col := $indexColumns }}{{ if $i }} AND {{ end }}{{ $col.ColumnName }} = ?{{ end }}"
{{- range $col := $indexColumns }}, {{ $col.ColumnName | ToSafeParamName }}{{ end }})

	// 应用额外的条件
	for key, value := range conditionMap {
		db = db.Where(key+" = ?", value)
	}

	return db.Updates(updatedMap).Error
}

// DeleteBy{{ $methodSuffix }} 根据索引{{ $index.IndexName }}删除
// 参数:
//   - ctx: 上下文对象
{{- range $col := $indexColumns }}
//   - {{ $col.ColumnName | ToSafeParamName }}: {{ $col.Comment }}
{{- end }}
// 返回:
//   - error: 错误信息
// 说明:
//   - 注意: 该索引不是唯一键，可能会删除多条记录
func (dao *{{ $daoName }}) DeleteBy{{ $methodSuffix }}(ctx context.Context
{{- range $i, $col := $indexColumns }}, {{ $col.ColumnName | ToSafeParamName }} {{ $col | GetGoType }}{{ end }}) error {
	return dao.WithContext(ctx).Where("{{ range $i, $col := $indexColumns }}{{ if $i }} AND {{ end }}{{ $col.ColumnName }} = ?{{ end }}"
{{- range $col := $indexColumns }}, {{ $col.ColumnName | ToSafeParamName }}{{ end }}).Delete(&{{ $.PoPackageName }}.{{ $entityName }}{}).Error
}

{{- end }}
{{- end }}
{{- end }}

// ==================== 辅助方法 ====================

// getValidOrderByFields 获取允许排序的字段白名单
// 返回:
//   - map[string]bool: 字段白名单，key为字段名，value为true表示允许排序
func (dao *{{ $daoName }}) getValidOrderByFields() map[string]bool {
	return map[string]bool{
{{- range $schema.Columns }}
		"{{ .ColumnName }}": true,
{{- end }}
	}
}

// isValidOrderBy 验证排序字符串是否安全（基于字段白名单）
// 支持格式:
//   - 单字段: id DESC
//   - 多字段: id DESC, createTime ASC
// 参数:
//   - orderBy: 排序字符串
// 返回:
//   - true: 排序字符串合法且所有字段都在白名单中
//   - false: 排序字符串不合法或包含非白名单字段
func (dao *{{ $daoName }}) isValidOrderBy(orderBy string) bool {
	if orderBy == "" {
		return false
	}

	// 获取字段白名单
	validFields := dao.getValidOrderByFields()

	// 按逗号分割多个排序字段
	orderParts := strings.Split(orderBy, ",")

	for _, part := range orderParts {
		part = strings.TrimSpace(part)
		if part == "" {
			return false
		}

		// 按空格分割字段名和排序方向
		tokens := strings.Fields(part)
		if len(tokens) == 0 || len(tokens) > 2 {
			// 格式错误: 必须是 "字段名" 或 "字段名 方向"
			return false
		}

		// 验证字段名是否在白名单中
		fieldName := tokens[0]
		if !validFields[fieldName] {
			// 字段不在白名单中
			return false
		}

		// 如果指定了排序方向，验证是否为 ASC 或 DESC
		if len(tokens) == 2 {
			direction := strings.ToUpper(tokens[1])
			if direction != "ASC" && direction != "DESC" {
				// 排序方向无效
				return false
			}
		}
	}

	return true
}

{{- end }}

package parser

import (
	"fmt"
	"log"

	"os"
	"strings"

	"github.com/LingoJack/model_infrax/config"
	"github.com/LingoJack/model_infrax/model"
	"github.com/pingcap/tidb/pkg/parser"
	"github.com/pingcap/tidb/pkg/parser/ast"
	"github.com/pingcap/tidb/pkg/parser/test_driver"
	"github.com/samber/lo"
)

type StatementParser struct {
	configger  *config.Configger
	statements []string
}

// NewStatementParser 创建SQL语句解析器
// 从配置文件中读取SQL文件路径，解析SQL文件内容
func NewStatementParser(cfg *config.Configger) (*StatementParser, error) {
	// 从配置中获取SQL文件路径
	sqlFilePath := cfg.GenerateConfig.SqlFilePath
	if sqlFilePath == "" {
		return nil, fmt.Errorf("statement模式下必须配置sql_file_path")
	}

	// 读取SQL文件内容
	byts, err := os.ReadFile(sqlFilePath)
	if err != nil {
		return nil, fmt.Errorf("读取SQL文件失败 [%s]: %w", sqlFilePath, err)
	}

	// 按分号分割SQL语句
	statements := strings.Split(string(byts), ";")

	log.Printf(" 成功加载SQL文件: %s, 共 %d 条语句", sqlFilePath, len(statements))

	return &StatementParser{
		configger:  cfg,
		statements: statements,
	}, nil
}

func (p *StatementParser) Parse() (schemas []model.Schema, err error) {
	for _, statement := range p.statements {
		// 跳过空语句
		trimmed := strings.TrimSpace(statement)
		if trimmed == "" {
			continue
		}

		log.Printf("⌛️ parsing statement: %s", statement)
		var schema model.Schema
		schema, err = p.parseStatement(statement)
		if err != nil {
			return nil, fmt.Errorf("解析语句失败: %w", err)
		}
		schemas = append(schemas, schema)
	}
	return
}

func (p *StatementParser) FilterTables(schemas []model.Schema) (filtered []model.Schema) {
	if p.configger.GenerateConfig.AllTables {
		filtered = schemas
		return
	}
	filtered = lo.Filter(schemas, func(schema model.Schema, index int) bool {
		return lo.Contains(p.configger.GenerateConfig.TableNames, schema.Name)
	})
	return
}

// parseStatement 解析单个CREATE TABLE语句，提取表结构信息
func (p *StatementParser) parseStatement(statement string) (schema model.Schema, err error) {
	// 创建TiDB parser实例
	tidbParser := parser.New()

	// 解析SQL语句
	stmtNodes, _, err := tidbParser.ParseSQL(statement)
	if err != nil {
		return schema, fmt.Errorf("SQL解析失败: %w", err)
	}

	// 确保至少有一个语句节点
	if len(stmtNodes) == 0 {
		return schema, fmt.Errorf("未找到有效的SQL语句")
	}

	// 获取第一个语句节点
	stmtNode := stmtNodes[0]

	// 类型断言为CREATE TABLE语句
	createTableStmt, ok := stmtNode.(*ast.CreateTableStmt)
	if !ok {
		return schema, fmt.Errorf("不是CREATE TABLE语句")
	}

	// 提取表名
	schema.Name = createTableStmt.Table.Name.O

	// 提取表注释
	for _, option := range createTableStmt.Options {
		if option.Tp == ast.TableOptionComment {
			schema.Comment = option.StrValue
			break
		}
	}

	// 用于存储列名到列索引的映射，方便后续索引处理
	// 注意：不能使用指针映射，因为 slice 扩容会导致指针失效
	columnIndexMap := make(map[string]int)

	// 提取列信息
	for _, col := range createTableStmt.Cols {
		column := model.Column{
			ColumnName: col.Name.Name.O,
			Type:       col.Tp.String(),
			IsNullable: true, // MySQL默认列是可以为NULL的，除非显式声明NOT NULL
		}

		// 提取列的各种属性
		for _, option := range col.Options {
			switch option.Tp {
			case ast.ColumnOptionComment:
				// 提取列注释：从ValueExpr的Datum.b字段中读取UTF-8编码的字节数组
				if option.Expr != nil {
					// 尝试类型断言为test_driver.ValueExpr
					if valueExpr, ok := option.Expr.(*test_driver.ValueExpr); ok {
						// Datum.b 存储的是UTF-8编码的字节数组
						if len(valueExpr.Datum.GetBytes()) > 0 {
							column.Comment = string(valueExpr.Datum.GetBytes())
						}
					}
				}
				// 如果Expr方式没取到，尝试StrValue（兼容处理）
				if column.Comment == "" && option.StrValue != "" {
					column.Comment = option.StrValue
				}
			case ast.ColumnOptionDefaultValue:
				// 提取默认值：需要区分ValueExpr（字符串/数值）和FuncCallExpr（函数如CURRENT_TIMESTAMP）
				if option.Expr != nil {
					var defaultVal string

					// 处理ValueExpr类型（字符串或数值默认值）
					if valueExpr, ok := option.Expr.(*test_driver.ValueExpr); ok {
						// 如果Datum.b为空字节数组，表示空字符串''
						if len(valueExpr.Datum.GetBytes()) == 0 {
							defaultVal = ""
						} else {
							// 否则转换字节数组为字符串
							defaultVal = string(valueExpr.Datum.GetBytes())
						}
					} else if funcExpr, ok := option.Expr.(*ast.FuncCallExpr); ok {
						// 处理FuncCallExpr类型（如CURRENT_TIMESTAMP）
						defaultVal = funcExpr.FnName.O
					}

					column.Default = &defaultVal
				}
			case ast.ColumnOptionAutoIncrement:
				// 标记自增列
				column.IsAutoIncrement = true
			case ast.ColumnOptionNull:
				// 标记允许NULL
				column.IsNullable = true
			case ast.ColumnOptionNotNull:
				// 标记不允许NULL
				column.IsNullable = false
			case ast.ColumnOptionPrimaryKey:
				// 标记主键
				column.IsPrimaryKey = true
			case ast.ColumnOptionUniqKey:
				// 标记唯一键
				column.IsUnique = true
			}
		}

		// 提取字符集校对规则
		if col.Tp.GetCollate() != "" {
			column.Collate = col.Tp.GetCollate()
		}

		schema.Columns = append(schema.Columns, column)
		// 存储列名到索引的映射，避免使用指针（slice 扩容会导致指针失效）
		columnIndexMap[column.ColumnName] = len(schema.Columns) - 1
	}
	for _, constraint := range createTableStmt.Constraints {
		switch constraint.Tp {
		case ast.ConstraintPrimaryKey:
			// 处理主键
			var pkColumns []model.Column
			for _, indexCol := range constraint.Keys {
				colName := indexCol.Column.Name.O
				if colIdx, exists := columnIndexMap[colName]; exists {
					// 通过索引直接修改 schema.Columns 中的列属性
					schema.Columns[colIdx].IsPrimaryKey = true
					schema.Columns[colIdx].IsIndexed = true
					pkColumns = append(pkColumns, schema.Columns[colIdx])
				}
			}
			schema.PrimaryKey = model.Index{
				IndexName: "PRIMARY",
				Columns:   pkColumns,
			}

		case ast.ConstraintUniq, ast.ConstraintUniqKey, ast.ConstraintUniqIndex:
			// 处理唯一索引
			var uniqueColumns []model.Column
			for _, indexCol := range constraint.Keys {
				colName := indexCol.Column.Name.O
				if colIdx, exists := columnIndexMap[colName]; exists {
					// 通过索引直接修改 schema.Columns 中的列属性
					schema.Columns[colIdx].IsUnique = true
					schema.Columns[colIdx].IsIndexed = true
					uniqueColumns = append(uniqueColumns, schema.Columns[colIdx])
				}
			}
			indexName := constraint.Name
			if indexName == "" {
				// 如果没有指定索引名，使用列名组合
				indexName = "uk_" + strings.Join(lo.Map(uniqueColumns, func(c model.Column, _ int) string {
					return c.ColumnName
				}), "_")
			}
			schema.UniqueIndex = append(schema.UniqueIndex, model.Index{
				IndexName: indexName,
				Columns:   uniqueColumns,
			})

		case ast.ConstraintKey, ast.ConstraintIndex:
			// 处理普通索引
			var indexColumns []model.Column
			for _, indexCol := range constraint.Keys {
				colName := indexCol.Column.Name.O
				if colIdx, exists := columnIndexMap[colName]; exists {
					// 通过索引直接修改 schema.Columns 中的列属性
					schema.Columns[colIdx].IsIndexed = true
					indexColumns = append(indexColumns, schema.Columns[colIdx])
				}
			}
			indexName := constraint.Name
			if indexName == "" {
				// 如果没有指定索引名，使用列名组合
				indexName = "idx_" + strings.Join(lo.Map(indexColumns, func(c model.Column, _ int) string {
					return c.ColumnName
				}), "_")
			}
			schema.Indexes = append(schema.Indexes, model.Index{
				IndexName: indexName,
				Columns:   indexColumns,
			})
		default:

		}
	}

	log.Printf("✅ 成功解析表: %s, 列数: %d, 索引数: %d", schema.Name, len(schema.Columns), len(schema.Indexes))
	return schema, nil
}

{{- /* Dao 层代码生成模板 */ -}}
package {{ .DaoPackageName }}

import (
	"context"
	"fmt"

	"strings"

	"gorm.io/gorm"
	igorm "git.woa.com/tencent-cloud-platform/go-module/itea-gorm"	// itea-go 框架提供的 db 注入
)

{{- range $schema := .Schemas }}
{{- $entityName := $schema.Name | ToPascalCase }}
{{- $daoName := printf "%sDao" $entityName }}
{{- $dtoName := printf "%sDto" $entityName }}
{{- $varName := $schema.Name | ToCamelCase }}

// {{ $daoName }} {{ $schema.Comment }}的Dao实现
type {{ $daoName }} struct {
	// itea-go 框架提供的 db 注入
	igorm.BaseDao `wired:"true"`
}

func (dao *{{ $daoName }} ) Database() string {
    // TODO 补全 db 名称
	return ""
}

// build{{ $entityName }}QueryCondition 构建查询条件
// 参数:
//   - db: GORM数据库连接实例
//   - queryDto: 查询条件Dto对象
// 返回:
//   - *gorm.DB: 应用了查询条件的数据库连接
// 说明:
//   - 支持精确匹配、模糊查询、IN查询、范围查询等多种查询方式
//   - 零值字段会被忽略，不会作为查询条件
func (dao *{{ $daoName }}) build{{ $entityName }}QueryCondition(db *gorm.DB, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) *gorm.DB {
	if queryDto == nil {
		return db
	}

	// 基础字段精确查询
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if eq $goType "string" }}
	if queryDto.{{ $fieldName }} != "" {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "int" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "uint64" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "int64" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "bool" }}
	// bool类型字段：false也是有效值，这里简化处理，如需区分未设置和false，Dto应使用*bool
	if queryDto.{{ $fieldName }} {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "time.Time" }}
	if !queryDto.{{ $fieldName }}.IsZero() {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*string" }}
	if queryDto.{{ $fieldName }} != nil && *queryDto.{{ $fieldName }} != "" {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*int" }}
	if queryDto.{{ $fieldName }} != nil {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*time.Time" }}
	if queryDto.{{ $fieldName }} != nil && !queryDto.{{ $fieldName }}.IsZero() {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else }}
	if queryDto.{{ $fieldName }} != nil {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- end }}
{{- end }}

	// 模糊查询条件
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if eq $goType "string" }}
	if queryDto.{{ $fieldName }}Fuzzy != "" {
		db = db.Where("{{ .ColumnName }} LIKE ?", "%"+queryDto.{{ $fieldName }}Fuzzy+"%")
	}
{{- else if eq $goType "*string" }}
	if queryDto.{{ $fieldName }}Fuzzy != nil && *queryDto.{{ $fieldName }}Fuzzy != "" {
		db = db.Where("{{ .ColumnName }} LIKE ?", "%"+*queryDto.{{ $fieldName }}Fuzzy+"%")
	}
{{- end }}
{{- end }}

	// 日期范围查询
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if or (eq $goType "time.Time") (eq $goType "*time.Time") }}
	if !queryDto.{{ $fieldName }}Start.IsZero() {
		db = db.Where("{{ .ColumnName }} >= ?", queryDto.{{ $fieldName }}Start)
	}
	if !queryDto.{{ $fieldName }}End.IsZero() {
		db = db.Where("{{ .ColumnName }} < DATE_ADD(?, INTERVAL 1 DAY)", queryDto.{{ $fieldName }}End)
	}
{{- end }}
{{- end }}

	// IN 查询条件
{{- range $schema.Columns }}
{{- if .IsIndexed }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
	if len(queryDto.{{ $fieldName }}List) > 0 {
		db = db.Where("{{ .ColumnName }} IN ?", queryDto.{{ $fieldName }}List)
	}
{{- end }}
{{- end }}

	return db
}

// ==================== 基础查询方法 ====================

// SelectList 查询列表
// 参数:
//   - ctx: 上下文对象
//   - queryDto: 查询条件Dto对象，支持分页、排序、多条件查询
// 返回:
//   - []*{{ $.PoPackageName }}.{{ $entityName }}: 查询结果列表
//   - error: 错误信息
func (dao *{{ $daoName }}) SelectList(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	var resultList []*{{ $.PoPackageName }}.{{ $entityName }}
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).WithContext(ctx)

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	// 排序
	if queryDto != nil && queryDto.OrderBy != "" {
		if dao.isValidOrderBy(queryDto.OrderBy) {
		    // NOCA:sql_injection(在`isValidOrderBy`方法做过排序的白名单校验)
			db = db.Order(queryDto.OrderBy)
		}
	}

	// 分页
	if queryDto != nil && queryDto.PageSize > 0 {
		db = db.Offset(queryDto.PageOffset * queryDto.PageSize).Limit(queryDto.PageSize)
	}

	err := db.Find(&resultList).Error
	return resultList, err
}

// SelectCount 查询数量
// 参数:
//   - ctx: 上下文对象
//   - queryDto: 查询条件Dto对象
// 返回:
//   - int64: 符合条件的记录数量
//   - error: 错误信息
func (dao *{{ $daoName }}) SelectCount(ctx context.Context, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) (int64, error) {
	var count int64
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).WithContext(ctx)

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	err := db.Count(&count).Error
	return count, err
}

