//   - 自增主键会在插入后自动填充到poBean中
func (dao *{{ $daoName }}) Insert(ctx context.Context, poBean *{{ $.PoPackageName }}.{{ $entityName }}) error {
	if poBean == nil {
		return fmt.Errorf("插入对象不能为空")
	}
	return dao.WithContext(ctx).Create(poBean).Error
}

// InsertBatch 批量插入
// 参数:
//   - ctx: 上下文对象
//   - poBeanList: 要插入的PO对象列表
// 返回:
//   - error: 错误信息
// 说明:
