//   3. 提供最灵活的更新控制方式
func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}WithMapAndCondition(ctx context.Context, {{ $pkParamName }} {{ $pkGoType }}, updatedMap map[string]interface{}, conditionMap map[string]interface{}) error {
