package main

import (
	"log"
	"os"
	"os/exec"
	"path/filepath"

	flag "github.com/spf13/pflag"
)

// Version 当前版本号
const Version = "1.0.9"

// defaultConfigPaths 默认配置文件路径列表
// 按照优先级顺序查找配置文件，找到第一个可用的就使用
var defaultConfigPaths = []string{
	"./application.yml",                                 // 当前目录下的配置文件
	"./assets/application.yml",                          // assets目录下的配置文件
	"/Applications/model_infrax/application.yml",        // 系统安装目录下的配置文件
	"/Applications/model_infrax/assets/application.yml", // 系统安装目录assets子目录下的配置文件
}

// defaultGoFile 默认要执行的 Go 文件
const defaultGoFile = "model_infra.go"

// main 主函数，程序入口点
// 采用优先级自动降级策略，按以下顺序尝试：
//  1. 如果用户指定了 --config 参数，使用指定的配置文件（最高优先级，用户意图优先）
//  2. 如果当前目录存在 model_infra.go 文件，直接执行它
//  3. 按默认路径列表查找并使用第一个可用的配置文件
//  4. 如果以上都失败，提示用户并退出
//
// 支持的命令行参数：
//
//	-c, --config: 指定配置文件路径（可选）
//	-v, --version: 显示版本号
//
// 使用示例：
//
//	jen                                    # 自动选择最合适的方式
//	jen -c ./my-config.yml                 # 强制使用指定的配置文件（最高优先级）
//	jen --config /path/to/config.yml       # 使用长格式参数
//	jen -v                                 # 显示版本号
//	jen --version                          # 显示版本号（长格式）
func main() {
	// 定义命令行参数
	configPath := flag.StringP("config", "c", "", "配置文件路径")
	showVersion := flag.BoolP("version", "v", false, "显示版本号")
	flag.Parse()

	// 优先级 0: 显示版本号（最高优先级）
	if *showVersion {
		log.Printf("jen version %s", Version)
		return
	}

	// 优先级 1: 用户指定的配置文件（最高优先级，用户意图优先）
	if *configPath != "" {
		log.Printf(" 使用用户指定的配置文件: %s", *configPath)
		if err := runWithConfig(*configPath); err != nil {
			log.Fatalf("❌ 使用配置文件 %s 失败: %v", *configPath, err)
		}
		log.Println(" 程序执行完成")
		return
	}

	// 优先级 2: 检查是否存在 model_infra.go 文件
	if fileExists(defaultGoFile) {
		log.Printf(" 检测到 %s 文件，直接执行...", defaultGoFile)
		if err := runGoFile(defaultGoFile); err != nil {
			log.Fatalf("❌ 执行 %s 失败: %v", defaultGoFile, err)
		}
		log.Println(" 程序执行完成")
		return
	}

	// 优先级 3: 尝试默认配置文件路径
	log.Println(" 未找到 model_infra.go，尝试使用默认配置文件...")
	for _, path := range defaultConfigPaths {
		if fileExists(path) {
			log.Printf(" 找到配置文件: %s", path)
			if err := runWithConfig(path); err != nil {
				log.Printf("⚠️ 配置文件 %s 加载失败: %v，继续尝试下一个...", path, err)
				continue
			}
			log.Println(" 程序执行完成")
			return
		}
	}

	// 优先级 4: 所有方式都失败，提示用户
	log.Println("❌ 无法找到可用的配置或代码文件")
	log.Println("")
	log.Println(" 请选择以下任一方式：")
	log.Println("")
	log.Println("   方式 1: 创建 model_infra.go 文件（推荐用于编程式控制）")
	log.Println("   -------------------------------------------------------")
	log.Println("   在当前目录创建 model_infra.go，示例：")
	log.Println("")
	log.Println("   package main")
	log.Println("")
	log.Println("   import (")
	log.Println("       \"log\"")
	log.Println("       \"github.com/LingoJack/model_infrax\"")
	log.Println("   )")
	log.Println("")
	log.Println("   func main() {")
	log.Println("       err := model_infrax.Generate(")
	log.Println("           model_infrax.NewBuilder().")
	log.Println("               DatabaseMode(\"localhost\", 3306, \"mydb\", \"root\", \"pass\").")
	log.Println("               AllTables().")
	log.Println("               OutputPath(\"./output\").")
	log.Println("               BuildAndGenerate(),")
	log.Println("       )")
	log.Println("       if err != nil {")
	log.Println("           log.Fatal(err)")
	log.Println("       }")
	log.Println("   }")
	log.Println("")
	log.Println("   方式 2: 使用配置文件（推荐用于声明式配置）")
	log.Println("   -------------------------------------------------------")
	log.Println("   创建 application.yml 配置文件，或使用 --config 参数指定")
	log.Println("   示例: jen --config ./my-config.yml")
	log.Println("")
	log.Printf("   默认配置文件查找路径: %v", defaultConfigPaths)
	log.Println("")
	os.Exit(1)
}

// fileExists 检查文件是否存在
// 参数:
//
//	filename: 要检查的文件路径
//
// 返回:
//
//	bool: 文件存在返回 true，否则返回 false
func fileExists(filename string) bool {
	info, err := os.Stat(filename)
	if os.IsNotExist(err) {
		return false
	}
	return !info.IsDir()
}

// runGoFile 执行指定的 Go 文件
// 使用 go run 命令执行文件，并将输出重定向到当前进程的标准输出/错误输出
// 参数:
//
//	filename: 要执行的 Go 文件路径
//
// 返回:
//
//	error: 执行过程中的错误，nil 表示成功
func runGoFile(filename string) error {
	// 获取文件的绝对路径
	absPath, err := filepath.Abs(filename)
	if err != nil {
		return err
	}

	log.Printf(" 执行文件: %s", absPath)

	// 创建 go run 命令
	cmd := exec.Command("go", "run", absPath)

	// 将命令的输出重定向到当前进程的标准输出和错误输出
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin

	// 执行命令
	return cmd.Run()
}

// runWithConfig 使用配置文件运行应用
// 参数:
//
//	configPath: 配置文件路径
//
// 返回:
//
//	error: 执行过程中的错误，nil 表示成功
func runWithConfig(configPath string) error {
	log.Println(" 开始执行代码生成...")

	// 初始化应用实例
	appInstance, err := InitializeApp(configPath)
	if err != nil {
		return err
	}

	// 运行应用
	if err = appInstance.Run(); err != nil {
		return err
	}

	return nil
}

{{- /* Dao 层代码生成模板 */ -}}
package {{ .DaoPackageName }}

import (
	"fmt"

	"strings"

	"gorm.io/gorm"
)

{{- range $schema := .Schemas }}
{{- $entityName := $schema.Name | ToPascalCase }}
{{- $daoName := printf "%sDao" $entityName }}
{{- $dtoName := printf "%sDto" $entityName }}
{{- $varName := $schema.Name | ToCamelCase }}

// {{ $daoName }} {{ $schema.Comment }}的Dao实现
type {{ $daoName }} struct {
	*gorm.DB
}

func (dao *{{ $daoName }} ) Database() string {
    // TODO 补全 db 名称
	return ""
}

// New{{ $daoName }} 创建{{ $daoName }}实例
// 参数:
//   - db: GORM数据库连接实例
// 返回:
//   - *{{ $daoName }}: Dao实例
func New{{ $daoName }}(db *gorm.DB) *{{ $daoName }} {
	return &{{ $daoName }}{db: db}
}

// build{{ $entityName }}QueryCondition 构建查询条件
// 参数:
//   - db: GORM数据库连接实例
//   - queryDto: 查询条件Dto对象
// 返回:
//   - *gorm.DB: 应用了查询条件的数据库连接
// 说明:
//   - 支持精确匹配、模糊查询、IN查询、范围查询等多种查询方式
//   - 零值字段会被忽略，不会作为查询条件
func (dao *{{ $daoName }}) build{{ $entityName }}QueryCondition(db *gorm.DB, queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) *gorm.DB {
	if queryDto == nil {
		return db
	}

	// 基础字段精确查询
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if eq $goType "string" }}
	if queryDto.{{ $fieldName }} != "" {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "int" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "uint64" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "int64" }}
	if queryDto.{{ $fieldName }} != 0 {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "bool" }}
	// bool类型字段：false也是有效值，这里简化处理，如需区分未设置和false，Dto应使用*bool
	if queryDto.{{ $fieldName }} {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "time.Time" }}
	if !queryDto.{{ $fieldName }}.IsZero() {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*string" }}
	if queryDto.{{ $fieldName }} != nil && *queryDto.{{ $fieldName }} != "" {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*int" }}
	if queryDto.{{ $fieldName }} != nil {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else if eq $goType "*time.Time" }}
	if queryDto.{{ $fieldName }} != nil && !queryDto.{{ $fieldName }}.IsZero() {
		db = db.Where("{{ .ColumnName }} = ?", *queryDto.{{ $fieldName }})
	}
{{- else }}
	if queryDto.{{ $fieldName }} != nil {
		db = db.Where("{{ .ColumnName }} = ?", queryDto.{{ $fieldName }})
	}
{{- end }}
{{- end }}

	// 模糊查询条件
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if eq $goType "string" }}
	if queryDto.{{ $fieldName }}Fuzzy != "" {
		db = db.Where("{{ .ColumnName }} LIKE ?", "%"+queryDto.{{ $fieldName }}Fuzzy+"%")
	}
{{- else if eq $goType "*string" }}
	if queryDto.{{ $fieldName }}Fuzzy != nil && *queryDto.{{ $fieldName }}Fuzzy != "" {
		db = db.Where("{{ .ColumnName }} LIKE ?", "%"+*queryDto.{{ $fieldName }}Fuzzy+"%")
	}
{{- end }}
{{- end }}

	// 日期范围查询
{{- range $schema.Columns }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
{{- if or (eq $goType "time.Time") (eq $goType "*time.Time") }}
	if !queryDto.{{ $fieldName }}Start.IsZero() {
		db = db.Where("{{ .ColumnName }} >= ?", queryDto.{{ $fieldName }}Start)
	}
	if !queryDto.{{ $fieldName }}End.IsZero() {
		db = db.Where("{{ .ColumnName }} < DATE_ADD(?, INTERVAL 1 DAY)", queryDto.{{ $fieldName }}End)
	}
{{- end }}
{{- end }}

	// IN 查询条件
{{- range $schema.Columns }}
{{- if .IsIndexed }}
{{- $fieldName := .ColumnName | ToPascalCase }}
{{- $goType := . | GetGoType }}
	if len(queryDto.{{ $fieldName }}List) > 0 {
		db = db.Where("{{ .ColumnName }} IN ?", queryDto.{{ $fieldName }}List)
	}
{{- end }}
{{- end }}

	return db
}

// ==================== 基础查询方法 ====================

// SelectList 查询列表
// 参数:
//   - queryDto: 查询条件Dto对象，支持分页、排序、多条件查询
// 返回:
//   - []*{{ $.PoPackageName }}.{{ $entityName }}: 查询结果列表
//   - error: 错误信息
func (dao *{{ $daoName }}) SelectList(queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	var resultList []*{{ $.PoPackageName }}.{{ $entityName }}
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{})

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	// 排序
	if queryDto != nil && queryDto.OrderBy != "" {
		if dao.isValidOrderBy(queryDto.OrderBy) {
			db = db.Order(queryDto.OrderBy)
		}
	}

	// 分页
	if queryDto != nil && queryDto.PageSize > 0 {
		db = db.Offset(queryDto.PageOffset * queryDto.PageSize).Limit(queryDto.PageSize)
	}

	err := db.Find(&resultList).Error
	return resultList, err
}

// SelectCount 查询数量
// 参数:
//   - queryDto: 查询条件Dto对象
// 返回:
//   - int64: 符合条件的记录数量
//   - error: 错误信息
func (dao *{{ $daoName }}) SelectCount(queryDto *{{ $.DtoPackageName }}.{{ $dtoName }}) (int64, error) {
	var count int64
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{})

	// 应用查询条件
	db = dao.build{{ $entityName }}QueryCondition(db, queryDto)

	err := db.Count(&count).Error
	return count, err
}

// ==================== 基础插入方法 ====================

// Insert 单行插入
// 参数:
//   - poBean: 要插入的PO对象
// 返回:
//   - error: 错误信息
// 说明:
//   - 插入所有字段，包括零值字段
//   - 自增主键会在插入后自动填充到poBean中
func (dao *{{ $daoName }}) Insert(poBean *{{ $.PoPackageName }}.{{ $entityName }}) error {
	if poBean == nil {
		return fmt.Errorf("插入对象不能为空")
	}
	return dao.Create(poBean).Error
}

// InsertBatch 批量插入
// 参数:
//   - poBeanList: 要插入的PO对象列表
// 返回:
//   - error: 错误信息
// 说明:
//   - 批量插入所有记录，在一个事务中执行
//   - 自增主键会在插入后自动填充到各个poBean中
func (dao *{{ $daoName }}) InsertBatch(poBeanList []*{{ $.PoPackageName }}.{{ $entityName }}) error {
	if len(poBeanList) == 0 {
		return fmt.Errorf("批量插入列表不能为空")
	}
	return dao.Create(&poBeanList).Error
}

// InsertOrUpdateNullable 插入或更新（会用零值覆盖）
// 参数:
//   - poBean: 要插入或更新的PO对象
// 返回:
//   - error: 错误信息
// 行为说明:
//   1. 如果记录不存在（根据主键判断），则执行插入操作
//   2. 如果记录已存在，则执行全字段更新操作
//   3. **重要**: 更新时会用传入对象的所有字段值覆盖数据库中的值，包括零值（nil、""、0、false等）
//      例如: 如果 poBean.Content = nil，会将数据库中的 content 字段更新为 NULL
//      例如: 如果 poBean.ArtifactName = ""，会将数据库中的 artifactName 字段更新为空字符串
//   4. 这种行为适用于需要"完整替换"记录的场景
//   5. 如果不希望零值覆盖数据库中的非零值，应使用 UpdateByXxx 等方法（内部使用 Updates）
func (dao *{{ $daoName }}) InsertOrUpdateNullable(poBean *{{ $.PoPackageName }}.{{ $entityName }}) error {
	if poBean == nil {
		return fmt.Errorf("插入或更新对象不能为空")
	}
	// 使用 GORM 的 Save 方法:
	// - 根据主键判断记录是否存在
	// - 存在则更新所有字段（包括零值字段）
	// - 不存在则插入新记录
	return dao.Save(poBean).Error
}

// InsertOrUpdateBatchNullable 批量插入或更新（会用零值覆盖）
// 参数:
//   - poBeanList: 要插入或更新的PO对象列表
// 返回:
//   - error: 错误信息
// 行为说明:
//   1. 对列表中的每条记录，根据主键判断是插入还是更新
//   2. 如果记录不存在，则执行插入操作
//   3. 如果记录已存在，则执行全字段更新操作
//   4. **重要**: 更新时会用传入对象的所有字段值覆盖数据库中的值，包括零值（nil、""、0、false等）
//      这意味着如果某个字段在传入对象中为零值，会将数据库中对应字段更新为零值
//   5. 批量操作在一个事务中执行，要么全部成功，要么全部失败
//   6. 适用场景: 需要完整替换多条记录的场景
//   7. 性能提示: 批量操作比逐条调用 InsertOrUpdateNullable 效率更高
//   8. 如果不希望零值覆盖，建议逐条调用 UpdateByXxx 等方法
func (dao *{{ $daoName }}) InsertOrUpdateBatchNullable(poBeanList []*{{ $.PoPackageName }}.{{ $entityName }}) error {
	if len(poBeanList) == 0 {
		return fmt.Errorf("批量插入或更新列表不能为空")
	}
	// 使用 GORM 的 Save 方法批量保存:
	// - 对每条记录根据主键判断是插入还是更新
	// - 更新时会覆盖所有字段（包括零值字段）
	// - 在一个事务中执行，保证原子性
	return dao.Save(&poBeanList).Error
}

{{- /* ==================== 主键索引方法 ==================== */ -}}
{{- if $schema.PrimaryKey.Columns }}
{{- $pkColumns := $schema.PrimaryKey.Columns }}
