{{- $pkGoType := $pkCol | GetGoType }}
{{- $pkParamName := $pkCol.ColumnName | ToSafeParamName }}

// ==================== 主键索引方法 ====================

// SelectBy{{ $pkFieldName }} 根据主键{{ $pkFieldName }}查询单条记录
// 参数:
//   - {{ $pkParamName }}: 主键值
// 返回:
//   - *{{ $.PoPackageName }}.{{ $entityName }}: 查询结果，如果不存在返回nil
//   - error: 错误信息
func (dao *{{ $daoName }}) SelectBy{{ $pkFieldName }}({{ $pkParamName }} {{ $pkGoType }}) (*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	var resultBean {{ $.PoPackageName }}.{{ $entityName }}
	err := dao.Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }}).First(&resultBean).Error
	if err != nil {
		return nil, err
	}
	return &resultBean, nil
}

{{- if $pkCol.IsIndexed }}
// SelectBy{{ $pkFieldName }}List 根据主键{{ $pkFieldName }}列表批量查询
// 参数:
//   - {{ $pkParamName }}List: 主键值列表
// 返回:
//   - []*{{ $.PoPackageName }}.{{ $entityName }}: 查询结果列表
//   - error: 错误信息
func (dao *{{ $daoName }}) SelectBy{{ $pkFieldName }}List({{ $pkParamName }}List []{{ $pkGoType }}) ([]*{{ $.PoPackageName }}.{{ $entityName }}, error) {
	if len({{ $pkParamName }}List) == 0 {
		return []*{{ $.PoPackageName }}.{{ $entityName }}{}, nil
	}
	var resultList []*{{ $.PoPackageName }}.{{ $entityName }}
	err := dao.Where("{{ $pkCol.ColumnName }} IN ?", {{ $pkParamName }}List).Find(&resultList).Error
	return resultList, err
}
{{- end }}

// UpdateBy{{ $pkFieldName }} 根据主键{{ $pkFieldName }}更新（不会用零值覆盖）
// 参数:
//   - poBean: 包含更新数据的PO对象
//   - {{ $pkParamName }}: 主键值
// 返回:
//   - error: 错误信息
// 行为说明:
//   1. 根据指定的 {{ $pkParamName }} 更新记录
//   2. **重要**: 只更新非零值字段，零值字段会被忽略，不会覆盖数据库中的值
//      例如: 如果 poBean.Content = nil，不会更新数据库中的 content 字段
//      例如: 如果 poBean.ArtifactName = ""，不会更新数据库中的 artifactName 字段
//   3. 这种行为适用于"部分更新"场景，保留数据库中未传入的字段值
//   4. 如果需要将某个字段更新为零值，应使用 UpdateBy{{ $pkFieldName }}WithMap 方法显式指定
//   5. 与 InsertOrUpdateNullable 的区别: InsertOrUpdateNullable 会用零值覆盖，UpdateBy{{ $pkFieldName }} 不会
func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}(poBean *{{ $.PoPackageName }}.{{ $entityName }}, {{ $pkParamName }} {{ $pkGoType }}) error {
	if poBean == nil {
		return fmt.Errorf("更新对象不能为空")
	}
	// 使用 Updates 方法:
	// - 只更新结构体中的非零值字段
	// - 零值字段会被忽略，保留数据库中的原值
	// - 适合部分更新场景
	return dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }}).Updates(poBean).Error
}

// UpdateBy{{ $pkFieldName }}WithMap 根据主键{{ $pkFieldName }}使用Map更新指定字段（可以用零值覆盖）
// 参数:
//   - {{ $pkParamName }}: 主键值
//   - updatedMap: 要更新的字段Map，key为字段名（数据库列名），value为字段值
// 返回:
//   - error: 错误信息
// 行为说明:
//   1. 根据指定的 {{ $pkParamName }} 更新记录
//   2. 使用 map 可以显式指定要更新的字段，包括零值字段
//   3. **重要**: 与 UpdateBy{{ $pkFieldName }} 不同，使用 map 可以将字段更新为零值
//      例如: updatedMap["content"] = nil 会将 content 字段更新为 NULL
//      例如: updatedMap["artifactName"] = "" 会将 artifactName 字段更新为空字符串
//   4. 只更新 map 中指定的字段，未指定的字段保持不变
//   5. 适用场景: 需要精确控制更新哪些字段，包括需要将某些字段设置为零值的场景
//   6. 使用建议: 字段名必须与数据库列名一致（或使用 GORM 的字段映射名）
func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}WithMap({{ $pkParamName }} {{ $pkGoType }}, updatedMap map[string]interface{}) error {
	if len(updatedMap) == 0 {
		return fmt.Errorf("更新字段不能为空")
	}
	// 使用 Updates 方法配合 map:
	// - 可以显式更新零值字段
	// - 只更新 map 中指定的字段
	// - 提供最精确的字段更新控制
	return dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }}).Updates(updatedMap).Error
}

// UpdateBy{{ $pkFieldName }}WithCondition 根据主键{{ $pkFieldName }}和额外条件更新（不会用零值覆盖）
// 参数:
//   - poBean: 包含更新数据的PO对象
//   - {{ $pkParamName }}: 主键值
//   - conditionMap: 额外的查询条件Map，key为字段名，value为字段值
// 返回:
//   - error: 错误信息
// 行为说明:
//   1. 根据指定的 {{ $pkParamName }} 和额外的条件更新记录
//   2. 只更新非零值字段，零值字段会被忽略
//   3. 适用场景: 需要在主键基础上增加额外的更新条件，如乐观锁、状态检查等
//   4. 示例: conditionMap["version"] = 1 可以实现乐观锁，只有版本号匹配才更新
func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}WithCondition(poBean *{{ $.PoPackageName }}.{{ $entityName }}, {{ $pkParamName }} {{ $pkGoType }}, conditionMap map[string]interface{}) error {
	if poBean == nil {
		return fmt.Errorf("更新对象不能为空")
	}
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }})

	// 应用额外的条件
	for key, value := range conditionMap {
		db = db.Where(key+" = ?", value)
	}

	return db.Updates(poBean).Error
}

// UpdateBy{{ $pkFieldName }}WithMapAndCondition 根据主键{{ $pkFieldName }}和额外条件使用Map更新指定字段（可以用零值覆盖）
// 参数:
//   - {{ $pkParamName }}: 主键值
//   - updatedMap: 要更新的字段Map
//   - conditionMap: 额外的查询条件Map
// 返回:
//   - error: 错误信息
// 行为说明:
//   1. 根据指定的 {{ $pkParamName }} 和额外的条件更新记录
//   2. 使用 map 可以显式指定要更新的字段，包括零值字段
//   3. 提供最灵活的更新控制方式
func (dao *{{ $daoName }}) UpdateBy{{ $pkFieldName }}WithMapAndCondition({{ $pkParamName }} {{ $pkGoType }}, updatedMap map[string]interface{}, conditionMap map[string]interface{}) error {
	if len(updatedMap) == 0 {
		return fmt.Errorf("更新字段不能为空")
	}
	db := dao.Model(&{{ $.PoPackageName }}.{{ $entityName }}{}).Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }})

	// 应用额外的条件
	for key, value := range conditionMap {
		db = db.Where(key+" = ?", value)
	}

	return db.Updates(updatedMap).Error
}

// DeleteBy{{ $pkFieldName }} 根据主键{{ $pkFieldName }}删除
// 参数:
//   - {{ $pkParamName }}: 主键值
// 返回:
//   - error: 错误信息
func (dao *{{ $daoName }}) DeleteBy{{ $pkFieldName }}({{ $pkParamName }} {{ $pkGoType }}) error {
	return dao.Where("{{ $pkCol.ColumnName }} = ?", {{ $pkParamName }}).Delete(&{{ $.PoPackageName }}.{{ $entityName }}{}).Error
