package tool

import (
	"github.com/jinzhu/copier"
)

// Copy 深度拷贝函数 - 支持各种类型的深度拷贝
//
// 功能说明：
// 1. 深度拷贝：完全复制数据，修改拷贝不会影响原数据
// 2. 支持类型：
//   - 基本类型：int, string, bool, float 等
//   - 结构体：包括嵌套结构体
//   - 切片：[]T, []*T 等各种切片类型
//   - 数组：[N]T
//   - Map：map[K]V
//   - 指针：*T（会创建新的指针指向拷贝的值）
//
// 3. 字段匹配：按字段名匹配，支持不同类型间的部分字段拷贝
//
// 参数说明：
//   - from: 源数据（可以是值或指针）
//   - to: 目标数据（必须是指针，用于接收拷贝结果）
//
// 返回值：
//   - error: 拷贝失败时返回错误信息
//
// 使用示例：
//
// 1. 结构体拷贝（相同类型）：
//
//	type User struct {
//	    Name string
//	    Age  int
//	}
//	src := User{Name: "Alice", Age: 30}
//	var dst User
//	err := Copy(src, &dst)  // 注意：dst 必须传指针
//
// 2. 结构体拷贝（不同类型，部分字段）：
//
//	type Entity struct {
//	    Name   string
//	    Age    int
//	    Gender string
//	}
//	type VO struct {
//	    Name   string
//	    Gender string
//	}
//	entity := Entity{Name: "Alice", Age: 30, Gender: "Female"}
//	var vo VO
//	err := Copy(entity, &vo)  // 只拷贝 Name 和 Gender 字段
//
// 3. 切片拷贝（深度拷贝）：
//
//	// 方式1：空切片（推荐）
//	from := []*int{IntPtr(1), IntPtr(2), IntPtr(3)}
//	to := make([]*int, 0)
//	err := Copy(from, &to)  // 注意：必须传 &to
//
//	// 方式2：预分配长度
//	to := make([]*int, len(from))
//	err := Copy(from, &to)
//
//	// 验证深度拷贝：修改拷贝不影响原数据
//	*to[0] = 100  // 修改拷贝
//	// from[0] 仍然是 1，不受影响
//
// 4. Map 拷贝（深度拷贝）：
//
//	from := map[string]*User{
//	    "alice": {Name: "Alice", Age: 30},
//	}
//	to := make(map[string]*User)
//	err := Copy(from, &to)
//
// 5. 嵌套结构体拷贝：
//
//	type Address struct {
//	    City string
//	}
//	type Person struct {
//	    Name    string
//	    Address *Address  // 嵌套指针
//	}
//	src := Person{
//	    Name: "Alice",
//	    Address: &Address{City: "Beijing"},
//	}
//	var dst Person
//	err := Copy(src, &dst)
//	// dst.Address 是新的指针，指向拷贝的 Address
//
// 常见错误：
//
// ❌ 错误1：目标参数不传指针
//
//	var dst User
//	err := Copy(src, dst)  // 错误！dst 不会被修改
//
// ✓ 正确：
//
//	err := Copy(src, &dst)  // 正确！传指针
//
// ❌ 错误2：切片拷贝不传指针
//
//	to := make([]*int, 0)
//	err := Copy(from, to)  // 错误！to 不会被修改
//
// ✓ 正确：
//
//	err := Copy(from, &to)  // 正确！传指针
//
// 注意事项：
// 1. to 参数必须是指针类型，否则无法修改目标变量
// 2. 切片、Map 等引用类型也需要传指针（&to）
// 3. 字段匹配规则：
//   - 按字段名匹配（大小写敏感）
//   - 字段类型必须兼容或可转换
//   - 源类型字段多于目标类型时，只拷贝匹配的字段
//
// 4. 深度拷贝保证：
//   - 指针字段会创建新的指针和新的值
//   - 切片会创建新的底层数组
//   - Map 会创建新的 Map
//   - 修改拷贝不会影响原数据
//
// 底层实现：
// 使用 github.com/jinzhu/copier 库实现深度拷贝
// 该库会递归处理嵌套结构，确保完全的深度拷贝
func Copy(from any, to any) (err error) {
	return copier.Copy(to, from)
}

// CopyWithOption 带选项的深度拷贝函数
//
// 功能说明：
// 提供更灵活的拷贝选项，支持自定义拷贝行为
//
// 参数说明：
//   - from: 源数据
//   - to: 目标数据（必须是指针）
//   - opts: 拷贝选项
//
// 可用选项：
//   - IgnoreEmpty: 忽略空值字段（零值不会覆盖目标字段）
//   - DeepCopy: 强制深度拷贝（默认已启用）
//
// 使用示例：
//
//	type User struct {
//	    Name string
//	    Age  int
//	}
//	src := User{Name: "Alice"}  // Age 为零值
//	dst := User{Name: "Bob", Age: 30}
//
//	// 不忽略空值：dst.Age 会被覆盖为 0
//	err := Copy(src, &dst)
//	// 结果：dst = {Name: "Alice", Age: 0}
//
//	// 忽略空值：dst.Age 保持原值
//	err := CopyWithOption(src, &dst, copier.Option{IgnoreEmpty: true})
//	// 结果：dst = {Name: "Alice", Age: 30}
func CopyWithOption(from any, to any, opt copier.Option) (err error) {
	return copier.CopyWithOption(to, from, opt)
}

