import (
	"fmt"
	"testing"

	"github.com/jinzhu/copier"
)

// ... existing code ...

func TestCopySliceCommonMistakes(t *testing.T) {
	from := []*int{IntPtr(1), IntPtr(2), IntPtr(3)}

	t.Run("错误方式1-不传指针", func(t *testing.T) {
		to := make([]*int, 0)
		// ❌ 错误：不传指针，to 不会被修改
		err := Copy(from, to) // 应该是 &to
		if err != nil {
			fmt.Println("✓ 正确：copier 检测到错误并返回 error")
		}
		fmt.Printf("to 的长度: %d (期望: 3)\n", len(to))
	})

	t.Run("正确方式-传指针", func(t *testing.T) {
		to := make([]*int, 0)
		// ✓ 正确：传指针，to 会被修改
		err := Copy(from, &to)
		if err != nil {
			t.Error(err)
			return
		}
		fmt.Printf("✓ to 的长度: %d (期望: 3)\n", len(to))
		if len(to) != 3 {
			t.Error("拷贝失败")
		}
	})
}

// TestDeepCopyMap 测试 map 的深度拷贝（值为指针）
func TestDeepCopyMap(t *testing.T) {
	// 创建源 map，值为指向 Entity 的指针
	from := map[string]*Entity{
		"alice": {
			Name: "Alice",
			Age: 30,
			Gender: "Female",
		},
	}

	to := make(map[string]*Entity)
	if err := Copy(from, &to); err != nil {
		t.Error(err)
		return
	}

	fmt.Println("原 map:", JsonifyIndent(from))
	fmt.Println("拷贝 map:", JsonifyIndent(to))

	if len(to) != len(from) {
		t.Errorf("拷贝失败：期望长度为 %d，实际为 %d", len(from), len(to))
	}

	// 验证：深度拷贝（指针地址不同，修改拷贝不影响原对象）
	src := from["alice"]
	dst := to["alice"]
	if src == nil || dst == nil {
		t.Fatal("拷贝失败：元素为空")
	}
	if src == dst {
		t.Error("❌ 深度拷贝失败：指针地址相同")
	}

	dst.Age = 40
	if src.Age != 30 {
		t.Error("❌ 深度拷贝失败：修改拷贝影响了原对象")
	} else {
		fmt.Println("✓ map 深度拷贝成功：修改拷贝不影响原对象")
	}
}

// TestDeepCopyNestedStruct 测试带嵌套指针字段的结构体深度拷贝
func TestDeepCopyNestedStruct(t *testing.T) {
	// 在函数内部定义临时类型，避免污染全局命名空间
	type Address struct {
		City string
	}
	type Person struct {
		Name string
		Addr *Address
	}

	from := Person{
		Name: "Alice",
		Addr: &Address{City: "Beijing"},
	}

	var to Person
	if err := Copy(from, &to); err != nil {
		t.Error(err)
		return
	}

	fmt.Println("原对象:", JsonifyIndent(from))
	fmt.Println("拷贝对象:", JsonifyIndent(to))

	if from.Addr == nil || to.Addr == nil {
		t.Fatal("拷贝失败：嵌套指针为空")
	}
	if from.Addr == to.Addr {
		t.Error("❌ 深度拷贝失败：嵌套指针地址相同")
	}

	// 修改拷贝的嵌套字段，验证不会影响原对象
	to.Addr.City = "Shanghai"
	if from.Addr.City != "Beijing" {
		t.Error("❌ 深度拷贝失败：修改拷贝影响了原对象的嵌套字段")
	} else {
		fmt.Println("✓ 嵌套结构体深度拷贝成功：修改拷贝不影响原对象")
	}
}

// TestCopyWithOptionIgnoreEmpty 测试 CopyWithOption 的 IgnoreEmpty 行为
func TestCopyWithOptionIgnoreEmpty(t *testing.T) {
	// src 的 Age、Gender 为零值
	src := Entity{
		Name: "Alice",
	}
	// dst 预先有完整数据
	dst := Entity{
		Name: "Bob",
		Age: 30,
		Gender: "Male",
	}

	// 默认拷贝：零值会覆盖目标字段
	dstDefault := dst
	if err := Copy(src, &dstDefault); err != nil {
		t.Error(err)
		return
	}

	// 使用 IgnoreEmpty：零值不会覆盖目标字段
	dstIgnoreEmpty := dst
	err := CopyWithOption(src, &dstIgnoreEmpty, copier.Option{
		IgnoreEmpty: true,
		DeepCopy: true,
	})
	if err != nil {
		t.Error(err)
		return
	}

	fmt.Println("默认拷贝结果:", JsonifyIndent(dstDefault))
	fmt.Println("IgnoreEmpty 拷贝结果:", JsonifyIndent(dstIgnoreEmpty))

	if dstDefault.Age != 0 {
		t.Errorf("默认拷贝失败：期望 Age 被覆盖为 0，实际为 %d", dstDefault.Age)
	}
	if dstIgnoreEmpty.Age != 30 {
		t.Errorf("IgnoreEmpty 失效：期望 Age 保持为 30，实际为 %d", dstIgnoreEmpty.Age)
	}
	if dstIgnoreEmpty.Name != "Alice" {
		t.Errorf("Name 字段拷贝失败：期望 Alice，实际为 %s", dstIgnoreEmpty.Name)
	}
	if dstIgnoreEmpty.Gender != "Male" {
		t.Errorf("IgnoreEmpty 失效：期望 Gender 保持为 Male，实际为 %s", dstIgnoreEmpty.Gender)
	}
}

// TestCopyFromPointer 测试 from 为指针类型的拷贝
func TestCopyFromPointer(t *testing.T) {
	src := &Entity{
		Name: "Alice",
		Age: 30,
		Gender: "Female",
	}

	var dst Entity
	if err := Copy(src, &dst); err != nil {
		t.Error(err)
		return
	}

	fmt.Println("from 指针:", JsonifyIndent(src))
	fmt.Println("to 值:", JsonifyIndent(dst))

	if dst.Name != src.Name || dst.Age != src.Age || dst.Gender != src.Gender {
		t.Error("指针来源拷贝失败：字段不一致")
	}
}
