// - opts: 拷贝选项
//
// 可用选项：
// - IgnoreEmpty: 忽略空值字段（零值不会覆盖目标字段）
// - DeepCopy: 强制深度拷贝（默认已启用）
//
// 使用示例：
//
//	type User struct {
//	 Name string
//	 Age int
//	}
//	src := User{Name: "Alice"} // Age 为零值
//	dst := User{Name: "Bob", Age: 30}
//
//	// 不忽略空值：dst.Age 会被覆盖为 0
//	err := Copy(src, &dst)
//	// 结果：dst = {Name: "Alice", Age: 0}
//
//	// 忽略空值：dst.Age 保持原值
//	err := CopyWithOption(src, &dst, copier.Option{IgnoreEmpty: true})
//	// 结果：dst = {Name: "Alice", Age: 30}
func CopyWithOption(from any, to any, opt copier.Option) (err error) {
	return copier.CopyWithOption(to, from, opt)
}

// DeepCopy 深度拷贝函数（泛型版本）
//
// 功能说明：
// 提供类型安全的深度拷贝，返回拷贝后的新对象
//
// 参数说明：
// - from: 源数据
//
// 返回值：
// - T: 拷贝后的新对象
// - error: 拷贝失败时返回错误
//
// 使用示例：
//
//	type User struct {
//	 Name string
//	 Age int
//	}
//	src := User{Name: "Alice", Age: 30}
//
//	// 方式1：使用 Copy（需要预先声明变量）
//	var dst User
//	err := Copy(src, &dst)
//
//	// 方式2：使用 DeepCopy（更简洁）
//	dst, err := DeepCopy(src)
//	// dst 是新的 User 对象
//
// 注意：
// 1. 此函数适用于相同类型的拷贝
// 2. 如需不同类型间拷贝，请使用 Copy 函数
func DeepCopy[T any](from T) (T, error) {
	var to T
	err := copier.Copy(&to, &from)
	return to, err
}

// MustCopy 深度拷贝函数 - panic 版本
//
// 功能说明：
// 与 Copy 函数功能相同，但拷贝失败时会直接 panic
// 适用于确定不会出错的场景，可以简化错误处理代码
//
// 参数说明：
// - from: 源数据（可以是值或指针）
// - to: 目标数据（必须是指针，用于接收拷贝结果）
//
// 使用场景：
// 1. 初始化阶段的数据拷贝（如配置初始化）
// 2. 测试代码中的数据准备
// 3. 确定类型兼容的简单拷贝
//
// 使用示例：
//
// 1. 结构体拷贝：
//
//	type User struct {
//	 Name string
//	 Age int
//	}
//	src := User{Name: "Alice", Age: 30}
//	var dst User
//	MustCopy(src, &dst) // 拷贝失败会 panic
//	// 无需处理 error，代码更简洁
//
// 2. 切片拷贝：
//
//	from := []int{1, 2, 3}
//	to := make([]int, 0)
//	MustCopy(from, &to) // 拷贝失败会 panic
//
// 3. 初始化配置：
//
//	var globalConfig Config
//	func init() {
//	 defaultConfig := Config{Timeout: 30, MaxRetry: 3}
//	 MustCopy(defaultConfig, &globalConfig) // 初始化失败直接 panic
//	}
//
// 注意事项：
// 1. 仅在确定不会出错的场景使用，否则建议使用 Copy 函数
// 2. 拷贝失败会导致程序 panic，请谨慎使用
// 3. 不适合在生产环境的业务逻辑中使用
// 4. 参数要求与 Copy 函数完全相同（to 必须是指针）
//
// 对比 Copy 函数：
//
//	// 使用 Copy：需要处理错误
//	var dst User
//	if err := Copy(src, &dst); err != nil {
//	 return err
//	}
//
//	// 使用 MustCopy：代码更简洁
//	var dst User
//	MustCopy(src, &dst)
func MustCopy(from any, to any) {
	if err := copier.Copy(to, from); err != nil {
		panic(err)
	}
}
