//
// 使用示例：
//
// 1. 结构体拷贝（相同类型）：
//
//	type User struct {
//	    Name string
//	    Age  int
//	}
//	src := User{Name: "Alice", Age: 30}
//	var dst User
//	err := Copy(src, &dst)  // 注意：dst 必须传指针
//
// 2. 结构体拷贝（不同类型，部分字段）：
//
//	type Entity struct {
//	    Name   string
//	    Age    int
//	    Gender string
//	}
//	type VO struct {
//	    Name   string
//	    Gender string
//	}
//	entity := Entity{Name: "Alice", Age: 30, Gender: "Female"}
//	var vo VO
//	err := Copy(entity, &vo)  // 只拷贝 Name 和 Gender 字段
//
// 3. 切片拷贝（深度拷贝）：
//
//	// 方式1：空切片（推荐）
//	from := []*int{IntPtr(1), IntPtr(2), IntPtr(3)}
//	to := make([]*int, 0)
//	err := Copy(from, &to)  // 注意：必须传 &to
//
//	// 方式2：预分配长度
//	to := make([]*int, len(from))
//	err := Copy(from, &to)
//
//	// 验证深度拷贝：修改拷贝不影响原数据
//	*to[0] = 100  // 修改拷贝
//	// from[0] 仍然是 1，不受影响
