func DeepCopyToByJson[T any](src any) (T, error) {
	var dst T

	// 序列化源对象为 JSON
	data, err := json.Marshal(src)
	if err != nil {
		return dst, err
	}

	// 反序列化 JSON 到目标对象
	err = json.Unmarshal(data, &dst)
	if err != nil {
		return dst, err
	}

