import (
	"fmt"
	"testing"
	"time"
)

// TestDeepCopyToSameType 测试相同类型之间的深度拷贝
func TestDeepCopyToSameType(t *testing.T) {
	type User struct {
		ID int64
		Name string
		Age int
		Birthday time.Time
	}

	original := User{
		ID: 1,
		Name: "john",
		Age: 18,
		Birthday: time.Now(),
	}

	copied, err := DeepCopyToByJson[User](original)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("原始对象:", JsonifyIndent(original))
	fmt.Println("拷贝对象:", JsonifyIndent(copied))
}

// TestDeepCopyPointerIssue 测试指针类型拷贝的问题
func TestDeepCopyPointerIssue(t *testing.T) {
	type UserEntity struct {
		ID *int64
		Name *string
		Age *int
		Birthday *time.Time
	}

	type UserVo struct {
		ID int64
		Name string
	}

	// 创建源对象（非指针字段）
	userVo := UserVo{
		ID: 100,
		Name: "john",
	}

	// 尝试拷贝到指针字段的结构体
	// ⚠️ 问题：JSON 无法将非指针字段转换为指针字段
	userEntity, err := DeepCopyToByJson[UserEntity](userVo)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("源对象 (UserVo):", JsonifyIndent(userVo))
	fmt.Println("目标对象 (UserEntity):", JsonifyIndent(userEntity))

	// 验证问题：指针字段应该是 nil
	if userEntity.ID != nil {
		t.Errorf("期望 ID 为 nil，但得到: %v", *userEntity.ID)
	}
	if userEntity.Name != nil {
		t.Errorf("期望 Name 为 nil，但得到: %v", *userEntity.Name)
	}

	fmt.Println("⚠️ 问题：所有指针字段都是 nil，因为 JSON 无法处理指针类型转换")
}

// TestDeepCopyWithPointers 测试指针类型之间的拷贝
func TestDeepCopyWithPointers(t *testing.T) {
	type UserEntity struct {
		ID *int64
		Name *string
		Age *int
		Birthday *time.Time
	}

	// 创建带指针字段的源对象
	original := UserEntity{
		ID: Int64Ptr(1),
		Name: StringPtr("alice"),
		Age: IntPtr(25),
		Birthday: TimePtr(time.Now()),
	}

	// 同类型拷贝（都是指针）
	copied, err := DeepCopyToByJson[UserEntity](original)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("原始对象:", JsonifyIndent(original))
	fmt.Println("拷贝对象:", JsonifyIndent(copied))

	// 验证：指针字段应该被正确拷贝
	if copied.ID == nil || *copied.ID != 1 {
		t.Error("ID 拷贝失败")
	}
	if copied.Name == nil || *copied.Name != "alice" {
		t.Error("Name 拷贝失败")
	}

	// 验证：是深拷贝，不是浅拷贝
	if copied.ID == original.ID {
		t.Error("⚠️ 问题：指针地址相同，不是真正的深拷贝")
	}
}

// TestDeepCopyTimePrecision 测试时间精度问题
func TestDeepCopyTimePrecision(t *testing.T) {
	type Event struct {
		Name string
		Timestamp time.Time
	}

	// 创建带纳秒精度的时间
	now := time.Now()
	original := Event{
		Name: "test_event",
		Timestamp: now,
	}

	copied, err := DeepCopyToByJson[Event](original)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Printf("原始时间: %v (纳秒: %d)\n", original.Timestamp, original.Timestamp.Nanosecond())
	fmt.Printf("拷贝时间: %v (纳秒: %d)\n", copied.Timestamp, copied.Timestamp.Nanosecond())

	// 验证时间精度
	if !original.Timestamp.Equal(copied.Timestamp) {
		t.Logf("⚠️ 警告：时间精度可能有微小差异")
		t.Logf("差异: %v", original.Timestamp.Sub(copied.Timestamp))
	}
}

// TestDeepCopyMissingFields 测试字段不匹配的情况
func TestDeepCopyMissingFields(t *testing.T) {
	type FullUser struct {
		ID int64
		Name string
		Email string
		Age int
		IsActive bool
	}

	type PartialUser struct {
		ID int64
		Name string
	}

	// 从完整对象拷贝到部分对象
	full := FullUser{
		ID: 1,
		Name: "bob",
		Email: "bob@example.com",
		Age: 30,
		IsActive: true,
	}

	partial, err := DeepCopyToByJson[PartialUser](full)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("完整对象:", JsonifyIndent(full))
	fmt.Println("部分对象:", JsonifyIndent(partial))
	fmt.Println("✓ 只拷贝了匹配的字段，其他字段被忽略")
}

// TestDeepCopyPrivateFields 测试私有字段的问题
func TestDeepCopyPrivateFields(t *testing.T) {
	type User struct {
		ID int64 // 公开字段
		Name string // 公开字段
		password string // 私有字段 - 无法被 JSON 序列化
	}

	original := User{
		ID: 1,
		Name: "charlie",
		password: "secret123", // 这个字段不会被拷贝
	}

	copied, err := DeepCopyToByJson[User](original)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Printf("原始对象: ID=%d, Name=%s, password=%s\n", original.ID, original.Name, original.password)
	fmt.Printf("拷贝对象: ID=%d, Name=%s, password=%s\n", copied.ID, copied.Name, copied.password)

	if copied.password != "" {
		t.Error("⚠️ 意外：私有字段不应该被拷贝")
	} else {
		fmt.Println("✓ 确认：私有字段 password 未被拷贝（为空字符串）")
	}
}

// TestDeepCopyPerformance 简单的性能对比测试
func TestDeepCopyPerformance(t *testing.T) {
	type User struct {
		ID int64
		Name string
		Email string
		Age int
		IsActive bool
	}

	user := User{
		ID: 1,
		Name: "performance_test",
		Email: "test@example.com",
		Age: 25,
		IsActive: true,
	}

	// JSON 深度拷贝
	start := time.Now()
	for i := 0; i < 10000; i++ {
		_, _ = DeepCopyToByJson[User](user)
	}
	jsonDuration := time.Since(start)

	// 直接赋值（浅拷贝）
	start = time.Now()
	for i := 0; i < 10000; i++ {
		_ = user
	}
	directDuration := time.Since(start)

	fmt.Printf("JSON 深度拷贝 10000 次耗时: %v\n", jsonDuration)
	fmt.Printf("直接赋值 10000 次耗时: %v\n", directDuration)
	fmt.Printf("性能差异: JSON 方式慢 %.2f 倍\n", float64(jsonDuration)/float64(directDuration))
}
