{"rawEvent":{"message_id":"019aa1a7778d79ce8751bb6bd8aadb0b","conversation_id":"019aa0a5a67277ddb0f8776405334a10","tool_call_id":"tooluse_SbYO6YRyTQS7icHT8Q1IZg","document":{"file_path":"/Users/jacklingo/dev/model_infrax/tool/copy.go","sub_content":"copy.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/tool/copy.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/tool/copy.go","apply_content":"package tool

import (
	"encoding/json"

	"github.com/jinzhu/copier"
)

// DeepCopy 深度拷贝对象（推荐使用）
// 使用 copier 库实现深度拷贝，相比 JSON 方式有以下优势：
// 1. 支持指针类型的自动转换（非指针 <-> 指针）
// 2. 性能更好，避免了 JSON 序列化/反序列化的开销
// 3. 支持嵌套结构、切片、Map 等复杂类型
// 4. 可以拷贝私有字段（如果类型相同）
// 5. 保持时间精度，不会有 JSON 转换导致的精度损失
//
// 注意：
// 1. 字段名需要匹配（大小写敏感）
// 2. 源对象和目标对象类型需要相同
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 拷贝后的新对象，类型与源对象相同
// - error: 如果拷贝过程中发生错误，返回错误信息
//
// 示例:
//
//	type User struct {
//	 Name string
//	 Age int
//	 Tags []string
//	}
//	original := User{Name: "Alice", Age: 30, Tags: []string{"admin", "user"}}
//	copied, err := DeepCopy(original)
//	if err != nil {
//	 // 处理错误
//	}
//	// copied 是 User 类型，无需类型转换
//	copied.Name = "Bob" // 修改拷贝不影响原对象
func DeepCopy[T any](src T) (T, error) {
	var dst T
	err := copier.Copy(&dst, &src)
	if err != nil {
		return dst, err
	}
	return dst, nil
}

// DeepCopyTo 深度拷贝对象到不同类型（推荐使用）
// 使用 copier 库实现类型转换和深度拷贝，相比 JSON 方式有以下优势：
// 1. 自动处理指针类型转换：非指针 -> 指针，指针 -> 非指针
// 2. 性能更好，避免了 JSON 序列化/反序列化的开销
// 3. 支持字段名映射（通过 struct tag）
// 4. 保持时间精度和类型信息
//
// 适用场景：
// - DTO 和 Entity 之间的转换
// - 不同层级对象之间的数据传递
// - 需要指针类型转换的场景
//
// 注意：
// 1. 字段名需要匹配（大小写敏感）
// 2. 目标类型中不存在的字段会被忽略
// 3. 源类型中不存在但目标类型存在的字段会使用零值
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 目标类型的新对象
// - error: 如果拷贝过程中发生错误，返回错误信息
//
// 示例:
//
//	type UserDTO struct {
//	 Name string
//	 Age int
//	}
//	type UserEntity struct {
//	 Name *string // 自动转换：非指针 -> 指针
//	 Age *int // 自动转换：非指针 -> 指针
//	 ID int // 这个字段在 UserDTO 中不存在，会使用零值
//	}
//	dto := UserDTO{Name: "Alice", Age: 30}
//	entity, err := DeepCopyTo[UserEntity](dto)
//	if err != nil {
//	 // 处理错误
//	}
//	// entity.Name 和 entity.Age 是指针类型，已自动转换
func DeepCopyTo[T any](src any) (T, error) {
	var dst T
	err := copier.Copy(&dst, src)
	if err != nil {
		return dst, err
	}
	return dst, nil
}

// DeepCopyWithOption 深度拷贝对象到不同类型（带选项）
// 提供更多控制选项的拷贝函数，可以自定义拷贝行为
//
// 参数:
// - src: 源对象，需要被拷贝的对象
// - opts: copier 选项，可以控制拷贝行为
//
// 返回:
// - T: 目标类型的新对象
// - error: 如果拷贝过程中发生错误，返回错误信息
//
// 示例:
//
//	// 深度拷贝，包括嵌套结构
//	entity, err := DeepCopyWithOption[UserEntity](dto, copier.Option{
//	 DeepCopy: true,
//	})
//
//	// 忽略空值字段
//	entity, err := DeepCopyWithOption[UserEntity](dto, copier.Option{
//	 IgnoreEmpty: true,
//	})
func DeepCopyWithOption[T any](src any, opt copier.Option) (T, error) {
	var dst T
	err := copier.CopyWithOption(&dst, src, opt)
	if err != nil {
		return dst, err
	}
	return dst, nil
}

// ==================== 以下是基于 JSON 的旧实现，保留用于兼容性 ====================
// 注意：以下函数使用 JSON 序列化/反序列化实现，存在以下限制：
// 1. 无法处理指针类型转换（非指针 -> 指针 会得到 nil）
// 2. 性能较差（涉及 JSON 编解码）
// 3. 私有字段无法拷贝
// 4. 时间精度可能损失
// 5. 无法处理函数、channel 等特殊类型
//
// 建议：新代码请使用 DeepCopy 或 DeepCopyTo 函数

// DeepCopyByJson 深度拷贝对象（JSON 方式，不推荐）
// 使用 JSON 序列化/反序列化实现深度拷贝，支持泛型类型
//
// ⚠️ 限制：
// 1. 源对象必须可以被 JSON 序列化（字段需要导出或有 json tag）
// 2. 不会拷贝未导出的字段
// 3. 不会拷贝函数、channel 等不可序列化的类型
// 4. 时间类型会被转换为 RFC3339 格式字符串后再解析，可能损失精度
// 5. 性能较差
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 拷贝后的新对象，类型与源对象相同
// - error: 如果拷贝过程中发生错误（序列化或反序列化失败），返回错误信息
//
// 示例:
//
//	type User struct {
//	 Name string
//	 Age int
//	 Tags []string
//	}
//	original := User{Name: "Alice", Age: 30, Tags: []string{"admin", "user"}}
//	copied, err := DeepCopyByJson(original)
//	if err != nil {
//	 // 处理错误
//	}
//	// copied 是 User 类型，无需类型转换
//	copied.Name = "Bob" // 修改拷贝不影响原对象
func DeepCopyByJson[T any](src T) (T, error) {
	var dst T

	// 序列化源对象为 JSON
	data, err := json.Marshal(src)
	if err != nil {
		return dst, err
	}

	// 反序列化 JSON 到目标对象
	err = json.Unmarshal(data, &dst)
	if err != nil {
		return dst, err
	}

	return dst, nil
}

// DeepCopyToByJson 深度拷贝对象到不同类型（JSON 方式，不推荐）
// 使用 JSON 序列化/反序列化实现类型转换和深度拷贝
//
// ⚠️ 限制：
// 1. 无法处理指针类型转换（非指针字段 -> 指针字段会得到 nil）
// 2. 源类型和目标类型的字段名需要匹配（或通过 json tag 匹配）
// 3. 目标类型中不存在的字段会被忽略
// 4. 源类型中不存在但目标类型存在的字段会使用零值
// 5. 性能较差
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 目标类型的新对象
// - error: 如果拷贝过程中发生错误（序列化或反序列化失败），返回错误信息
//
// 示例:
//
//	type UserDTO struct {
//	 Name string `json:"name"`
//	 Age int `json:"age"`
//	}
//	type UserEntity struct {
//	 Name string `json:"name"`
//	 Age int `json:"age"`
//	 ID int `json:"id"` // 这个字段在 UserDTO 中不存在，会使用零值
//	}
//	dto := UserDTO{Name: "Alice", Age: 30}
//	entity, err := DeepCopyToByJson[UserEntity](dto)
//	if err != nil {
//	 // 处理错误
//	}
//	// entity 是 UserEntity 类型，无需类型转换
//
// ⚠️ 注意：如果 UserEntity 的字段是指针类型，JSON 方式无法正确转换，请使用 DeepCopyTo 函数
func DeepCopyToByJson[T any](src any) (T, error) {
	var dst T

	// 序列化源对象为 JSON
	data, err := json.Marshal(src)
	if err != nil {
		return dst, err
	}

	// 反序列化 JSON 到目标对象
	err = json.Unmarshal(data, &dst)
	if err != nil {
		return dst, err
	}

	return dst, nil
}
