import (
	"fmt"
	"testing"
	"time"

	"github.com/jinzhu/copier"
)

// TestDeepCopy 测试使用 copier 的同类型深度拷贝
func TestDeepCopy(t *testing.T) {
	type User struct {
		ID int64
		Name string
		Age int
		Birthday time.Time
		Tags []string
	}

	original := User{
		ID: 1,
		Name: "Alice",
		Age: 30,
		Birthday: time.Now(),
		Tags: []string{"admin", "user"},
	}

	// 使用 copier 进行深度拷贝
	copied, err := DeepCopy(original)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("原始对象:", JsonifyIndent(original))
	fmt.Println("拷贝对象:", JsonifyIndent(copied))

	// 验证：修改拷贝不影响原对象
	copied.Name = "Bob"
	copied.Tags[0] = "guest"

	if original.Name == copied.Name {
		t.Error("深度拷贝失败：修改拷贝影响了原对象")
	}
	fmt.Println("✓ 深度拷贝成功：修改拷贝不影响原对象")
}

// TestDeepCopyTo 测试使用 copier 的跨类型拷贝（解决指针转换问题）
func TestDeepCopyTo(t *testing.T) {
	type UserEntity struct {
		ID *int64 // 指针字段
		Name *string // 指针字段
		Age *int // 指针字段
		Birthday *time.Time // 指针字段
	}

	type UserVo struct {
		ID int64 // 非指针字段
		Name string // 非指针字段
	}

	// 创建源对象（非指针字段）
	e := UserVo{
		ID: 3,
		Name: "John",
	}

	// 使用 copier 拷贝到指针字段的结构体
	// ✓ copier 可以自动处理非指针 -> 指针的转换
	v, err := DeepCopyTo[UserEntity](e)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("源对象 (UserVo):", JsonifyIndent(e))
	fmt.Println("目标对象 (UserEntity):", JsonifyIndent(v))

	// 验证：指针字段应该被正确赋值
	if v.ID == nil {
		t.Error("❌ ID 应该有值，但得到 nil")
	} else if *v.ID != 3 {
		t.Errorf("❌ ID 期望为 3，但得到: %d", *v.ID)
	} else {
		fmt.Printf("✓ ID 正确转换：%d -> *%d\n", e.ID, *v.ID)
	}

	if v.Name == nil {
		t.Error("❌ Name 应该有值，但得到 nil")
	} else if *v.Name != "John" {
		t.Errorf("❌ Name 期望为 John，但得到: %s", *v.Name)
	} else {
		fmt.Printf("✓ Name 正确转换：%s -> *%s\n", e.Name, *v.Name)
	}

	// Age 和 Birthday 在源对象中不存在，应该是 nil
	if v.Age != nil {
		t.Error("❌ Age 应该是 nil（源对象中不存在）")
	}
	if v.Birthday != nil {
		t.Error("❌ Birthday 应该是 nil（源对象中不存在）")
	}

	fmt.Println("✓ copier 成功处理了非指针 -> 指针的类型转换")
}

// TestDeepCopyToReverse 测试指针 -> 非指针的转换
func TestDeepCopyToReverse(t *testing.T) {
	type UserEntity struct {
		ID *int64
		Name *string
		Age *int
	}

	type UserVo struct {
		ID int64
		Name string
		Age int
	}

	// 创建源对象（指针字段）
	entity := UserEntity{
		ID: Int64Ptr(100),
		Name: StringPtr("Alice"),
		Age: IntPtr(25),
	}

	// 使用 copier 拷贝到非指针字段的结构体
	// ✓ copier 可以自动处理指针 -> 非指针的转换
	vo, err := DeepCopyTo[UserVo](entity)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("源对象 (UserEntity):", JsonifyIndent(entity))
	fmt.Println("目标对象 (UserVo):", JsonifyIndent(vo))

	// 验证：非指针字段应该被正确赋值
	if vo.ID != 100 {
		t.Errorf("❌ ID 期望为 100，但得到: %d", vo.ID)
	} else {
		fmt.Printf("✓ ID 正确转换：*%d -> %d\n", *entity.ID, vo.ID)
	}

	if vo.Name != "Alice" {
		t.Errorf("❌ Name 期望为 Alice，但得到: %s", vo.Name)
	} else {
		fmt.Printf("✓ Name 正确转换：*%s -> %s\n", *entity.Name, vo.Name)
	}

	fmt.Println("✓ copier 成功处理了指针 -> 非指针的类型转换")
}

// TestDeepCopyWithOption 测试带选项的深度拷贝
func TestDeepCopyWithOption(t *testing.T) {
	type Address struct {
		City string
		Country string
	}

	type User struct {
		Name string
		Age int
		Address Address
	}

	original := User{
		Name: "Bob",
		Age: 0, // 零值
		Address: Address{
			City: "Beijing",
			Country: "China",
		},
	}

	// 测试 IgnoreEmpty 选项
	t.Run("IgnoreEmpty", func(t *testing.T) {
		target := User{
			Name: "Original",
			Age: 30,
		}

		err := copier.CopyWithOption(&target, &original, copier.Option{
			IgnoreEmpty: true, // 忽略空值字段
		})
		if err != nil {
			t.Fatal(err)
		}

		// Age 是零值，应该被忽略，保持原值
		if target.Age != 30 {
			t.Errorf("❌ IgnoreEmpty 失败：Age 应该保持 30，但得到: %d", target.Age)
		} else {
			fmt.Println("✓ IgnoreEmpty 成功：零值字段被忽略")
		}

		// Name 不是零值，应该被拷贝
		if target.Name != "Bob" {
			t.Errorf("❌ Name 应该被拷贝为 Bob，但得到: %s", target.Name)
		}
	})

	// 测试 DeepCopy 选项
	t.Run("DeepCopy", func(t *testing.T) {
		copied, err := DeepCopyWithOption[User](original, copier.Option{
			DeepCopy: true, // 深度拷贝嵌套结构
		})
		if err != nil {
			t.Fatal(err)
		}

		// 修改拷贝的嵌套结构
		copied.Address.City = "Shanghai"

		// 验证原对象不受影响
		if original.Address.City != "Beijing" {
			t.Error("❌ DeepCopy 失败：修改拷贝影响了原对象")
		} else {
			fmt.Println("✓ DeepCopy 成功：嵌套结构被深度拷贝")
		}
	})
}

// TestDeepCopyPerformance 性能对比测试：copier vs JSON
func TestDeepCopyPerformance(t *testing.T) {
	type User struct {
		ID int64
		Name string
		Email string
		Age int
		IsActive bool
		Tags []string
	}

	user := User{
		ID: 1,
		Name: "performance_test",
		Email: "test@example.com",
		Age: 25,
		IsActive: true,
		Tags: []string{"tag1", "tag2", "tag3"},
	}

	iterations := 10000

	// 测试 copier 性能
	start := time.Now()
	for i := 0; i < iterations; i++ {
		_, err := DeepCopy(user)
		if err != nil {
			t.Fatal(err)
		}
	}
	copierDuration := time.Since(start)

	// 测试 JSON 性能
	start = time.Now()
	for i := 0; i < iterations; i++ {
		_, err := DeepCopyByJson(user)
		if err != nil {
			t.Fatal(err)
		}
	}
	jsonDuration := time.Since(start)

	fmt.Printf("\n性能对比（%d 次拷贝）:\n", iterations)
	fmt.Printf(" copier 方式: %v\n", copierDuration)
	fmt.Printf(" JSON 方式: %v\n", jsonDuration)
	fmt.Printf(" 性能提升: %.2fx\n", float64(jsonDuration)/float64(copierDuration))

	if copierDuration > jsonDuration {
		t.Logf("⚠️ 警告：copier 比 JSON 慢，这不太正常")
	} else {
		fmt.Printf("✓ copier 比 JSON 快 %.2f 倍\n", float64(jsonDuration)/float64(copierDuration))
	}
}

// TestDeepCopyToByJson_PointerIssue 对比测试：展示 JSON 方式的指针转换问题
func TestDeepCopyToByJson_PointerIssue(t *testing.T) {
	type UserEntity struct {
		ID *int64
		Name *string
	}

	type UserVo struct {
		ID int64
		Name string
	}

	vo := UserVo{
		ID: 999,
		Name: "TestUser",
	}

	// 使用 JSON 方式（会失败）
	t.Run("JSON方式-失败", func(t *testing.T) {
		entity, err := DeepCopyToByJson[UserEntity](vo)
		if err != nil {
			t.Fatal(err)
		}

		fmt.Println("\n❌ JSON 方式的问题：")
		fmt.Println("源对象:", JsonifyIndent(vo))
		fmt.Println("目标对象:", JsonifyIndent(entity))

		// 验证：指针字段应该是 nil（JSON 无法处理）
		if entity.ID != nil {
			t.Error("意外：JSON 方式竟然成功转换了指针（这不应该发生）")
		} else {
			fmt.Println("✗ ID 字段为 nil（JSON 无法处理非指针 -> 指针转换）")
		}

		if entity.Name != nil {
			t.Error("意外：JSON 方式竟然成功转换了指针（这不应该发生）")
		} else {
			fmt.Println("✗ Name 字段为 nil（JSON 无法处理非指针 -> 指针转换）")
		}
	})

	// 使用 copier 方式（会成功）
	t.Run("copier方式-成功", func(t *testing.T) {
		entity, err := DeepCopyTo[UserEntity](vo)
		if err != nil {
			t.Fatal(err)
		}

		fmt.Println("\n✓ copier 方式的优势：")
		fmt.Println("源对象:", JsonifyIndent(vo))
		fmt.Println("目标对象:", JsonifyIndent(entity))

		// 验证：指针字段应该被正确赋值
		if entity.ID == nil || *entity.ID != 999 {
			t.Error("copier 转换失败")
		} else {
			fmt.Printf("✓ ID 字段正确转换：%d -> *%d\n", vo.ID, *entity.ID)
		}

		if entity.Name == nil || *entity.Name != "TestUser" {
			t.Error("copier 转换失败")
		} else {
			fmt.Printf("✓ Name 字段正确转换：%s -> *%s\n", vo.Name, *entity.Name)
		}
	})
}

// TestDeepCopyTimePrecision 测试时间精度保持
func TestDeepCopyTimePrecision(t *testing.T) {
	type Event struct {
		Name string
		Timestamp time.Time
	}

	// 创建带纳秒精度的时间
	now := time.Now()
	original := Event{
		Name: "test_event",
		Timestamp: now,
	}

	// 使用 copier
	copierResult, err := DeepCopy(original)
	if err != nil {
		t.Fatal(err)
	}

	// 使用 JSON
	jsonResult, err := DeepCopyByJson(original)
	if err != nil {
		t.Fatal(err)
	}

	fmt.Println("\n时间精度对比：")
	fmt.Printf("原始时间: %v (纳秒: %d)\n", original.Timestamp, original.Timestamp.Nanosecond())
	fmt.Printf("copier拷贝: %v (纳秒: %d)\n", copierResult.Timestamp, copierResult.Timestamp.Nanosecond())
	fmt.Printf("JSON拷贝: %v (纳秒: %d)\n", jsonResult.Timestamp, jsonResult.Timestamp.Nanosecond())

	// 验证 copier 保持精度
	if !original.Timestamp.Equal(copierResult.Timestamp) {
		t.Error("❌ copier 时间精度丢失")
	} else {
		fmt.Println("✓ copier 完美保持时间精度")
	}

	// JSON 可能有精度损失
	if !original.Timestamp.Equal(jsonResult.Timestamp) {
		fmt.Println("⚠️ JSON 方式可能有时间精度损失")
		fmt.Printf(" 差异: %v\n", original.Timestamp.Sub(jsonResult.Timestamp))
	}
}
