// TestDeepCopySlice 测试切片的深度拷贝
func TestDeepCopySlice(t *testing.T) {
	// 创建源切片
	from := make([]*int, 0)
	from = append(from, IntPtr(1))
	from = append(from, IntPtr(2))
	from = append(from, IntPtr(3))

	// 方式1：使用指针传递（推荐）
	// 注意：Copy 函数需要传递指针才能修改切片本身
	to := make([]*int, 0)
	err := Copy(from, &to) // 传递 &to 而不是 to
	if err != nil {
		t.Error(err)
		return
	}

	fmt.Println("拷贝后的切片:", to)
	fmt.Printf("切片长度: %d, 容量: %d\n", len(to), cap(to))

	// 验证：拷贝成功
	if len(to) != 3 {
		t.Errorf("拷贝失败：期望长度为 3，实际为 %d", len(to))
		return
	}

	// 验证：深度拷贝（修改拷贝不影响原切片）
	if to[0] != nil {
		*to[0] = 100 // 修改拷贝的第一个元素
	}

	fmt.Println("\n修改拷贝后:")
	fmt.Println("原切片 from:", JsonifyIndent(from))
	fmt.Println("拷贝切片 to:", JsonifyIndent(to))

	// 验证：原切片未被修改
	if from[0] != nil && *from[0] != 1 {
		t.Error("❌ 深度拷贝失败：修改拷贝影响了原切片")
	} else {
		fmt.Println("✓ 深度拷贝成功：修改拷贝不影响原切片")
	}
}

// TestDeepCopySlice_Alternative 测试切片拷贝的另一种方式
func TestDeepCopySlice_Alternative(t *testing.T) {
	// 创建源切片
	from := []*int{IntPtr(1), IntPtr(2), IntPtr(3)}

	// 方式2：先初始化目标切片的长度
	to := make([]*int, len(from))
	err := Copy(from, &to)
	if err != nil {
		t.Error(err)
		return
	}

	fmt.Println("拷贝后的切片:", JsonifyIndent(to))

	// 验证长度
	if len(to) != len(from) {
		t.Errorf("拷贝失败：期望长度为 %d，实际为 %d", len(from), len(to))
	}
}

// TestDeepCopyStruct 测试结构体的深度拷贝
func TestDeepCopyStruct(t *testing.T) {
	// 创建源对象
	entity := Entity{
		Name: "Alice",
		Age: 30,
		Gender: "Female",
	}

	// 拷贝到相同类型
	var copied Entity
	err := Copy(entity, &copied)
	if err != nil {
		t.Error(err)
		return
	}

	fmt.Println("原对象:", JsonifyIndent(entity))
	fmt.Println("拷贝对象:", JsonifyIndent(copied))

	// 验证：修改拷贝不影响原对象
	copied.Name = "Bob"
	if entity.Name == copied.Name {
		t.Error("❌ 拷贝失败：修改拷贝影响了原对象")
	} else {
		fmt.Println("✓ 拷贝成功：修改拷贝不影响原对象")
	}
}

// TestDeepCopyStructToVO 测试结构体到 VO 的拷贝（部分字段）
func TestDeepCopyStructToVO(t *testing.T) {
	// 创建源对象
	entity := Entity{
		Name: "Alice",
		Age: 30,
		Gender: "Female",
	}

	// 拷贝到 VO（只包含部分字段）
	var vo VO
	err := Copy(entity, &vo)
	if err != nil {
		t.Error(err)
		return
	}

	fmt.Println("Entity:", JsonifyIndent(entity))
	fmt.Println("VO:", JsonifyIndent(vo))

	// 验证：只拷贝了匹配的字段
	if vo.Name != entity.Name {
		t.Error("❌ Name 字段拷贝失败")
	}
	if vo.Gender != entity.Gender {
		t.Error("❌ Gender 字段拷贝失败")
	}

	fmt.Println("✓ 部分字段拷贝成功")
}

// TestCopySliceCommonMistakes 演示切片拷贝的常见错误
func TestCopySliceCommonMistakes(t *testing.T) {
	from := []*int{IntPtr(1), IntPtr(2), IntPtr(3)}

	t.Run("错误方式1-不传指针", func(t *testing.T) {
		to := make([]*int, 0)
		// ❌ 错误：不传指针，to 不会被修改
		err := Copy(from, to) // 应该是 &to
		if err != nil {
			fmt.Println("✓ 正确：copier 检测到错误并返回 error")
		}
		fmt.Printf("to 的长度: %d (期望: 3)\n", len(to))
	})

	t.Run("正确方式-传指针", func(t *testing.T) {
		to := make([]*int, 0)
		// ✓ 正确：传指针，to 会被修改
		err := Copy(from, &to)
		if err != nil {
			t.Error(err)
			return
		}
		fmt.Printf("✓ to 的长度: %d (期望: 3)\n", len(to))
		if len(to) != 3 {
			t.Error("拷贝失败")
		}
	})
}
