	"./application.yml", // 当前目录下的配置文件
	"./assets/application.yml", // assets目录下的配置文件
	"/Applications/jen/application.yml", // 系统安装目录下的配置文件
	"/Applications/jen/assets/application.yml", // 系统安装目录assets子目录下的配置文件
}

// defaultGoFile 默认要执行的 Go 文件
const defaultGoFile = "model_infra.go"

// main 主函数，程序入口点
// 负责解析命令行参数、初始化应用、启动代码生成流程
//
// 工作模式：
// 1. 默认模式：如果当前目录存在 model_infra.go 文件，直接执行它
// 2. 配置模式：当用户明确使用 --config 参数时，从 YAML 配置文件加载
//
// 支持的命令行参数：
// -c, --config: 指定配置文件路径（可选，指定后进入配置模式）
//
// 使用示例：
// jen # 默认执行 model_infra.go（如果存在）
// jen -c ./my-config.yml # 使用指定的配置文件
// jen --config /path/to/config.yml # 使用长格式参数指定配置文件
func main() {
	// 定义命令行参数
	configPath := flag.StringP("config", "c", "", "配置文件路径（指定后使用配置文件模式）")
	flag.Parse()

	// 判断用户是否明确指定了 --config 参数
	configSpecified := false
	flag.Visit(func(f *flag.Flag) {
		if f.Name == "config" {
			configSpecified = true
		}
	})

	// 模式1: 默认模式 - 执行 model_infra.go 文件
	if !configSpecified {
		// 检查当前目录是否存在 model_infra.go 文件
		if fileExists(defaultGoFile) {
			log.Printf(" 检测到 %s 文件，使用默认模式执行...", defaultGoFile)
			if err := runGoFile(defaultGoFile); err != nil {
				log.Fatalf("❌ 执行 %s 失败: %v", defaultGoFile, err)
			}
			log.Println(" 程序执行完成")
			return
		}

		// 如果没有 model_infra.go 文件，提示用户
		log.Printf("⚠️ 当前目录未找到 %s 文件", defaultGoFile)
		log.Println(" 提示：")
		log.Println(" 1. 创建 model_infra.go 文件来定义代码生成逻辑")
		log.Println(" 2. 或使用 --config 参数指定配置文件")
		log.Println(" 示例: jen --config ./application.yml")
		os.Exit(1)
	}

	// 模式2: 配置文件模式 - 从 YAML 加载配置
	log.Println(" 使用配置文件模式...")

	appInstance, err := InitializeApp(*configPath)
	if err != nil {
		log.Printf("⚠️ 使用配置文件 %s 失败: %v", *configPath, err)
		log.Println(" 尝试使用默认配置文件路径...")

		// 遍历默认配置文件路径列表
		for _, path := range defaultConfigPaths {
			log.Printf(" 尝试配置文件: %s", path)
			appInstance, err = InitializeApp(path)
			if err == nil {
				log.Printf("✅ 成功加载配置文件: %s", path)
				break
			}
		}

		if err != nil {
			log.Fatalf("❌ 无法找到可用的配置文件，尝试的路径: %v\n最后错误: %v", defaultConfigPaths, err)
		}
	}

	log.Println(" 开始执行代码生成...")
	if err = appInstance.Run(); err != nil {
		log.Fatalf("❌ 运行应用失败: %v", err)
	}

	log.Println(" 程序执行完成")
}

// fileExists 检查文件是否存在
// 参数:
// filename: 要检查的文件路径
// 返回:
// bool: 文件存在返回 true，否则返回 false
func fileExists(filename string) bool {
	info, err := os.Stat(filename)
	if os.IsNotExist(err) {
		return false
	}
	return !info.IsDir()
}

// runGoFile 执行指定的 Go 文件
// 使用 go run 命令执行文件，并将输出重定向到当前进程的标准输出/错误输出
// 参数:
// filename: 要执行的 Go 文件路径
// 返回:
// error: 执行过程中的错误，nil 表示成功
func runGoFile(filename string) error {
	// 获取文件的绝对路径
	absPath, err := filepath.Abs(filename)
	if err != nil {
		return err
	}

	log.Printf(" 执行文件: %s", absPath)

	// 创建 go run 命令
	cmd := exec.Command("go", "run", absPath)

	// 将命令的输出重定向到当前进程的标准输出和错误输出
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin

	// 执行命令
	return cmd.Run()
}
