func NewAppFromBuilder(builder *config.ConfiggerBuilder) (*App, error) {
	// 构建配置对象
	cfg, err := builder.Build()
	if err != nil {
		return nil, fmt.Errorf("构建配置失败: %w", err)
	}

	// 基于配置创建代码生成器
	gen := generator.NewGenerator(cfg)

	// 创建并返回应用实例
	return NewApp(cfg, gen), nil
}

