		// 生成所有表
		AllTables().
		// 配置输出路径
		OutputPath("./output").
		// 忽略表名前缀（如 t_user -> User）
		IgnoreTableNamePrefix(true).
		// 只为有索引的字段生成CRUD方法
		CrudOnlyIdx(true).
		// 配置包名
		Packages("model/entity", "model/query", "model/view", "dao", "tool").
		// 构建配置并生成代码
		BuildAndGenerate()

	if err != nil {
		log.Fatalf("❌ 生成失败: %v", err)
	}

