// 这样用户可以在多个位置放置配置文件，提高灵活性
var defaultConfigPaths = []string{
	"./application.yml", // 当前目录下的配置文件
	"./assets/application.yml", // assets目录下的配置文件
	"/Applications/jen/application.yml", // 系统安装目录下的配置文件
	"/Applications/jen/assets/application.yml", // 系统安装目录assets子目录下的配置文件
}

// defaultInfraxFilePath 默认的 model_infrax.go 文件路径
const defaultInfraxFilePath = "./model_infrax.go"

// main 主函数，程序入口点
// 负责解析命令行参数、初始化应用、启动代码生成流程
//
// 支持的命令行参数：
//
//	-c, --config: 指定配置文件路径（可选，如果不指定则使用 model_infrax.go）
//
// 使用示例：
//
//	jen # 使用 model_infrax.go 文件中的配置
//	jen -c ./my-config.yml # 使用指定的配置文件
//	jen --config /path/to/config.yml # 使用长格式参数指定配置文件
func main() {
	configPath := flag.StringP("config", "c", "", "配置文件路径（可选，默认使用 model_infrax.go）")
	flag.Parse()

	var err error
	var appInstance *App

	// 如果用户指定了配置文件，则使用配置文件模式
	if *configPath != "" {
		log.Printf(" 使用配置文件模式: %s", *configPath)
		appInstance, err = InitializeApp(*configPath)
		if err != nil {
			log.Fatalf("❌ 加载配置文件失败: %v", err)
		}
	} else {
		// 默认使用 model_infrax.go 文件模式
		log.Println(" 查找 model_infrax.go 文件...")

		if _, err := os.Stat(defaultInfraxFilePath); err == nil {
			log.Printf("✅ 找到配置文件: %s", defaultInfraxFilePath)
			appInstance, err = initializeAppFromGoFile(defaultInfraxFilePath)
			if err != nil {
				log.Fatalf("❌ 从 model_infrax.go 加载配置失败: %v", err)
			}
		} else {
			// 如果没有 model_infrax.go，尝试使用默认配置文件路径
			log.Println("⚠️ 未找到 model_infrax.go 文件")
			log.Println(" 尝试使用默认配置文件路径...")

			for _, path := range defaultConfigPaths {
				log.Printf(" 尝试配置文件: %s", path)
				appInstance, err = InitializeApp(path)
				if err == nil {
					log.Printf("✅ 成功加载配置文件: %s", path)
					break
				}
			}

			if err != nil {
				log.Fatalf("❌ 无法找到可用的配置，请创建 model_infrax.go 文件或指定配置文件\n"+
					"提示: 创建 model_infrax.go 文件并定义 Infrax() 函数，或使用 -c 参数指定配置文件\n"+
					"最后错误: %v", err)
			}
		}
	}

	log.Println(" 开始执行代码生成...")
	if err = appInstance.Run(); err != nil {
		log.Fatalf("❌ 运行应用失败: %v", err)
	}

	log.Println(" 程序执行完成")
}

// initializeAppFromGoFile 从 Go 文件加载配置并初始化应用
// 这个函数会执行 model_infrax.go 文件中的 Infrax() 函数来获取配置
//
// 参数:
// - goFilePath: Go 文件路径
//
// 返回:
// - *App: 初始化完成的应用实例
// - error: 初始化过程中的错误
func initializeAppFromGoFile(goFilePath string) (*App, error) {
	// 获取文件的绝对路径
	absPath, err := filepath.Abs(goFilePath)
	if err != nil {
		return nil, fmt.Errorf("获取文件绝对路径失败: %w", err)
	}

	// 获取文件所在目录
	dir := filepath.Dir(absPath)

	// 创建临时的 main.go 文件来执行 Infrax() 函数
	tempMainContent := `package main

import (
	"encoding/json"
	"fmt"
	"log"

	"github.com/LingoJack/model_infrax"
)

func main() {
	// 调用用户定义的 Infrax() 函数获取配置
	builder := Infrax()
	if builder == nil {
		log.Fatal("Infrax() 函数返回 nil")
	}

	// 执行代码生成
	err := model_infrax.Generate(builder)
	if err != nil {
		log.Fatalf("代码生成失败: %v", err)
	}
}
`

	// 创建临时文件
	tempFile := filepath.Join(dir, ".jen_temp_main.go")
	if err := os.WriteFile(tempFile, []byte(tempMainContent), 0644); err != nil {
		return nil, fmt.Errorf("创建临时文件失败: %w", err)
	}
	defer os.Remove(tempFile) // 确保清理临时文件

	log.Println(" 编译并执行 model_infrax.go...")

	// 使用 go run 执行临时文件和用户的 model_infrax.go
	cmd := exec.Command("go", "run", tempFile, goFilePath)
	cmd.Dir = dir
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	if err := cmd.Run(); err != nil {
		return nil, fmt.Errorf("执行 model_infrax.go 失败: %w\n"+
			"请确保 model_infrax.go 文件中定义了 Infrax() 函数，"+
			"该函数应返回 *config.ConfiggerBuilder 类型", err)
	}

	// 由于代码已经在子进程中执行完成，这里返回一个空的 App 实例
	// 实际上不会再执行 Run() 方法
	return &App{}, nil
}
