// Infrax 配置文件定义函数
// 用户可以在这个函数中配置代码生成的各种参数
//
// 使用示例：
// 直接在当前目录创建 model_infrax.go 文件，然后运行 jen 命令即可
func Infrax() *config.ConfiggerBuilder {
	return config.NewBuilder().
		// 配置数据库连接
		DatabaseMode("localhost", 3306, "mydb", "root", "password").

		// 配置表名，支持多个表
		Tables("users", "orders", "products").

		// 或者使用所有表（如果不想逐个指定）
		// AllTables().

		// 配置输出路径
		OutputPath("./generated").

		// 可选：配置包名（默认为 "model"）
		PackageName("models").

		// 可选：配置表前缀过滤
		TablePrefixFilter("app_").

		// 可选：配置框架类型（支持 "gorm" 和 "itea"）
		Framework("gorm").

		// 可选：是否启用索引字段优化
		EnableIndexOptimization(true).

		// 可选：是否生成 JSON 标签
		EnableJSONTags(true).

		// 可选：是否生成 GORM 标签
		EnableGORMTags(true).

		// 可选：自定义字段类型映射
		// FieldTypeMapping(map[string]string{
		// "varchar": "string",
		// "int": "int64",
		// }).

		// 可选：排除某些字段
		// ExcludeFields("created_at", "updated_at").

		// 可选：自定义字段标签
		// CustomTags(map[string]map[string]string{
		// "name": {"validate": "required"},
		// }).

		// 可选：是否生成测试文件
		GenerateTests(false)
}

// InfraxWithConfig 返回配置构建器和额外的配置选项
// 提供更灵活的配置方式
func InfraxWithConfig() (*config.ConfiggerBuilder, map[string]interface{}) {
	builder := config.NewBuilder().
		DatabaseMode("localhost", 3306, "mydb", "root", "password").
		AllTables().
		OutputPath("./generated").
		Framework("gorm").
		EnableIndexOptimization(true).
		EnableJSONTags(true).
		EnableGORMTags(true)

	// 额外配置选项
	extraConfig := map[string]interface{}{
		"author": "Model Infrax Generator",
		"generate_time": "auto",
		"use_custom_types": true,
		"generate_docs": true,
	}

	return builder, extraConfig
}

// SimpleInfrax 简单配置示例
