func SimpleInfrax() *config.ConfiggerBuilder {
	return config.NewBuilder().
		DatabaseMode("localhost", 3306, "test_db", "root", "").
		AllTables().
		OutputPath("./models").
		Framework("gorm")
}

// ProductionInfrax 生产环境配置示例
