		DatabaseMode("prod-db-host", 3306, "production_db", "app_user", "secure_password").
		Tables("users", "orders", "products", "categories").
		OutputPath("./internal/models").
		PackageName("models").
		Framework("gorm").
		EnableIndexOptimization(true).
		EnableJSONTags(true).
		EnableGORMTags(true).
		GenerateTests(true).
		TablePrefixFilter("app_").
		ExcludeFields("password_hash", "deleted_at")
}","instruction":"创建 model_infrax.go 文件，提供多种配置方式供用户选择使用","apply_mode":"manual"}},"timestamp":1763623460,"type":"TOOL_CALL_ARGS"}

