// tryLoadFromGoFile 尝试从 model_infrax.go 文件加载配置
// 优先检查当前目录，然后检查父目录
func tryLoadFromGoFile() (interface{}, error) {
	goFileName := "model_infrax.go"

	// 检查当前目录
	if _, err := os.Stat(goFileName); err == nil {
		log.Printf(" 找到 %s 文件在当前目录", goFileName)
		return loadGoConfig(goFileName)
	}

	// 检查父目录
	parentDir := ".."
	parentGoFile := filepath.Join(parentDir, goFileName)
	if _, err := os.Stat(parentGoFile); err == nil {
		log.Printf(" 找到 %s 文件在父目录", goFileName)
		return loadGoConfig(parentGoFile)
	}

	return nil, fmt.Errorf("未找到 %s 文件", goFileName)
}

// loadGoConfig 加载并执行 Go 配置文件中的 Infrax 函数
func loadGoConfig(filePath string) (interface{}, error) {
	// 这里我们需要动态导入和执行 Go 文件
	// 由于 Go 的静态特性，我们需要一个更灵活的方法

	// 创建临时目录来编译和运行配置文件
	tempDir := filepath.Join(os.TempDir(), "model_infrax_config")
	os.MkdirAll(tempDir, 0755)

	// 复制配置文件到临时目录
	configContent, err := os.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("读取配置文件失败: %w", err)
	}

	tempConfigPath := filepath.Join(tempDir, "config_runner.go")
	tempMainPath := filepath.Join(tempDir, "main.go")

	// 写入配置文件内容
	err = os.WriteFile(tempConfigPath, configContent, 0644)
	if err != nil {
		return nil, fmt.Errorf("写入临时配置文件失败: %w", err)
	}

	// 创建临时主程序来执行配置
	tempMainContent := `package main

import (
	"encoding/json"
	"fmt"
	"os"
)

func main() {
	// 导入配置文件中的配置
	builder := Infrax()

	// 将配置转换为 JSON 输出
	configData := map[string]interface{}{
		"database": builder.GetDatabaseConfig(),
		"tables": builder.GetTables(),
		"output": builder.GetOutputPath(),
		"options": builder.GetOptions(),
	}

	jsonData, err := json.Marshal(configData)
	if err != nil {
		fmt.Printf("错误: %v\n", err)
		os.Exit(1)
	}

	fmt.Print(string(jsonData))
}`

	err = os.WriteFile(tempMainPath, []byte(tempMainContent), 0644)
	if err != nil {
		return nil, fmt.Errorf("写入临时主程序失败: %w", err)
	}

	// 注意：这里简化实现，实际使用中可能需要更复杂的动态执行机制
	// 由于 Go 的静态编译特性，建议用户直接使用 API 而不是命令行工具

	log.Printf("ℹ️ 检测到 %s 文件，建议使用 API 方式：", filePath)
	log.Printf(" go run %s -c main.go", filePath)
	log.Printf(" 然后在代码中调用 model_infrax.Generate(model_infrax.Infrax())")

	return nil, fmt.Errorf("命令行工具暂不支持 Go 配置文件，请使用 API 方式")
}","apply_mode":"manual"}},"timestamp":1763623546,"type":"TOOL_CALL_ARGS"}

