import (
	"fmt"
	"os"

	"github.com/LingoJack/model_infrax/pkg/tool"

	"gopkg.in/yaml.v3"
)

// Configger 配置管理器
// 负责加载和管理应用配置，支持YAML格式的配置文件
// 包含代码生成模式、数据库连接、输出选项等核心配置
type Configger struct {
	// GenerateConfig 生成配置，包含数据源和表选择相关配置
	GenerateConfig GenerateConfig `yaml:"generate_config"`
	// GenerateOption 生成选项，包含输出路径、包名、文件组织等配置
	GenerateOption GenerateOption `yaml:"generate_option"`
}

// GenerateConfig 生成模式配置
// 支持两种模式：database（从数据库解析）和 statement（从SQL文件解析）
type GenerateConfig struct {
	// GenerateMode 生成模式: "database" 从数据库解析表结构 或 "statement" 从SQL文件解析表结构
	GenerateMode string `yaml:"generate_mode"`

	// database 模式配置 - 当GenerateMode为"database"时使用
	DatabaseName string `yaml:"database_name"` // 数据库名称
	Host string `yaml:"host"` // 数据库主机地址
	Port int `yaml:"port"` // 数据库端口
	URLTemplate string `yaml:"url_template"` // 数据库连接URL模板
	Username string `yaml:"username"` // 数据库用户名
	Password string `yaml:"password"` // 数据库密码

	// statement 模式配置 - 当GenerateMode为"statement"时使用
	SqlFilePath string `yaml:"sql_file_path"` // SQL文件路径，包含DDL语句

	// 通用配置 - 两种模式都使用
	AllTables bool `yaml:"all_tables"` // 是否生成所有表，true表示处理所有表，false表示仅处理TableNames指定的表
	TableNames []string `yaml:"table_names"` // 表名列表，当AllTables为false时，仅处理这些表
}

// GenerateOption 生成选项配置
// 控制代码生成的输出格式、文件组织方式、命名规则等
type GenerateOption struct {
	// OutputPath 输出路径，所有生成的代码文件将保存到此目录
	OutputPath string `yaml:"output_path"`
	// IgnoreTableNamePrefix 是否忽略表名前缀，true表示生成类名时去掉表名前缀
	IgnoreTableNamePrefix bool `yaml:"ignore_table_name_prefix"`
	// CrudOnlyIdx 是否仅CRUD索引，true表示只为CRUD操作生成索引
	CrudOnlyIdx bool `yaml:"crud_only_idx"`
	// Package 包配置，定义生成代码的包名和命名空间
	Package PackageConfig `yaml:"package_name"`
	// ModelAllInOneFile 是否将所有Model放在一个文件中，true表示生成单个大文件，false表示每个表一个文件
	ModelAllInOneFile bool `yaml:"all_model_in_one_file"`
	// ModelAllInOneFileName 当ModelAllInOneFile为true时，指定合并文件的名称
	ModelAllInOneFileName string `yaml:"all_model_in_one_file_name"`
	// UseFramework 使用的框架，影响生成代码的风格和结构
	UseFramework string `yaml:"use_framework"`
}

// PackageConfig 包名配置
// 定义不同类型代码的包名，用于命名空间管理
type PackageConfig struct {
	PoPackage string `yaml:"po_package"` // Persistent Object包名，对应数据库实体类
	DtoPackage string `yaml:"dto_package"` // Data Transfer Object包名，对应数据传输对象
	VoPackage string `yaml:"vo_package"` // View Object包名，对应视图对象
	DaoPackage string `yaml:"dao_package"` // Data Access Object包名，对应数据访问层
	ToolPackage string `yaml:"tool_package"` // Tool包名，对应工具类
}

// NewConfigger 创建配置管理器实例
// 从指定路径的YAML文件中加载配置
//
// 参数:
// - configPath: 配置文件路径，支持~符号展开
//
// 返回:
// - *Configger: 配置管理器实例指针
// - error: 加载过程中的错误，nil表示成功
func NewConfigger(configPath string) (*Configger, error) {
	// 展开路径中的~符号为用户主目录
	path := tool.EscapeHomeDir(configPath)

	// 读取配置文件内容
	data, err := os.ReadFile(path)
	if err != nil {
		return nil, fmt.Errorf("读取配置文件失败: %w", err)
	}

	// 解析YAML配置
	var config Configger
	if err = yaml.Unmarshal(data, &config); err != nil {
		return nil, fmt.Errorf("解析YAML配置失败: %w", err)
	}

	// 后处理配置项，展开路径中的特殊符号
	if err := processConfigPaths(&config); err != nil {
		return nil, fmt.Errorf("处理配置路径失败: %w", err)
	}

	return &config, nil
}

// processConfigPaths 处理配置中的路径项
// 展开路径中的~符号，确保路径的有效性
func processConfigPaths(config *Configger) error {
	// 展开输出路径中的~符号
	config.GenerateOption.OutputPath = tool.EscapeHomeDir(config.GenerateOption.OutputPath)

	// 展开SQL文件路径中的~符号（如果存在）
	if config.GenerateConfig.SqlFilePath != "" {
		config.GenerateConfig.SqlFilePath = tool.EscapeHomeDir(config.GenerateConfig.SqlFilePath)
	}

	return nil
