import (
	"fmt"
	"log"
	"os"
	"path/filepath"

	"model_infrax"
	"model_infrax/config"

	flag "github.com/spf13/pflag"
)

// jen 命令的主入口
// 这个命令会读取 model_infrax.go 文件中的 Infrax() 函数配置
// 然后执行代码生成
//
// 使用方式:
// jen # 使用 model_infrax.go 中的 Infrax() 配置
// jen -c config.yml # 使用 YAML 配置文件
// jen -m # 使用 model_infrax.go 中的 InfraxMultiple() 配置（多数据库）
// jen -h # 显示帮助信息

func main() {
	// 定义命令行参数
	configFile := flag.StringP("config", "c", "", "使用 YAML 配置文件路径")
	multiple := flag.BoolP("multiple", "m", false, "使用 InfraxMultiple() 配置生成多个数据库")
	help := flag.BoolP("help", "h", false, "显示帮助信息")

	flag.Parse()

	// 显示帮助信息
	if *help {
		showHelp()
		return
	}

	// 模式 1: 使用 YAML 配置文件
	if *configFile != "" {
		log.Printf(" 使用配置文件: %s", *configFile)
		if err := model_infrax.GenerateFromConfig(*configFile); err != nil {
			log.Fatalf("❌ 生成失败: %v", err)
		}
		log.Println("✅ 代码生成成功！")
		return
	}

	// 模式 2: 使用 InfraxMultiple() 配置（多数据库）
	if *multiple {
		log.Println(" 使用 InfraxMultiple() 配置生成多个数据库...")
		builders := model_infrax.InfraxMultiple()
		if len(builders) == 0 {
			log.Fatal("❌ InfraxMultiple() 返回空配置列表")
		}

		for i, builder := range builders {
			log.Printf(" [%d/%d] 开始生成...", i+1, len(builders))
			if err := model_infrax.Generate(builder); err != nil {
				log.Printf("❌ [%d/%d] 生成失败: %v", i+1, len(builders), err)
				continue
			}
			log.Printf("✅ [%d/%d] 生成成功", i+1, len(builders))
		}
		log.Println(" 所有数据库代码生成完成！")
		return
	}

	// 模式 3: 使用 Infrax() 配置（默认）
	log.Println(" 使用 Infrax() 配置生成代码...")

	// 检查 model_infrax.go 文件是否存在
	if !fileExists("model_infrax.go") {
		log.Println("⚠️ 未找到 model_infrax.go 文件")
		log.Println(" 提示: 请在项目根目录创建 model_infrax.go 文件并实现 Infrax() 函数")
		log.Println(" 或者使用 -c 参数指定 YAML 配置文件")
		showQuickStart()
		os.Exit(1)
	}

	// 调用 Infrax() 函数获取配置
	builder := model_infrax.Infrax()
	if builder == nil {
		log.Fatal("❌ Infrax() 返回 nil 配置")
	}

	// 执行代码生成
	if err := model_infrax.Generate(builder); err != nil {
		log.Fatalf("❌ 生成失败: %v", err)
	}

	log.Println("✅ 代码生成成功！")
}

// fileExists 检查文件是否存在
func fileExists(filename string) bool {
	_, err := os.Stat(filename)
	return err == nil
}

// showHelp 显示帮助信息
func showHelp() {
	fmt.Println(`
jen - Model Infrax 代码生成工具

用法:
 jen 使用 model_infrax.go 中的 Infrax() 配置
 jen -c <config.yml> 使用 YAML 配置文件
 jen -m 使用 model_infrax.go 中的 InfraxMultiple() 配置（多数据库）
 jen -h 显示此帮助信息

选项:
 -c, --config <file> 指定 YAML 配置文件路径
 -m, --multiple 使用多数据库配置模式
 -h, --help 显示帮助信息

示例:
