func showQuickStart() {
	execPath, _ := os.Executable()
	execDir := filepath.Dir(execPath)

	fmt.Printf(`
快速开始:

1. 创建 model_infrax.go 文件:

 package main

 import "model_infrax/config"

 func Infrax() *config.ConfiggerBuilder {
 return config.NewBuilder().
 DatabaseMode("localhost", 3306, "mydb", "root", "password").
 Tables("users", "orders").
 OutputPath("./generated").
 IgnoreTableNamePrefix(true)
 }

2. 运行生成命令:

 jen

3. 查看生成的代码:

 ls -la ./generated

示例配置文件位置:
 %s/assert/application.yml

更多示例:
 jen -h
`, execDir)
}
