	// 	// 自定义包名
	// 	Packages("entity", "dto", "vo", "dao", "util").
	//
	// 	// 使用框架模板
	// 	UseFramework("itea-go")
}

// InfraxMultiple 多数据库配置示例
// 如果需要同时生成多个数据库的代码，可以实现这个函数
// 然后使用 jen -m 命令运行
func InfraxMultiple() []*config.ConfiggerBuilder {
	return []*config.ConfiggerBuilder{
		// 用户数据库
		config.NewBuilder().
			DatabaseMode("localhost", 3306, "user_db", "root", "password").
			Tables("users", "profiles", "sessions").
			OutputPath("./generated/user_db").
			IgnoreTableNamePrefix(true),

		// 订单数据库
		config.NewBuilder().
			DatabaseMode("localhost", 3306, "order_db", "root", "password").
			Tables("orders", "order_items", "payments").
			OutputPath("./generated/order_db").
			IgnoreTableNamePrefix(true),

		// 产品数据库
		config.NewBuilder().
			DatabaseMode("localhost", 3306, "product_db", "root", "password").
			AllTables().
			OutputPath("./generated/product_db").
			IgnoreTableNamePrefix(true),
	}
}

// ==================== 辅助函数 ====================

// getEnv 获取环境变量，如果不存在则返回默认值
func getEnv(key, defaultValue string) string {
	value := os.Getenv(key)
	if value == "" {
		return defaultValue
	}
	return value
}

// ==================== 配置说明 ====================

/*
配置选项说明:

1. 数据源配置:
 - DatabaseMode(host, port, dbName, username, password) - 从数据库生成
 - StatementMode(sqlFilePath) - 从 SQL 文件生成

2. 表选择:
 - AllTables() - 生成所有表
 - Tables(names...) - 指定表名列表

3. 输出配置:
 - OutputPath(path) - 输出路径
 - IgnoreTableNamePrefix(bool) - 忽略表名前缀
 - CrudOnlyIdx(bool) - 只为索引字段生成 CRUD
 - ModelAllInOneFile(bool, fileName) - 所有 Model 合并到一个文件

4. 包名配置:
 - Packages(po, dto, vo, dao, tool) - 批量设置包名
 - PoPackage(name) - 设置 PO 包名
 - DtoPackage(name) - 设置 DTO 包名
 - VoPackage(name) - 设置 VO 包名
 - DaoPackage(name) - 设置 DAO 包名
 - ToolPackage(name) - 设置 Tool 包名

5. 框架支持:
 - UseFramework(name) - 使用框架模板（如 "itea-go"）

使用环境变量:
 export DB_HOST=localhost
 export DB_PORT=3306
 export DB_NAME=mydb
 export DB_USER=root
 export DB_PASS=password
 jen

更多文档:
 - Jen 命令使用指南: ./docs/JEN_USAGE.md
 - API 文档: ./README.md
 - 配置选项: ./config/builder.go
*/
