import (
	"fmt"
	"log"
	"model_infrax/config"
	"model_infrax/generator"
	"model_infrax/model"
	"model_infrax/parser"
	"os"
	"os/exec"
	"path/filepath"

	flag "github.com/spf13/pflag"
)

// ... existing code ...

type App struct {
	Config *config.Configger
	Generator *generator.Generator
}

// ... existing code ...

// NewApp 创建应用实例
// 注意：DatabaseParser 和 StatementParser 不再作为依赖注入，而是在 Run 方法中根据模式动态创建
// 这样可以避免 statement 模式下不必要的数据库连接
func NewApp(cfg *config.Configger, g *generator.Generator) *App {
	return &App{
		Config: cfg,
		Generator: g,
	}
}

// ... existing code ...

// NewAppFromBuilder 从配置构建器创建应用实例
// 这是使用 Go 代码配置的便捷方法
// 示例:
//
//	app := NewAppFromBuilder(
//	 config.NewBuilder().
//	 DatabaseMode("localhost", 3306, "mydb", "root", "password").
//	 AllTables().
//	 OutputPath("./output"),
//	)
func NewAppFromBuilder(builder *config.ConfiggerBuilder) (*App, error) {
	cfg, err := builder.Build()
	if err != nil {
		return nil, fmt.Errorf("构建配置失败: %w", err)
	}

	gen := generator.NewGenerator(cfg)
	return NewApp(cfg, gen), nil
}

// ... existing code ...

// Run 运行应用程序，执行完整的代码生成流程
// 流程包括：
// 1. 解析数据库表结构（从数据库或SQL文件）
// 2. 根据配置过滤需要处理的表
// 3. 生成Model实体类代码
// 4. 生成DTO数据传输对象代码
// 5. 生成DAO数据访问对象代码
// 6. 生成Tool工具类代码
func (a *App) Run() error {
	var schemas []model.Schema
	var err error

	// 根据配置的生成模式选择不同的解析器
	// 采用延迟初始化策略：只在需要时才创建对应的解析器
	// 这样可以避免 statement 模式下不必要的数据库连接尝试
	switch a.Config.GenerateConfig.GenerateMode {
	case "database":
		// 从数据库解析表结构
		log.Println(" 开始从数据库解析表结构...")

		// 动态创建 DatabaseParser，只在 database 模式下才会尝试连接数据库
		var databaseParser *parser.DatabaseParser
		databaseParser, err = parser.NewDatabaseParser(a.Config)
		if err != nil {
			return fmt.Errorf("初始化数据库解析器失败: %w", err)
		}

		schemas, err = databaseParser.Parse()
		if err != nil {
			return err
		}
		log.Printf("✅ 数据库解析完成，共获取到 %d 个表", len(schemas))

		// 根据配置文件中的表名过滤规则，筛选需要生成代码的表
		schemas = databaseParser.FilterTables(schemas)

	case "statement":
		// 从SQL文件解析表结构
		log.Println(" 开始从SQL文件解析表结构...")

		// 动态创建 StatementParser，不需要数据库连接，只解析 SQL 文件
		var statementParser *parser.StatementParser
		statementParser, err = parser.NewStatementParser(a.Config)
		if err != nil {
			return fmt.Errorf("初始化SQL文件解析器失败: %w", err)
		}

		schemas, err = statementParser.Parse()
		if err != nil {
			return err
		}
		log.Printf("✅ SQL文件解析完成，共获取到 %d 个表", len(schemas))

		// 根据配置文件中的表名过滤规则，筛选需要生成代码的表
		schemas = statementParser.FilterTables(schemas)

	default:
		return fmt.Errorf("不支持的生成模式: %s，请使用 'database' 或 'statement'", a.Config.GenerateConfig.GenerateMode)
	}

	log.Printf(" 过滤后需要处理的表数量: %d", len(schemas))

	log.Println("️ 开始生成 Model 代码...")

	// 生成Model实体类代码
	// 根据配置决定是生成到一个文件还是分别生成
	if a.Config.GenerateOption.ModelAllInOneFile {
		err = a.Generator.GenerateModel(schemas, a.Config.GenerateOption.ModelAllInOneFileName)
	} else {
		err = a.Generator.GenerateModelOneByOne(schemas)
	}
	if err != nil {
		return err
	}

	log.Println("✅ Model 代码生成完成")

	log.Println(" 开始生成 DTO 代码...")

	// 生成DTO数据传输对象代码，用于API接口的数据交换
	err = a.Generator.GenerateDTOOneByOne(schemas)
	if err != nil {
		return err
	}

	log.Println("✅ DTO 代码生成完成")

	log.Println("️ 开始生成 DAO 代码...")

	// 生成DAO数据访问对象代码，提供数据库操作方法
	err = a.Generator.GenerateDAOOneByOne(schemas)
	if err != nil {
		return err
	}

	log.Println("✅ DAO 代码生成完成")

	log.Println("️ 开始生成 Tool 工具代码...")

	// 生成Tool工具类代码，提供通用的辅助功能
	err = a.Generator.GenerateAllTools()
	if err != nil {
		return err
	}

	log.Println(" 所有代码生成完成！")

	return nil
}

// ... existing code ...

var defaultConfigPaths = []string{
	"./application.yml",
	"./assert/application.yml",
	"/Applications/jen/application.yml",
	"/Applications/jen/assert/application.yml",
}

// findJenFile 在当前目录及子目录中查找 jen.go 文件
// 类似 wire 查找 wire.go 的方式
func findJenFile() (string, error) {
	// 优先查找当前目录
	if _, err := os.Stat("jen.go"); err == nil {
		return "jen.go", nil
	}

	// 查找当前目录下的所有 .go 文件，检查是否包含 //go:build jen 标签
	entries, err := os.ReadDir(".")
	if err != nil {
		return "", fmt.Errorf("读取当前目录失败: %w", err)
	}

	for _, entry := range entries {
		if entry.IsDir() || !filepath.Match("*.go", entry.Name()) {
			continue
		}

		// 读取文件前几行，检查是否有 jen build tag
		content, err := os.ReadFile(entry.Name())
		if err != nil {
			continue
		}

		// 简单检查前 200 字节是否包含 jen build tag
		header := string(content)
		if len(header) > 200 {
			header = header[:200]
		}

		if containsJenBuildTag(header) {
			return entry.Name(), nil
		}
	}

	return "", fmt.Errorf("未找到 jen.go 文件或包含 //go:build jen 标签的文件")
}

// containsJenBuildTag 检查文件头是否包含 jen build tag
func containsJenBuildTag(header string) bool {
	// 检查常见的 build tag 格式
	tags := []string{
		"//go:build jen",
		"// +build jen",
	}

	for _, tag := range tags {
		if len(header) >= len(tag) {
			// 检查文件开头是否包含这些标签
			for i := 0; i < len(header)-len(tag); i++ {
				if header[i:i+len(tag)] == tag {
					return true
				}
			}
		}
	}

	return false
}

// runJenFile 执行 jen.go 文件
// 类似 wire 的执行方式，编译并运行 jen.go
func runJenFile(jenFile string) error {
	log.Printf(" 找到配置文件: %s", jenFile)
	log.Println(" 开始执行代码生成...")

	// 创建临时目录用于编译
	tmpDir, err := os.MkdirTemp("", "jen-*")
	if err != nil {
		return fmt.Errorf("创建临时目录失败: %w", err)
	}
	defer os.RemoveAll(tmpDir)

	// 编译 jen.go 文件
	outputBinary := filepath.Join(tmpDir, "jen_gen")
	cmd := exec.Command("go", "build", "-tags", "jen", "-o", outputBinary, jenFile)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr

	log.Println(" 编译配置文件...")
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("编译 %s 失败: %w", jenFile, err)
	}

	// 运行编译后的二进制文件
	log.Println("⚙️ 执行代码生成...")
	runCmd := exec.Command(outputBinary)
	runCmd.Stdout = os.Stdout
	runCmd.Stderr = os.Stderr

	if err := runCmd.Run(); err != nil {
		return fmt.Errorf("执行生成失败: %w", err)
	}

	return nil
}

func main() {
	// 定义命令行参数
	configPath := flag.StringP("config", "c", "", "配置文件路径 (YAML)")
	useJenFile := flag.BoolP("jen", "j", false, "使用 jen.go 文件模式（默认自动检测）")

	flag.Parse()

	// 模式 1: 如果指定了 -j 或没有指定 -c，尝试查找并执行 jen.go
	if *useJenFile || *configPath == "" {
		jenFile, err := findJenFile()
		if err == nil {
			// 找到 jen.go 文件，执行它
			if err := runJenFile(jenFile); err != nil {
				log.Fatalf("❌ 执行失败: %v", err)
			}
			return
		}

		// 如果明确指定了 -j 但找不到文件，报错
		if *useJenFile {
			log.Fatalf("❌ %v", err)
		}

		// 否则继续尝试 YAML 配置模式
		log.Println(" 未找到 jen.go 文件，尝试使用 YAML 配置模式...")
	}

	// 模式 2: 使用 YAML 配置文件
	if *configPath == "" {
		*configPath = "./application.yml"
	}

	app, err := InitializeApp(*configPath)
	if err != nil {
		// 尝试默认路径
		for _, path := range defaultConfigPaths {
			app, err = InitializeApp(path)
			if err == nil {
				break
			}
		}
		if err != nil {
			log.Fatalf("❌ 初始化失败: %v\n\n 提示：\n 1. 创建 jen.go 文件使用编程式配置\n 2. 或使用 -c 指定 YAML 配置文件路径", err)
		}
	}

	if err = app.Run(); err != nil {
		log.Fatalf("❌ 运行应用失败: %v", err)
	}
}
