// +build jen

package main

import (
	"log"
	"os"
	"strconv"

	"github.com/LingoJack/model_infrax"
)

// jen.go 示例文件
// 这个文件展示了如何使用 jen.go 模式配置代码生成
// 
// 使用方式：
// 1. 复制这个文件到你的项目根目录
// 2. 根据需要修改配置
// 3. 运行 `jen` 命令
//
// 注意：必须保留文件开头的 build tag 注释

func main() {
	// 方式 1: 从环境变量读取配置（推荐用于生产环境）
	if useEnvConfig() {
		generateFromEnv()
		return
	}

	// 方式 2: 硬编码配置（适合开发环境）
	generateFromHardcode()
}

// useEnvConfig 检查是否使用环境变量配置
func useEnvConfig() bool {
	return os.Getenv("DB_HOST") != ""
}

// generateFromEnv 从环境变量读取配置并生成代码
func generateFromEnv() {
	host := os.Getenv("DB_HOST")
	port, _ := strconv.Atoi(os.Getenv("DB_PORT"))
	database := os.Getenv("DB_NAME")
	username := os.Getenv("DB_USER")
	password := os.Getenv("DB_PASS")

	log.Println(" 使用环境变量配置")
	log.Printf(" 数据库: %s:%d/%s", host, port, database)

	err := model_infrax.Generate(
		model_infrax.NewBuilder().
			DatabaseMode(host, port, database, username, password).
			AllTables().
			OutputPath("./generated").
			IgnoreTableNamePrefix(true).
			CrudOnlyIdx(false),
	)

	if err != nil {
		log.Fatalf("❌ 生成失败: %v", err)
	}

	log.Println("✅ 代码生成成功！")
}

// generateFromHardcode 使用硬编码配置生成代码
func generateFromHardcode() {
	log.Println(" 使用硬编码配置")

	// 配置示例 1: 从数据库生成指定表
	err := model_infrax.Generate(
		model_infrax.NewBuilder().
			// 数据库连接配置
			DatabaseMode("localhost", 3306, "mydb", "root", "password").

			// 指定要生成的表（如果不指定则生成所有表）
			Tables("users", "orders", "products").

			// 输出路径
			OutputPath("./generated").

			// 生成选项
			IgnoreTableNamePrefix(true). // 忽略表名前缀（如 t_user -> User）
			CrudOnlyIdx(false). // 为所有字段生成 CRUD 方法
			ModelAllInOneFile(false, ""). // 每个表生成单独的文件

			// 自定义包名（可选）
			Packages("model", "dto", "vo", "dao", "util"),
	)

	if err != nil {
		log.Fatalf("❌ 生成失败: %v", err)
	}

	log.Println("✅ 代码生成成功！")

	// 配置示例 2: 从 SQL 文件生成（取消注释使用）
	/*
	err = model_infrax.Generate(
		model_infrax.NewBuilder().
			StatementMode("./schema.sql").
			AllTables().
			OutputPath("./generated_from_sql"),
	)

	if err != nil {
		log.Fatalf("❌ 从 SQL 文件生成失败: %v", err)
	}
	*/

	// 配置示例 3: 批量生成多个数据库（取消注释使用）
	/*
	databases := []struct {
		name string
		tables []string
	}{
		{"user_db", []string{"users", "profiles", "sessions"}},
		{"order_db", []string{"orders", "order_items", "payments"}},
		{"product_db", []string{"products", "categories", "inventory"}},
	}

	for _, db := range databases {
		log.Printf(" 生成数据库 %s...", db.name)

		err := model_infrax.Generate(
			model_infrax.NewBuilder().
				DatabaseMode("localhost", 3306, db.name, "root", "password").
				Tables(db.tables...).
				OutputPath("./generated/" + db.name).
				IgnoreTableNamePrefix(true),
		)

		if err != nil {
			log.Printf("❌ 生成 %s 失败: %v", db.name, err)
			continue
		}

		log.Printf("✅ %s 生成成功", db.name)
	}
	*/
}
","instruction":"创建一个示例 jen.go 文件，展示各种配置方式","apply_mode":"manual"}},"timestamp":1763610491,"type":"TOOL_CALL_ARGS"}

