// TestConfigBuilder_DatabaseMode 测试数据库模式配置
func TestConfigBuilder_DatabaseMode(t *testing.T) {
	cfg := NewBuilder().
		DatabaseMode("localhost", 3306, "testdb", "root", "password").
		Tables("users").
		OutputPath("./output").
		MustBuild()

	if cfg.GenerateConfig.GenerateMode != "database" {
		t.Errorf("期望 GenerateMode 为 'database'，实际为 '%s'", cfg.GenerateConfig.GenerateMode)
	}

	if cfg.GenerateConfig.Host != "localhost" {
		t.Errorf("期望 Host 为 'localhost'，实际为 '%s'", cfg.GenerateConfig.Host)
	}

	if cfg.GenerateConfig.Port != 3306 {
		t.Errorf("期望 Port 为 3306，实际为 %d", cfg.GenerateConfig.Port)
	}

	if cfg.GenerateConfig.DatabaseName != "testdb" {
		t.Errorf("期望 DatabaseName 为 'testdb'，实际为 '%s'", cfg.GenerateConfig.DatabaseName)
	}
}

// TestConfigBuilder_StatementMode 测试SQL文件模式配置
func TestConfigBuilder_StatementMode(t *testing.T) {
	cfg := NewBuilder().
		StatementMode("./schema.sql").
		AllTables().
		OutputPath("./output").
		MustBuild()

	if cfg.GenerateConfig.GenerateMode != "statement" {
		t.Errorf("期望 GenerateMode 为 'statement'，实际为 '%s'", cfg.GenerateConfig.GenerateMode)
	}

	if cfg.GenerateConfig.SqlFilePath != "./schema.sql" {
		t.Errorf("期望 SqlFilePath 为 './schema.sql'，实际为 '%s'", cfg.GenerateConfig.SqlFilePath)
	}

	if !cfg.GenerateConfig.AllTables {
		t.Error("期望 AllTables 为 true")
	}
}

// TestConfigBuilder_Tables 测试表名配置
func TestConfigBuilder_Tables(t *testing.T) {
	cfg := NewBuilder().
		DatabaseMode("localhost", 3306, "testdb", "root", "password").
		Tables("users", "orders", "products").
		OutputPath("./output").
		MustBuild()

	if len(cfg.GenerateConfig.TableNames) != 3 {
		t.Errorf("期望 TableNames 长度为 3，实际为 %d", len(cfg.GenerateConfig.TableNames))
	}

	expectedTables := []string{"users", "orders", "products"}
	for i, table := range expectedTables {
		if cfg.GenerateConfig.TableNames[i] != table {
			t.Errorf("期望 TableNames[%d] 为 '%s'，实际为 '%s'", i, table, cfg.GenerateConfig.TableNames[i])
		}
	}
}

// TestConfigBuilder_Packages 测试包名配置
func TestConfigBuilder_Packages(t *testing.T) {
	cfg := NewBuilder().
		StatementMode("./schema.sql").
		AllTables().
		OutputPath("./output").
		Packages("model", "request", "response", "repository", "helper").
		MustBuild()

	if cfg.GenerateOption.Package.PoPackage != "model" {
		t.Errorf("期望 PoPackage 为 'model'，实际为 '%s'", cfg.GenerateOption.Package.PoPackage)
	}

	if cfg.GenerateOption.Package.DtoPackage != "request" {
		t.Errorf("期望 DtoPackage 为 'request'，实际为 '%s'", cfg.GenerateOption.Package.DtoPackage)
	}

	if cfg.GenerateOption.Package.VoPackage != "response" {
		t.Errorf("期望 VoPackage 为 'response'，实际为 '%s'", cfg.GenerateOption.Package.VoPackage)
	}

	if cfg.GenerateOption.Package.DaoPackage != "repository" {
		t.Errorf("期望 DaoPackage 为 'repository'，实际为 '%s'", cfg.GenerateOption.Package.DaoPackage)
	}

	if cfg.GenerateOption.Package.ToolPackage != "helper" {
		t.Errorf("期望 ToolPackage 为 'helper'，实际为 '%s'", cfg.GenerateOption.Package.ToolPackage)
	}
}

// TestConfigBuilder_Options 测试各种选项配置
func TestConfigBuilder_Options(t *testing.T) {
	cfg := NewBuilder().
		StatementMode("./schema.sql").
		AllTables().
		OutputPath("./output").
		IgnoreTableNamePrefix(true).
		CrudOnlyIdx(true).
		ModelAllInOneFile(true, "models.go").
		UseFramework("itea-go").
		MustBuild()

	if !cfg.GenerateOption.IgnoreTableNamePrefix {
		t.Error("期望 IgnoreTableNamePrefix 为 true")
	}

	if !cfg.GenerateOption.CrudOnlyIdx {
		t.Error("期望 CrudOnlyIdx 为 true")
	}

	if !cfg.GenerateOption.ModelAllInOneFile {
		t.Error("期望 ModelAllInOneFile 为 true")
	}

	if cfg.GenerateOption.ModelAllInOneFileName != "models.go" {
		t.Errorf("期望 ModelAllInOneFileName 为 'models.go'，实际为 '%s'", cfg.GenerateOption.ModelAllInOneFileName)
	}

	if cfg.GenerateOption.UseFramework != "itea-go" {
		t.Errorf("期望 UseFramework 为 'itea-go'，实际为 '%s'", cfg.GenerateOption.UseFramework)
	}
}

// TestConfigBuilder_Validation 测试配置验证
func TestConfigBuilder_Validation(t *testing.T) {
	tests := []struct {
		name string
		builder *ConfigBuilder
		expectError bool
		errorMsg string
	}{
		{
			name: "缺少数据库主机",
			builder: NewBuilder().
				DatabaseMode("", 3306, "testdb", "root", "password").
				Tables("users"),
			expectError: true,
			errorMsg: "数据库模式下必须指定 Host",
		},
		{
			name: "缺少数据库端口",
			builder: NewBuilder().
				DatabaseMode("localhost", 0, "testdb", "root", "password").
				Tables("users"),
			expectError: true,
			errorMsg: "数据库模式下必须指定 Port",
		},
		{
			name: "缺少数据库名称",
			builder: NewBuilder().
				DatabaseMode("localhost", 3306, "", "root", "password").
				Tables("users"),
			expectError: true,
			errorMsg: "数据库模式下必须指定 DatabaseName",
		},
		{
			name: "缺少SQL文件路径",
			builder: NewBuilder().
				StatementMode("").
				Tables("users"),
			expectError: true,
			errorMsg: "SQL文件模式下必须指定 SqlFilePath",
		},
		{
			name: "缺少表名配置",
			builder: NewBuilder().
				DatabaseMode("localhost", 3306, "testdb", "root", "password"),
			expectError: true,
			errorMsg: "必须指定要生成的表名或使用 AllTables()",
		},
		{
			name: "正确的配置",
			builder: NewBuilder().
				DatabaseMode("localhost", 3306, "testdb", "root", "password").
				Tables("users"),
			expectError: false,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			_, err := tt.builder.Build()
			if tt.expectError {
				if err == nil {
					t.Errorf("期望出现错误，但没有错误")
				} else if err.Error() != tt.errorMsg {
					t.Errorf("期望错误信息为 '%s'，实际为 '%s'", tt.errorMsg, err.Error())
				}
			} else {
				if err != nil {
					t.Errorf("不期望出现错误，但出现了错误: %v", err)
				}
			}
		})
	}
}

// TestConfigBuilder_ChainedCalls 测试链式调用
func TestConfigBuilder_ChainedCalls(t *testing.T) {
	// 测试链式调用是否正常工作
	cfg := NewBuilder().
		DatabaseMode("localhost", 3306, "testdb", "root", "password").
		Tables("users", "orders").
		OutputPath("./output").
		IgnoreTableNamePrefix(true).
		CrudOnlyIdx(true).
		ModelAllInOneFile(true, "models.go").
		UseFramework("itea-go").
		Packages("model", "dto", "vo", "dao", "tool").
		MustBuild()

	// 验证所有配置都正确设置
	if cfg.GenerateConfig.Host != "localhost" {
		t.Error("链式调用后 Host 配置不正确")
	}

	if len(cfg.GenerateConfig.TableNames) != 2 {
		t.Error("链式调用后 TableNames 配置不正确")
	}

	if !cfg.GenerateOption.IgnoreTableNamePrefix {
		t.Error("链式调用后 IgnoreTableNamePrefix 配置不正确")
	}
}

// TestConfigBuilder_DefaultValues 测试默认值
func TestConfigBuilder_DefaultValues(t *testing.T) {
	cfg := NewBuilder().
		DatabaseMode("localhost", 3306, "testdb", "root", "password").
		Tables("users").
		MustBuild()

	// 验证默认值
	if cfg.GenerateOption.OutputPath != "./output" {
		t.Errorf("期望默认 OutputPath 为 './output'，实际为 '%s'", cfg.GenerateOption.OutputPath)
	}

	if cfg.GenerateOption.Package.PoPackage != "po" {
		t.Errorf("期望默认 PoPackage 为 'po'，实际为 '%s'", cfg.GenerateOption.Package.PoPackage)
	}

	if cfg.GenerateOption.Package.DtoPackage != "dto" {
		t.Errorf("期望默认 DtoPackage 为 'dto'，实际为 '%s'", cfg.GenerateOption.Package.DtoPackage)
	}

	if cfg.GenerateOption.IgnoreTableNamePrefix {
		t.Error("期望默认 IgnoreTableNamePrefix 为 false")
	}

	if cfg.GenerateOption.CrudOnlyIdx {
		t.Error("期望默认 CrudOnlyIdx 为 false")
	}

	if cfg.GenerateOption.ModelAllInOneFile {
		t.Error("期望默认 ModelAllInOneFile 为 false")
	}
}
