{"rawEvent":{"message_id":"019a9f3b4e597182a5d16361e7ec03d9","conversation_id":"019a9f2ccaae7a729b2639fc1ac4e4bb","tool_call_id":"tooluse_VXd3mCmORuaP2ClaJdfPYQ","document":{"apply_mode":"manual","apply_content":" modelinfra

import (
	"fmt"
	"github.com/jacklingo/model_infrax/config"
	"github.com/jacklingo/model_infrax/generator"
	"github.com/jacklingo/model_infrax/model"
	"github.com/jacklingo/model_infrax/parser"
	"log"
)

// Generator 代码生成器，提供简洁的公开 API
// 这是供外部项目使用的主要入口
type Generator struct {
	config *config.Configger
	generator *generator.Generator
}

// New 创建一个新的代码生成器
// 使用 Builder 模式配置生成器
//
// 示例:
// gen := modelinfra.New(
// modelinfra.NewBuilder().
// DatabaseMode("localhost", 3306, "mydb", "root", "password").
// Tables("users", "orders").
// OutputPath("./output"),
// )
// if err := gen.Generate(); err != nil {
// log.Fatal(err)
// }
func New(builder *config.ConfigBuilder) (*Generator, error) {
	cfg, err := builder.Build()
	if err != nil {
		return nil, fmt.Errorf("构建配置失败: %w", err)
	}

	gen := generator.NewGenerator(cfg)
	return &Generator{
		config: cfg,
		generator: gen,
	}, nil
}

// NewWithConfig 使用已有的配置创建生成器
// 适用于从 YAML 文件加载配置的场景
