{"rawEvent":{"message_id":"019a9f3c17317c29b5a9933c567336cf","conversation_id":"019a9f2ccaae7a729b2639fc1ac4e4bb","tool_call_id":"tooluse_C3LUdubuQMO4Cd5Q1EH0uA","document":{"file_path":"/Users/jacklingo/dev/model_infrax/cmd/model_infrax/main.go","sub_content":"main.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/cmd/model_infrax/main.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/cmd/model_infrax/main.go","apply_content":"package main

import (
	"log"
	"model_infrax"

	flag "github.com/spf13/pflag"
)

// 默认配置文件路径列表
// 按优先级顺序尝试加载配置文件
var defaultConfigPaths = []string{
	"./application.yml",
	"./assert/application.yml",
	"/Applications/jen/application.yml",
	"/Applications/jen/assert/application.yml",
}

func main() {
	// 解析命令行参数
	configPath := flag.StringP("config", "c", "./application.yml", "配置文件路径")
	flag.Parse()

	// 尝试从指定的配置文件生成代码
	err := model_infrax.GenerateFromConfig(*configPath)
	if err != nil {
		// 如果指定的配置文件失败，尝试默认路径
		log.Printf("使用配置文件 %s 失败: %v，尝试默认路径...", *configPath, err)

		for _, path := range defaultConfigPaths {
			err = model_infrax.GenerateFromConfig(path)
			if err == nil {
				log.Printf("✅ 使用配置文件: %s", path)
				return
			}
		}

		// 所有路径都失败
		log.Fatalf("❌ 无法找到有效的配置文件，请使用 -c 参数指定配置文件路径")
	}

	log.Println(" 代码生成完成！")
}
