{"rawEvent":{"message_id":"019a9f3c17317c29b5a9933c567336cf","conversation_id":"019a9f2ccaae7a729b2639fc1ac4e4bb","tool_call_id":"tooluse_yl3UetPrR6Swn9weK2bx-g","document":{"file_path":"/Users/jacklingo/dev/model_infrax/examples/programmatic_usage.go","sub_content":"programmatic_usage.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/examples/programmatic_usage.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/examples/programmatic_usage.go","apply_content":"package main

import (
	"log"
	"model_infrax"
)

// 示例 1: 从数据库生成代码
func Example_DatabaseMode() {
	err := model_infrax.Generate(
		model_infrax.NewBuilder().
			DatabaseMode("localhost", 3306, "mydb", "root", "password").
			Tables("users", "orders", "products").
			OutputPath("./generated").
			IgnoreTableNamePrefix(true),
	)
	if err != nil {
		log.Fatal(err)
	}
	log.Println("✅ 代码生成成功")
}

// 示例 2: 从 SQL 文件生成代码
func Example_StatementMode() {
	err := model_infrax.Generate(
		model_infrax.NewBuilder().
			StatementMode("~/schema.sql").
			AllTables().
			OutputPath("./generated").
			UseFramework("itea-go"),
	)
	if err != nil {
		log.Fatal(err)
	}
	log.Println("✅ 代码生成成功")
}

// 示例 3: 使用配置文件
func Example_ConfigFile() {
	err := model_infrax.GenerateFromConfig("./application.yml")
	if err != nil {
		log.Fatal(err)
	}
	log.Println("✅ 代码生成成功")
}

// 示例 4: 完整配置示例
func Example_FullConfiguration() {
	err := model_infrax.Generate(
		model_infrax.NewBuilder().
			// 数据库配置
			DatabaseMode("localhost", 3306, "mydb", "root", "password").
			// 表配置
			Tables("t_user", "t_order", "t_product").
			// 输出配置
			OutputPath("./output").
			// 生成选项
			IgnoreTableNamePrefix(true).
			CrudOnlyIdx(true).
			ModelAllInOneFile(false, "").
			// 包名配置
			Packages("entity", "dto", "vo", "dao", "util").
			// 框架配置
			UseFramework("itea-go"),
	)
	if err != nil {
		log.Fatal(err)
	}
	log.Println("✅ 代码生成成功")
}

// 示例 5: 在 Web 服务中使用
func Example_WebService() {
	// 假设这是一个 HTTP 处理函数
	handleGenerate := func(dbHost string, dbPort int, dbName string, tables []string) error {
		builder := model_infrax.NewBuilder().
			DatabaseMode(dbHost, dbPort, dbName, "root", "password").
			OutputPath("./generated")

		// 动态添加表名
		if len(tables) > 0 {
			builder.Tables(tables...)
		} else {
			builder.AllTables()
		}

		return model_infrax.Generate(builder)
	}

	// 使用示例
	err := handleGenerate("localhost", 3306, "mydb", []string{"users", "orders"})
	if err != nil {
		log.Fatal(err)
	}
}

// 示例 6: 批量生成多个数据库
func Example_MultipleDatabases() {
	databases := []struct {
		name string
		tables []string
	}{
		{"db1", []string{"users", "orders"}},
		{"db2", []string{"products", "categories"}},
		{"db3", []string{"logs", "events"}},
	}

	for _, db := range databases {
		log.Printf(" 开始生成数据库 %s 的代码...", db.name)

		err := model_infrax.Generate(
			model_infrax.NewBuilder().
				DatabaseMode("localhost", 3306, db.name, "root", "password").
				Tables(db.tables...).
				OutputPath("./generated/" + db.name),
		)

		if err != nil {
			log.Printf("❌ 生成数据库 %s 失败: %v", db.name, err)
			continue
		}

		log.Printf("✅ 数据库 %s 代码生成成功", db.name)
	}
}

// 示例 7: 条件生成
func Example_ConditionalGeneration() {
	// 根据环境变量决定生成模式
	mode := "database" // 可以从环境变量读取

	var builder *model_infrax.ConfiggerBuilder

	if mode == "database" {
		builder = model_infrax.NewBuilder().
			DatabaseMode("localhost", 3306, "mydb", "root", "password").
			AllTables()
	} else {
		builder = model_infrax.NewBuilder().
			StatementMode("./schema.sql").
			AllTables()
	}

	err := model_infrax.Generate(
		builder.
			OutputPath("./generated").
			IgnoreTableNamePrefix(true),
	)

	if err != nil {
		log.Fatal(err)
	}
}

func main() {
	// 运行示例
	log.Println("=== 示例 1: 从数据库生成 ===")
	// Example_DatabaseMode()

	log.Println("\n=== 示例 2: 从 SQL 文件生成 ===")
	// Example_StatementMode()

	log.Println("\n=== 示例 3: 使用配置文件 ===")
	// Example_ConfigFile()

	log.Println("\n=== 示例 4: 完整配置 ===")
	// Example_FullConfiguration()

	log.Println("\n=== 示例 5: Web 服务中使用 ===")
	// Example_WebService()

	log.Println("\n=== 示例 6: 批量生成 ===")
	// Example_MultipleDatabases()

	log.Println("\n=== 示例 7: 条件生成 ===")
	// Example_ConditionalGeneration()

	log.Println("\n 取消注释上面的函数调用来运行示例")
}
