{"rawEvent":{"message_id":"019a950de7b27ca69503ba08cc5013eb","conversation_id":"019a950dc8477f649f9392afc52e19dc","tool_call_id":"tooluse_-gDYanLoTsOQf8UYK2OM0g","document":{"file_path":"/Users/jacklingo/dev/model_infrax/tool/copy.go","sub_content":"copy.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/tool/copy.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/tool/copy.go","apply_content":"package tool

import (
	"encoding/json"
)

// DeepCopy 深度拷贝对象
// 使用 JSON 序列化/反序列化实现深度拷贝，支持泛型类型
// 注意：该方法依赖 JSON 编解码，因此：
// 1. 源对象必须可以被 JSON 序列化（字段需要导出或有 json tag）
// 2. 不会拷贝未导出的字段
// 3. 不会拷贝函数、channel 等不可序列化的类型
// 4. 时间类型会被转换为 RFC3339 格式字符串后再解析
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 拷贝后的新对象，类型与源对象相同
// - error: 如果拷贝过程中发生错误（序列化或反序列化失败），返回错误信息
//
// 示例:
// type User struct {
// Name string
// Age int
// Tags []string
// }
// original := User{Name: "Alice", Age: 30, Tags: []string{"admin", "user"}}
// copied, err := DeepCopy(original)
// if err != nil {
// // 处理错误
// }
// // copied 是 User 类型，无需类型转换
// copied.Name = "Bob" // 修改拷贝不影响原对象
func DeepCopy[T any](src T) (T, error) {
	var dst T

	// 序列化源对象为 JSON
	data, err := json.Marshal(src)
	if err != nil {
		return dst, err
	}

	// 反序列化 JSON 到目标对象
	err = json.Unmarshal(data, &dst)
	if err != nil {
		return dst, err
	}

	return dst, nil
}

// MustDeepCopy 深度拷贝对象（panic 版本）
// 功能与 DeepCopy 相同，但在发生错误时会 panic 而不是返回 error
// 适用于确定不会出错的场景，或者希望在出错时直接终止程序的场景
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 拷贝后的新对象，类型与源对象相同
//
// Panic:
// - 如果序列化或反序列化失败，会 panic
//
// 示例:
// type User struct {
// Name string
// Age int
// }
// original := User{Name: "Alice", Age: 30}
// copied := MustDeepCopy(original) // 无需处理 error
// copied.Name = "Bob"
func MustDeepCopy[T any](src T) T {
	dst, err := DeepCopy(src)
	if err != nil {
		panic(err)
	}
	return dst
}

// DeepCopyTo 深度拷贝对象到不同类型
// 使用 JSON 序列化/反序列化实现类型转换和深度拷贝
// 适用于需要在不同但结构相似的类型之间转换的场景
//
// 注意：
// 1. 源类型和目标类型的字段名需要匹配（或通过 json tag 匹配）
// 2. 目标类型中不存在的字段会被忽略
// 3. 源类型中不存在但目标类型存在的字段会使用零值
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 目标类型的新对象
// - error: 如果拷贝过程中发生错误（序列化或反序列化失败），返回错误信息
//
// 示例:
// type UserDTO struct {
// Name string `json:"name"`
// Age int `json:"age"`
// }
// type UserEntity struct {
// Name string `json:"name"`
// Age int `json:"age"`
// ID int `json:"id"` // 这个字段在 UserDTO 中不存在，会使用零值
// }
// dto := UserDTO{Name: "Alice", Age: 30}
// entity, err := DeepCopyTo[UserEntity](dto)
// if err != nil {
// // 处理错误
// }
// // entity 是 UserEntity 类型，无需类型转换
func DeepCopyTo[T any](src any) (T, error) {
	var dst T

	// 序列化源对象为 JSON
	data, err := json.Marshal(src)
	if err != nil {
		return dst, err
	}

	// 反序列化 JSON 到目标对象
	err = json.Unmarshal(data, &dst)
	if err != nil {
		return dst, err
	}

	return dst, nil
}

// MustDeepCopyTo 深度拷贝对象到不同类型（panic 版本）
// 功能与 DeepCopyTo 相同，但在发生错误时会 panic 而不是返回 error
//
// 参数:
// - src: 源对象，需要被拷贝的对象
//
// 返回:
// - T: 目标类型的新对象
//
// Panic:
// - 如果序列化或反序列化失败，会 panic
//
// 示例:
// type UserDTO struct {
// Name string `json:"name"`
// }
// type UserEntity struct {
// Name string `json:"name"`
// ID int `json:"id"`
// }
// dto := UserDTO{Name: "Alice"}
// entity := MustDeepCopyTo[UserEntity](dto) // 无需处理 error
func MustDeepCopyTo[T any](src any) T {
	dst, err := DeepCopyTo[T](src)
	if err != nil {
		panic(err)
	}
	return dst
}
","instruction":"创建一个支持泛型的深度拷贝方法，使用泛型参数T确保返回类型明确，无需手动类型转换","apply_mode":"manual"}},"timestamp":1763437329,"type":"TOOL_CALL_ARGS"}

{"rawEvent":{"message_id":"019a95076f5d77749869a20e85768acc","conversation_id":"019a95038c927bd19ab4600ee6c8bc18","tool_call_id":"call_2b1b392419d74b81954d285f","document":{"file_path":"/Users/jacklingo/dev/model_infrax/tool/copy.go","sub_content":"copy.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/tool/copy.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/tool/copy.go","apply_content":"package tool

import (
	"encoding/json"
	"reflect"
)

// DeepCopy 使用JSON序列化/反序列化实现深度拷贝
// 适用于可以被JSON序列化的对象，性能较好但要求对象类型可被JSON处理
// 参数:
// - src: 源对象，必须是可以被JSON序列化的类型
//
// 返回:
// - interface{}: 深度拷贝后的对象
// - error: 拷贝过程中的错误，如JSON序列化失败
//
// 示例:
// - original := User{Name: "张三", Age: 25}
// - copied, err := DeepCopy(original)
// - // copied 是 original 的完全独立副本
func DeepCopy(src interface{}) (interface{}, error) {
	if src == nil {
		return nil, nil
	}

	// 通过JSON序列化和反序列化实现深度拷贝
	data, err := json.Marshal(src)
	if err != nil {
		return nil, err
	}

	var dest interface{}
	err = json.Unmarshal(data, &dest)
	if err != nil {
		return nil, err
	}

	return dest, nil
}

// DeepCopyToSameType 使用JSON序列化/反序列化实现同类型深度拷贝
// 返回与源对象相同类型的拷贝，适用于需要保持类型信息的场景
// 参数:
// - src: 源对象，必须是可以被JSON序列化的类型
//
// 返回:
// - interface{}: 与源对象相同类型的深度拷贝对象
// - error: 拷贝过程中的错误，如JSON序列化失败
//
// 示例:
// - original := User{Name: "张三", Age: 25}
// - copied, err := DeepCopyToSameType(original)
// - // copied 的类型仍然是 User
func DeepCopyToSameType(src interface{}) (interface{}, error) {
	if src == nil {
		return nil, nil
	}

	data, err := json.Marshal(src)
	if err != nil {
		return nil, err
	}

	// 创建与源对象相同类型的新实例
	srcValue := reflect.ValueOf(src)
	if srcValue.Kind() == reflect.Ptr {
		// 如果是指针，创建指向新对象的指针
		newPtr := reflect.New(srcValue.Type().Elem())
		err = json.Unmarshal(data, newPtr.Interface())
		return newPtr.Interface(), err
	} else {
		// 如果是值类型，创建新对象
		newValue := reflect.New(srcValue.Type())
		err = json.Unmarshal(data, newValue.Interface())
		return newValue.Elem().Interface(), err
	}
}

// DeepCopyToType 使用JSON序列化/反序列化实现指定类型的深度拷贝
// 通过传入类型示例来指定目标类型，实现跨类型的深度拷贝
// 参数:
// - src: 源对象，必须是可以被JSON序列化的类型
// - typeExample: 类型示例，如 User{} 或 &User{}，用于指定目标类型
//
// 返回:
// - interface{}: 指定类型的深度拷贝对象
// - error: 拷贝过程中的错误，如JSON序列化失败或类型不匹配
//
// 示例:
// - original := map[string]interface{}{"name": "张三", "age": 25}
// - copied, err := DeepCopyToType(original, User{})
// - // copied 的类型为 User，如果字段匹配则自动转换
func DeepCopyToType(src, typeExample interface{}) (interface{}, error) {
	if src == nil {
		return nil, nil
	}

	// 检查类型示例是否有效
	if typeExample == nil {
		return nil, fmt.Errorf("typeExample cannot be nil")
	}

	data, err := json.Marshal(src)
	if err != nil {
		return nil, err
	}

	typeValue := reflect.ValueOf(typeExample)
	if typeValue.Kind() == reflect.Ptr {
		// 如果传入的是指针类型示例，创建新指针
		newPtr := reflect.New(typeValue.Type().Elem())
		err = json.Unmarshal(data, newPtr.Interface())
		return newPtr.Interface(), err
	} else {
		// 如果传入的是值类型示例，创建新值
		newValue := reflect.New(typeValue.Type())
		err = json.Unmarshal(data, newValue.Interface())
		return newValue.Elem().Interface(), err
	}
}

// DeepCopyToTypeReflect 使用反射实现指定类型的深度拷贝
// 不依赖JSON序列化，支持更多数据类型和复杂结构的类型转换
// 参数:
// - src: 源对象，可以是任意类型
// - typeExample: 类型示例，如 User{} 或 &User{}，用于指定目标类型
//
// 返回:
// - interface{}: 指定类型的深度拷贝对象
// - error: 拷贝过程中的错误
//
// 示例:
// - original := &TempUser{Name: "李四", Age: 30}
// - copied, err := DeepCopyToTypeReflect(original, User{})
// - // copied 的类型为 User，即使源类型不同也能正确拷贝
func DeepCopyToTypeReflect(src, typeExample interface{}) (interface{}, error) {
	if src == nil {
		return nil, nil
	}

	if typeExample == nil {
		return nil, fmt.Errorf("typeExample cannot be nil")
	}

	// 先用反射方法进行深度拷贝
	copied, err := DeepCopyReflect(src)
	if err != nil {
		return nil, err
	}

	// 然后将拷贝结果转换为目标类型
	typeValue := reflect.ValueOf(typeExample)
	if typeValue.Kind() == reflect.Ptr {
		// 指针类型目标
		newPtr := reflect.New(typeValue.Type().Elem())
		err = copyValueToType(reflect.ValueOf(copied), newPtr.Elem())
		if err != nil {
			return nil, err
		}
		return newPtr.Interface(), nil
	} else {
		// 值类型目标
		newValue := reflect.New(typeValue.Type())
		err = copyValueToType(reflect.ValueOf(copied), newValue.Elem())
		if err != nil {
			return nil, err
		}
		return newValue.Elem().Interface(), nil
	}
}

// copyValueToType 辅助函数：将一个值拷贝到指定类型的值中
func copyValueToType(srcValue, dstValue reflect.Value) error {
	if !srcValue.IsValid() || !dstValue.IsValid() || !dstValue.CanSet() {
		return fmt.Errorf("invalid values for copying")
	}

	// 如果类型相同，直接拷贝
	if srcValue.Type() == dstValue.Type() {
		dstValue.Set(srcValue)
		return nil
	}

	// 处理不同类型之间的转换
	switch srcValue.Kind() {
	case reflect.Struct:
		if dstValue.Kind() == reflect.Struct {
			// 结构体到结构体的拷贝，按字段名匹配
			return copyStructToStruct(srcValue, dstValue)
		}
	case reflect.Map:
		if dstValue.Kind() == reflect.Struct {
			// map到结构体的拷贝，按字段名匹配
			return copyMapToStruct(srcValue, dstValue)
		}
	case reflect.Ptr:
		if srcValue.IsNil() {
			return nil
		}
		return copyValueToType(srcValue.Elem(), dstValue)
	default:
		// 尝试直接类型转换
		if srcValue.Type().ConvertibleTo(dstValue.Type()) {
			dstValue.Set(srcValue.Convert(dstValue.Type()))
			return nil
		}
	}

	return fmt.Errorf("cannot convert %v to %v", srcValue.Type(), dstValue.Type())
}

// copyStructToStruct 结构体到结构体的拷贝
func copyStructToStruct(srcValue, dstValue reflect.Value) error {
	srcType := srcValue.Type()
	dstType := dstValue.Type()

	for i := 0; i < dstValue.NumField(); i++ {
		dstField := dstValue.Field(i)
		dstFieldType := dstType.Field(i)

		if !dstField.CanSet() {
			continue
		}

		// 查找源结构体中同名字段
		srcField, found := srcType.FieldByName(dstFieldType.Name)
		if !found {
			continue
		}

		srcFieldValue := srcValue.FieldByName(dstFieldType.Name)
		if !srcFieldValue.IsValid() {
			continue
		}

		// 递归拷贝字段
		err := copyValueToType(srcFieldValue, dstField)
		if err != nil {
			// 如果字段类型不匹配，尝试跳过
			continue
		}
	}

	return nil
}

// copyMapToStruct map到结构体的拷贝
func copyMapToStruct(srcValue, dstValue reflect.Value) error {
	if srcValue.IsNil() {
		return nil
	}

	dstType := dstValue.Type()

	for _, key := range srcValue.MapKeys() {
		if key.Kind() != reflect.String {
			continue
		}

		fieldName := key.String()
		dstField, found := dstType.FieldByName(fieldName)
		if !found || !dstValue.FieldByName(fieldName).CanSet() {
			continue
		}

		srcFieldValue := srcValue.MapIndex(key)
		dstField := dstValue.FieldByName(fieldName)

		err := copyValueToType(srcFieldValue, dstField)
		if err != nil {
			// 如果字段类型不匹配，尝试跳过
			continue
		}
	}

	return nil
}

// DeepCopyReflect 使用反射实现深度拷贝
// 不依赖JSON序列化，支持更多数据类型，包括私有序段（通过反射访问）
// 性能相对较差但适用范围更广
// 参数:
// - src: 源对象，可以是任意类型
//
// 返回:
// - interface{}: 深度拷贝后的对象
// - error: 拷贝过程中的错误
//
// 示例:
// - original := &User{Name: "李四", Profile: Profile{Email: "test@example.com"}}
// - copied, err := DeepCopyReflect(original)
// - // copied 是 original 的完全独立副本
func DeepCopyReflect(src interface{}) (interface{}, error) {
	if src == nil {
		return nil, nil
	}

	original := reflect.ValueOf(src)
	cpy := reflect.New(original.Type()).Elem()

	// 递归拷贝函数
	copyRecursive := func(original, cpy reflect.Value) {}
	copyRecursive = func(original, cpy reflect.Value) {
		switch original.Kind() {
		case reflect.Ptr:
			// 创建新的指针并递归拷贝指向的值
			originalValue := original.Elem()
			if !originalValue.IsValid() {
				return
			}
			cpy.Set(reflect.New(originalValue.Type()))
			copyRecursive(originalValue, cpy.Elem())

		case reflect.Interface:
			// 处理接口类型
			if original.IsNil() {
				return
			}
			originalValue := original.Elem()
			copyValue := reflect.New(originalValue.Type()).Elem()
			copyRecursive(originalValue, copyValue)
			cpy.Set(copyValue)

		case reflect.Struct:
			// 递归拷贝结构体的每个字段
			for i := 0; i < original.NumField(); i++ {
				if cpy.Field(i).CanSet() {
					copyRecursive(original.Field(i), cpy.Field(i))
				}
			}

		case reflect.Slice:
			// 拷贝切片
			if original.IsNil() {
				return
			}
			cpy.Set(reflect.MakeSlice(original.Type(), original.Len(), original.Cap()))
			for i := 0; i < original.Len(); i++ {
				copyRecursive(original.Index(i), cpy.Index(i))
			}

		case reflect.Map:
			// 拷贝映射
			if original.IsNil() {
				return
			}
			cpy.Set(reflect.MakeMap(original.Type()))
			for _, key := range original.MapKeys() {
				originalValue := original.MapIndex(key)
				copyValue := reflect.New(originalValue.Type()).Elem()
				copyRecursive(originalValue, copyValue)

				copyKey := reflect.New(key.Type()).Elem()
				copyRecursive(key, copyKey)

				cpy.SetMapIndex(copyKey, copyValue)
			}

		case reflect.Array:
			// 拷贝数组
			for i := 0; i < original.Len(); i++ {
				copyRecursive(original.Index(i), cpy.Index(i))
			}

		default:
			// 基本类型直接复制
			if cpy.CanSet() {
				cpy.Set(original)
			}
		}
	}

	copyRecursive(original, cpy)
	return cpy.Interface(), nil
}

// Clone 是 DeepCopyReflect 的简化版本，不返回错误
// 适用于确定不会出错的场景，调用更简洁
// 参数:
// - src: 源对象
//
// 返回:
// - interface{}: 深度拷贝后的对象，如果出错返回 nil
//
// 示例:
// - original := User{Name: "王五"}
// - copied := Clone(original)
// - // 如果拷贝失败，copied 为 nil
func Clone(src interface{}) interface{} {
	result, err := DeepCopyReflect(src)
	if err != nil {
		return nil
	}
	return result
}

// CloneToType 是 DeepCopyToTypeReflect 的简化版本，不返回错误
// 通过传入类型示例来指定目标类型，调用更简洁
// 参数:
// - src: 源对象
// - typeExample: 类型示例，如 User{} 或 &User{}，用于指定目标类型
//
// 返回:
// - interface{}: 指定类型的深度拷贝对象，如果出错返回 nil
//
// 示例:
// - original := map[string]interface{}{"name": "赵六", "age": 30}
// - copied := CloneToType(original, User{})
// - // copied 的类型为 User，如果拷贝失败返回 nil
func CloneToType(src, typeExample interface{}) interface{} {
	result, err := DeepCopyToTypeReflect(src, typeExample)
	if err != nil {
		return nil
	}
	return result
}

// CopyStruct 拷贝结构体到相同类型的结构体
// 使用反射高效拷贝结构体字段，适用于结构体间的快速拷贝
// 参数:
// - src: 源结构体指针
// - dst: 目标结构体指针，必须与src类型相同
//
// 返回:
// - error: 拷贝过程中的错误
//
// 示例:
// - src := &User{Name: "赵六", Age: 30}
// - dst := &User{}
// - err := CopyStruct(src, dst)
// - // dst 现在包含与 src 相同的数据
func CopyStruct(src, dst interface{}) error {
	if src == nil || dst == nil {
		return nil
	}

	srcValue := reflect.ValueOf(src)
	dstValue := reflect.ValueOf(dst)

	// 检查是否为指针
	if srcValue.Kind() != reflect.Ptr || dstValue.Kind() != reflect.Ptr {
		return &reflect.ValueError{Method: "CopyStruct", Kind: reflect.Invalid}
	}

	srcElem := srcValue.Elem()
	dstElem := dstValue.Elem()

	// 检查类型是否相同
	if srcElem.Type() != dstElem.Type() {
		return &reflect.ValueError{Method: "CopyStruct", Kind: reflect.Invalid}
	}

	// 检查是否为结构体
	if srcElem.Kind() != reflect.Struct {
		return &reflect.ValueError{Method: "CopyStruct", Kind: reflect.Invalid}
	}

	// 拷贝所有可导出的字段
	for i := 0; i < srcElem.NumField(); i++ {
		field := srcElem.Type().Field(i)
		// 只拷贝可导出的字段
		if field.PkgPath == "" {
			srcField := srcElem.Field(i)
			dstField := dstElem.Field(i)
			if dstField.CanSet() {
				dstField.Set(srcField)
			}
		}
	}

	return nil
}

// SliceDeepCopy 对切片进行深度拷贝
// 专门针对切片的深度拷贝，性能更优
// 参数:
// - src: 源切片，可以是任意类型的切片
//
// 返回:
// - interface{}: 深度拷贝后的切片
// - error: 拷贝过程中的错误
//
// 示例:
// - original := []User{{Name: "测试1"}, {Name: "测试2"}}
// - copied, err := SliceDeepCopy(original)
// - // copied 是 original 的完全独立副本
func SliceDeepCopy(src interface{}) (interface{}, error) {
	if src == nil {
		return nil, nil
	}

	srcValue := reflect.ValueOf(src)
	if srcValue.Kind() != reflect.Slice {
		return nil, &reflect.ValueError{Method: "SliceDeepCopy", Kind: srcValue.Kind()}
	}

	result := reflect.MakeSlice(srcValue.Type(), srcValue.Len(), srcValue.Cap())

	for i := 0; i < srcValue.Len(); i++ {
		srcElem := srcValue.Index(i)

		// 如果元素是指针、切片、映射、结构体或接口，递归拷贝
		if srcElem.Kind() == reflect.Ptr ||
			srcElem.Kind() == reflect.Slice ||
			srcElem.Kind() == reflect.Map ||
			srcElem.Kind() == reflect.Struct ||
			srcElem.Kind() == reflect.Interface {

			copied, err := DeepCopyReflect(srcElem.Interface())
			if err != nil {
				return nil, err
			}
			result.Index(i).Set(reflect.ValueOf(copied))
		} else {
			// 基本类型直接复制
			result.Index(i).Set(srcElem)
		}
	}

	return result.Interface(), nil
}","instruction":"添加DeepCopyToType和DeepCopyToTypeReflect函数，支持通过传入类型示例(如User{})来指定目标类型进行拷贝","apply_mode":"manual"}},"timestamp":1763436955,"type":"TOOL_CALL_ARGS"}

