func TestDeepCopyToSameType(t *testing.T) {
	type User struct {
		Name string
		Age int
	}
	original := User{Name: "张三", Age: 25}
	copied, err := DeepCopyToSameType(original)
	if err != nil {
		t.Errorf("DeepCopy failed: %v", err)
	}
	fmt.Printf("DeepCopyToSameType result: %v (type: %T)\n", copied, copied)
}

func TestDeepCopyToType(t *testing.T) {
	type User struct {
		Name string `json:"name"`
		Age int `json:"age"`
	}

	// 测试从map拷贝到指定类型
	original := map[string]interface{}{
		"name": "李四",
		"age": 30,
	}

	// 使用类型示例指定目标类型
	copied, err := DeepCopyToType(original, User{})
	if err != nil {
		t.Errorf("DeepCopyToType failed: %v", err)
	}

	user, ok := copied.(User)
	if !ok {
		t.Errorf("Expected User type, got %T", copied)
	}

	fmt.Printf("DeepCopyToType result: %+v (type: %T)\n", user, user)

	if user.Name != "李四" || user.Age != 30 {
		t.Errorf("Expected name=李四, age=30, got name=%s, age=%d", user.Name, user.Age)
	}
}

func TestDeepCopyToTypeReflect(t *testing.T) {
	type TempUser struct {
		Name string
		Age int
		City string
	}

	type User struct {
		Name string
		Age int
	}

	// 测试从不同结构体拷贝到指定类型
	original := TempUser{
		Name: "王五",
		Age: 35,
		City: "北京",
	}

	// 使用反射方式拷贝到指定类型
	copied, err := DeepCopyToTypeReflect(original, User{})
	if err != nil {
		t.Errorf("DeepCopyToTypeReflect failed: %v", err)
	}

	user, ok := copied.(User)
	if !ok {
		t.Errorf("Expected User type, got %T", copied)
	}

	fmt.Printf("DeepCopyToTypeReflect result: %+v (type: %T)\n", user, user)

	if user.Name != "王五" || user.Age != 35 {
		t.Errorf("Expected name=王五, age=35, got name=%s, age=%d", user.Name, user.Age)
	}
}

func TestCloneToType(t *testing.T) {
	type User struct {
		Name string
		Age int
	}

	// 测试简化版本，不返回错误
	original := map[string]interface{}{
		"name": "赵六",
		"age": 40,
	}

	// 使用类型示例指定目标类型，简化调用
	copied := CloneToType(original, User{})
	if copied == nil {
