		return
	}

	user, ok := copied.(User)
	if !ok {
		t.Errorf("Expected User type, got %T", copied)
	}

	fmt.Printf("CloneToType result: %+v (type: %T)\n", user, user)

	if user.Name != "赵六" || user.Age != 40 {
		t.Errorf("Expected name=赵六, age=40, got name=%s, age=%d", user.Name, user.Age)
	}
}

func TestPointerTypeExample(t *testing.T) {
	type User struct {
		Name string
		Age int
	}

	original := map[string]interface{}{
		"name": "钱七",
		"age": 45,
	}

	// 测试使用指针类型示例
	copied, err := DeepCopyToType(original, &User{})
	if err != nil {
		t.Errorf("DeepCopyToType with pointer failed: %v", err)
	}

	user, ok := copied.(*User)
	if !ok {
		t.Errorf("Expected *User type, got %T", copied)
	}

	fmt.Printf("Pointer type example result: %+v (type: %T)\n", user, user)

	if user.Name != "钱七" || user.Age != 45 {
		t.Errorf("Expected name=钱七, age=45, got name=%s, age=%d", user.Name, user.Age)
	}
