{"rawEvent":{"message_id":"019a94fa5cfd7a6995dbd7fecc1b95e7","conversation_id":"019a94fa314576b99f19524310f11e8b","tool_call_id":"call_b08012714c594bd5976f01dd","document":{"file_path":"/Users/jacklingo/dev/model_infrax/assert/template/tools/collection.go","sub_content":"collection.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/assert/template/tools/collection.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/assert/template/tools/collection.go","apply_content":"package tool

import (
	"reflect"
	"sort"
)

// Contains 检查切片中是否包含指定元素
// 使用反射实现，支持任意类型的切片
// 参数:
// - slice: 待检查的切片
// - item: 要查找的元素
//
// 返回:
// - bool: 如果包含返回true，否则返回false
//
// 示例:
// - Contains([]string{"a", "b", "c"}, "b") -> true
// - Contains([]int{1, 2, 3}, 4) -> false
func Contains(slice interface{}, item interface{}) bool {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return false
	}

	for i := 0; i < sliceValue.Len(); i++ {
		if reflect.DeepEqual(sliceValue.Index(i).Interface(), item) {
			return true
		}
	}
	return false
}

// RemoveFromSlice 从切片中移除指定元素，返回新切片
// 使用反射实现，支持任意类型的切片
// 参数:
// - slice: 原始切片
// - item: 要移除的元素
//
// 返回:
// - interface{}: 移除指定元素后的新切片
//
// 示例:
// - RemoveFromSlice([]string{"a", "b", "c"}, "b") -> []string{"a", "c"}
func RemoveFromSlice(slice interface{}, item interface{}) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return slice
	}

	result := reflect.MakeSlice(sliceValue.Type(), 0, sliceValue.Len())
	for i := 0; i < sliceValue.Len(); i++ {
		current := sliceValue.Index(i).Interface()
		if !reflect.DeepEqual(current, item) {
			result = reflect.Append(result, sliceValue.Index(i))
		}
	}
	return result.Interface()
}

// Unique 去除切片中的重复元素，返回新切片
// 使用反射和map实现，支持任意类型的切片
// 参数:
// - slice: 原始切片
//
// 返回:
// - interface{}: 去重后的新切片
//
// 示例:
// - Unique([]string{"a", "b", "a", "c"}) -> []string{"a", "b", "c"}
func Unique(slice interface{}) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return slice
	}

	seen := make(map[interface{}]bool)
	result := reflect.MakeSlice(sliceValue.Type(), 0, sliceValue.Len())

	for i := 0; i < sliceValue.Len(); i++ {
		current := sliceValue.Index(i).Interface()
		if !seen[current] {
			seen[current] = true
			result = reflect.Append(result, sliceValue.Index(i))
		}
	}
	return result.Interface()
}

// Filter 过滤切片中的元素，返回满足条件的新切片
// 参数:
// - slice: 原始切片
// - predicate: 过滤条件函数，返回true保留元素，false过滤掉元素
//
// 返回:
// - interface{}: 过滤后的新切片
//
// 示例:
// - Filter([]int{1, 2, 3, 4}, func(i interface{}) bool { return i.(int) > 2 })
// -> []int{3, 4}
func Filter(slice interface{}, predicate func(interface{}) bool) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return slice
	}

	result := reflect.MakeSlice(sliceValue.Type(), 0, sliceValue.Len())
	for i := 0; i < sliceValue.Len(); i++ {
		current := sliceValue.Index(i).Interface()
		if predicate(current) {
			result = reflect.Append(result, sliceValue.Index(i))
		}
	}
	return result.Interface()
}

// Map 对切片中的每个元素应用转换函数，返回新切片
// 参数:
// - slice: 原始切片
// - mapper: 转换函数，将原始元素转换为目标元素
//
// 返回:
// - interface{}: 转换后的新切片
//
// 示例:
// - Map([]int{1, 2, 3}, func(i interface{}) interface{} { return i.(int) * 2 })
// -> []int{2, 4, 6}
func Map(slice interface{}, mapper func(interface{}) interface{}) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return slice
	}

	result := reflect.MakeSlice(sliceValue.Type(), 0, sliceValue.Len())
	for i := 0; i < sliceValue.Len(); i++ {
		current := sliceValue.Index(i).Interface()
		mapped := mapper(current)
		mappedValue := reflect.ValueOf(mapped)
		if mappedValue.Type().AssignableTo(result.Type().Elem()) {
			result = reflect.Append(result, mappedValue)
		}
	}
	return result.Interface()
}

// Reduce 将切片元素聚合成单个值
// 参数:
// - slice: 原始切片
// - accumulator: 聚合函数，接收当前累加值和当前元素，返回新的累加值
// - initialValue: 初始累加值
//
// 返回:
// - interface{}: 聚合后的结果
//
// 示例:
// - Reduce([]int{1, 2, 3}, func(acc, item interface{}) interface{} { 
// return acc.(int) + item.(int) }, 0) -> 6
func Reduce(slice interface{}, accumulator func(interface{}, interface{}) interface{}, initialValue interface{}) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return initialValue
	}

	result := initialValue
	for i := 0; i < sliceValue.Len(); i++ {
		current := sliceValue.Index(i).Interface()
		result = accumulator(result, current)
	}
	return result
}

// Reverse 反转切片中的元素顺序，返回新切片
// 使用反射实现，支持任意类型的切片
// 参数:
// - slice: 原始切片
//
// 返回:
// - interface{}: 反转后的新切片
//
// 示例:
// - Reverse([]string{"a", "b", "c"}) -> []string{"c", "b", "a"}
func Reverse(slice interface{}) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice {
		return slice
	}

	length := sliceValue.Len()
	result := reflect.MakeSlice(sliceValue.Type(), length, length)
	for i := 0; i < length; i++ {
		result.Index(i).Set(sliceValue.Index(length - 1 - i))
	}
	return result.Interface()
}

// Chunk 将切片分割成指定大小的块，返回二维切片
// 参数:
// - slice: 原始切片
// - size: 每块的大小，必须大于0
//
// 返回:
// - interface{}: 分块后的二维切片
//
// 示例:
// - Chunk([]int{1, 2, 3, 4, 5}, 2) -> [][]int{{1, 2}, {3, 4}, {5}}
func Chunk(slice interface{}, size int) interface{} {
	sliceValue := reflect.ValueOf(slice)
	if sliceValue.Kind() != reflect.Slice || size <= 0 {
		return slice
	}

	length := sliceValue.Len()
	if length == 0 {
		return slice
	}

	// 创建二维切片类型
	elemType := sliceValue.Type().Elem()
	resultType := reflect.SliceOf(reflect.SliceOf(elemType))
	result := reflect.MakeSlice(resultType, 0, (length+size-1)/size)

	for i := 0; i < length; i += size {
		end := i + size
		if end > length {
			end = length
		}

		chunk := sliceValue.Slice(i, end)
		result = reflect.Append(result, chunk)
	}
	return result.Interface()
}

// SortStrings 对字符串切片进行排序，返回新切片
// 参数:
// - slice: 字符串切片
// - ascending: 是否升序排列，true为升序，false为降序
//
// 返回:
// - []string: 排序后的新切片
//
// 示例:
// - SortStrings([]string{"c", "a", "b"}, true) -> []string{"a", "b", "c"}
func SortStrings(slice []string, ascending bool) []string {
	result := make([]string, len(slice))
	copy(result, slice)

	if ascending {
		sort.Strings(result)
	} else {
		sort.Sort(sort.Reverse(sort.StringSlice(result)))
	}
	return result
}

// SortInts 对整数切片进行排序，返回新切片
// 参数:
// - slice: 整数切片
// - ascending: 是否升序排列，true为升序，false为降序
//
// 返回:
// - []int: 排序后的新切片
//
// 示例:
// - SortInts([]int{3, 1, 2}, true) -> []int{1, 2, 3}
func SortInts(slice []int, ascending bool) []int {
	result := make([]int, len(slice))
	copy(result, slice)

	if ascending {
		sort.Ints(result)
	} else {
		sort.Sort(sort.Reverse(sort.IntSlice(result)))
	}
	return result
}

// Intersection 计算两个切片的交集，返回包含共同元素的新切片
// 参数:
// - slice1: 第一个切片
// - slice2: 第二个切片
//
// 返回:
// - interface{}: 交集切片，元素顺序按照在slice1中的出现顺序
//
// 示例:
// - Intersection([]string{"a", "b", "c"}, []string{"b", "c", "d"}) -> []string{"b", "c"}
func Intersection(slice1, slice2 interface{}) interface{} {
	slice1Value := reflect.ValueOf(slice1)
	slice2Value := reflect.ValueOf(slice2)

	if slice1Value.Kind() != reflect.Slice || slice2Value.Kind() != reflect.Slice {
		return nil
	}

	// 将第二个切片转换为map以便快速查找
	lookup := make(map[interface{}]bool)
	for i := 0; i < slice2Value.Len(); i++ {
		lookup[slice2Value.Index(i).Interface()] = true
	}

	result := reflect.MakeSlice(slice1Value.Type(), 0, slice1Value.Len())
	seen := make(map[interface{}]bool) // 避免重复添加

	for i := 0; i < slice1Value.Len(); i++ {
		current := slice1Value.Index(i).Interface()
		if lookup[current] && !seen[current] {
			result = reflect.Append(result, slice1Value.Index(i))
			seen[current] = true
		}
	}
	return result.Interface()
}

// Union 计算两个切片的并集，返回包含所有不重复元素的新切片
// 参数:
// - slice1: 第一个切片
// - slice2: 第二个切片
//
// 返回:
// - interface{}: 并集切片，元素顺序按照在原切片中的出现顺序
//
// 示例:
// - Union([]string{"a", "b"}, []string{"b", "c"}) -> []string{"a", "b", "c"}
func Union(slice1, slice2 interface{}) interface{} {
	slice1Value := reflect.ValueOf(slice1)
	slice2Value := reflect.ValueOf(slice2)

	if slice1Value.Kind() != reflect.Slice || slice2Value.Kind() != reflect.Slice {
		return nil
	}

	// 创建结果切片，先添加slice1的元素
	result := reflect.MakeSlice(slice1Value.Type(), 0, slice1Value.Len()+slice2Value.Len())
	seen := make(map[interface{}]bool)

	// 添加第一个切片的元素
	for i := 0; i < slice1Value.Len(); i++ {
		current := slice1Value.Index(i).Interface()
		if !seen[current] {
			result = reflect.Append(result, slice1Value.Index(i))
			seen[current] = true
		}
	}

	// 添加第二个切片的元素（跳过已存在的）
	for i := 0; i < slice2Value.Len(); i++ {
		current := slice2Value.Index(i).Interface()
		if !seen[current] {
			result = reflect.Append(result, slice2Value.Index(i))
			seen[current] = true
		}
	}
	return result.Interface()
}

// Difference 计算两个切片的差集，返回在slice1中但不在slice2中的元素
// 参数:
// - slice1: 第一个切片
// - slice2: 第二个切片
//
// 返回:
// - interface{}: 差集切片
//
// 示例:
// - Difference([]string{"a", "b", "c"}, []string{"b", "d"}) -> []string{"a", "c"}
func Difference(slice1, slice2 interface{}) interface{} {
	slice1Value := reflect.ValueOf(slice1)
	slice2Value := reflect.ValueOf(slice2)

	if slice1Value.Kind() != reflect.Slice || slice2Value.Kind() != reflect.Slice {
		return nil
	}

	// 将第二个切片转换为map以便快速查找
	lookup := make(map[interface{}]bool)
	for i := 0; i < slice2Value.Len(); i++ {
		lookup[slice2Value.Index(i).Interface()] = true
	}

	result := reflect.MakeSlice(slice1Value.Type(), 0, slice1Value.Len())
	for i := 0; i < slice1Value.Len(); i++ {
		current := slice1Value.Index(i).Interface()
		if !lookup[current] {
			result = reflect.Append(result, slice1Value.Index(i))
		}
	}
	return result.Interface()
}","instruction":"在collection.go文件中实现常用的集合工具函数，包含Contains、RemoveFromSlice、Unique、Filter、Map、Reduce、Reverse、Chunk、SortStrings、SortInts、Intersection、Union、Difference等函数，每个函数都有详细的注释和示例","apply_mode":"manual"}},"timestamp":1763436087,"type":"TOOL_CALL_ARGS"}

