// 5. 生成DAO数据访问对象代码
// 6. 生成Tool工具类代码
func (a *App) Run() error {
	log.Println(" 开始解析数据库...")

	// 获取数据库中所有表的结构信息
	schemas, err := a.DatabaseParser.Parse()
	if err != nil {
		return err
	}

	log.Printf("✅ 解析完成，共获取到 %d 个表", len(schemas))

	// 根据配置文件中的表名过滤规则，筛选需要生成代码的表
	schemas = a.DatabaseParser.FilterTables(schemas)
	log.Printf(" 过滤后需要处理的表数量: %d", len(schemas))","new_string":"// Run 运行应用程序，执行完整的代码生成流程
