// 2. 根据配置过滤需要处理的表
// 3. 生成Model实体类代码
// 4. 生成DTO数据传输对象代码
// 5. 生成DAO数据访问对象代码
// 6. 生成Tool工具类代码
func (a *App) Run() error {
	var schemas []model.Schema
	var err error

	// 根据配置的生成模式选择不同的解析器
	switch a.Config.GenerateConfig.GenerateMode {
	case "database":
		// 从数据库解析表结构
		log.Println(" 开始从数据库解析表结构...")
		schemas, err = a.DatabaseParser.Parse()
		if err != nil {
			return err
