package main

import (
	"log"
	"model_infrax/config"
	"model_infrax/generator"
	"model_infrax/parser"

	flag "github.com/spf13/pflag"
)

type App struct {
	Config          *config.Configger
	DatabaseParser  *parser.DatabaseParser
	StatementParser *parser.StatementParser
	Generator       *generator.Generator
}

func NewApp(cfg *config.Configger, p *parser.DatabaseParser, g *generator.Generator, s *parser.StatementParser) *App {
	return &App{
		Config:          cfg,
		DatabaseParser:  p,
		Generator:       g,
		StatementParser: s,
	}
}

// Run 运行应用程序，执行完整的代码生成流程
// 流程包括：
// 1. 解析数据库表结构
// 2. 根据配置过滤需要处理的表
// 3. 生成Model实体类代码
// 4. 生成DTO数据传输对象代码
// 5. 生成DAO数据访问对象代码
// 6. 生成Tool工具类代码
func (a *App) Run() error {
	log.Println(" 开始解析数据库...")

	// 获取数据库中所有表的结构信息
	schemas, err := a.DatabaseParser.Parse()
	if err != nil {
		return err
	}

	log.Printf("✅ 解析完成，共获取到 %d 个表", len(schemas))

	// 根据配置文件中的表名过滤规则，筛选需要生成代码的表
	schemas = a.DatabaseParser.FilterTables(schemas)
	log.Printf(" 过滤后需要处理的表数量: %d", len(schemas))

	log.Println("️ 开始生成 Model 代码...")

	// 生成Model实体类代码
	// 根据配置决定是生成到一个文件还是分别生成
	if a.Config.GenerateOption.ModelAllInOneFile {
		err = a.Generator.GenerateModel(schemas, a.Config.GenerateOption.ModelAllInOneFileName)
	} else {
		err = a.Generator.GenerateModelOneByOne(schemas)
	}
	if err != nil {
		return err
	}

	log.Println("✅ Model 代码生成完成")

	log.Println(" 开始生成 DTO 代码...")

	// 生成DTO数据传输对象代码，用于API接口的数据交换
	err = a.Generator.GenerateDTOOneByOne(schemas)
	if err != nil {
		return err
	}

	log.Println("✅ DTO 代码生成完成")

	log.Println("️ 开始生成 DAO 代码...")

	// 生成DAO数据访问对象代码，提供数据库操作方法
	err = a.Generator.GenerateDAOOneByOne(schemas)
	if err != nil {
		return err
	}

	log.Println("✅ DAO 代码生成完成")

	log.Println("️ 开始生成 Tool 工具代码...")

	// 生成Tool工具类代码，提供通用的辅助功能
	err = a.Generator.GenerateAllTools()
	if err != nil {
		return err
	}

	log.Println(" 所有代码生成完成！")

	return nil
}

func main() {

	configPath := flag.StringP("config", "c", "./assert/application.yml", "配置文件路径")
	sqlPath := flag.StringP("sql", "s", "./assert/database.sql", "sql文件路径")

	flag.Parse()

	app, err := InitializeApp(*configPath)
	if err != nil {
		log.Fatalf("初始化应用失败: %v", err)
	}

	if err = app.Run(); err != nil {
		log.Fatalf("运行应用失败: %v", err)
	}
}

package parser

import (
	"fmt"
	"log"
	"model_infrax/config"
	"model_infrax/tool"
	"os"
	"testing"

	"github.com/pingcap/tidb/pkg/parser"
	"github.com/pingcap/tidb/pkg/parser/ast"
	_ "github.com/pingcap/tidb/pkg/parser/test_driver"
)

type colX struct {
	colNames []string
}

func (v *colX) Enter(in ast.Node) (ast.Node, bool) {
	if name, ok := in.(*ast.ColumnName); ok {
		v.colNames = append(v.colNames, name.Name.O)
	}
	return in, false
}

func (v *colX) Leave(in ast.Node) (ast.Node, bool) {
	return in, true
}

func extract(rootNode *ast.StmtNode) []string {
	v := &colX{}
	(*rootNode).Accept(v)
	return v.colNames
}

func parse(sql string) (*ast.StmtNode, error) {
	p := parser.New()

	stmtNodes, _, err := p.ParseSQL(sql)
	if err != nil {
		return nil, err
	}

	return &stmtNodes[0], nil
}

func TestTidbPaseNode(t *testing.T) {
	p := parser.New()

	byts, err := os.ReadFile("/Users/jacklingo/dev/model_infrax/assert/database.sql")
	if err != nil {
		panic(err)
	}

	statement := string(byts)

	stmtNodes, _, err := p.ParseSQL(statement)
	if err != nil {
		panic(err)
	}

	log.Printf("stmtNodes: %s", tool.JsonifyIndent(stmtNodes))
}

func TestTiDBParser(t *testing.T) {
	byts, err := os.ReadFile("/Users/jacklingo/dev/model_infrax/assert/database.sql")
	if err != nil {
		panic(err)
	}

	statement := string(byts)

	astNode, err := parse(statement)
	if err != nil {
		fmt.Printf("parse error: %v\n", err.Error())
		return
	}
	fmt.Printf("%s\n", tool.JsonifyIndent(extract(astNode)))
}

func TestStatementParser_Parse(t *testing.T) {
	sqlFilePath := "/Users/jacklingo/dev/model_infrax/assert/database.sql"

	configger, err := config.NewConfigger("/Users/jacklingo/dev/model_infrax/assert/application.yml")
	if err != nil {
		panic(err)
	}

	parser, err := NewStatementParser(configger, sqlFilePath)
	if err != nil {
		panic(err)
	}

	schemas, err := parser.Parse()
	if err != nil {
		panic(err)
	}

	log.Printf("schemas: %s", tool.JsonifyIndent(schemas))
}

