{"rawEvent":{"message_id":"019a925741f476cd804cfb115d34d4e2","conversation_id":"019a924c423f72a287e1d3c5cf4f1b17","tool_call_id":"tooluse_evr3vqxcQdCG1LA5bgu4CA","document":{"file_path":"/Users/jacklingo/dev/model_infrax/parser/statement_parser.go","sub_content":"statement_parser.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/parser/statement_parser.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/parser/statement_parser.go","apply_content":"package parser

import (
	"fmt"
	"log"
	"model_infrax/config"
	"model_infrax/model"
	"model_infrax/tool"
	"os"
	"regexp"
	"strings"

	"github.com/samber/lo"
)

type StatementParser struct {
	configger *config.Configger
	statements []string
}

func NewStatementParser(cfg *config.Configger, sqlFilePath string) (*StatementParser, error) {
	path := tool.EscapeHomeDir(sqlFilePath)

	byts, err := os.ReadFile(path)
	if err != nil {
		return nil, err
	}

	statements := strings.Split(string(byts), ";")

	return &StatementParser{
		configger: cfg,
		statements: statements,
	}, nil
}

func (p *StatementParser) Parse() (schemas []model.Schema, err error) {
	for _, statement := range p.statements {
		// 跳过空语句
		trimmed := strings.TrimSpace(statement)
		if trimmed == "" {
			continue
		}

		log.Printf("⌛️ parsing statement: %s", statement)
		var schema model.Schema
		schema, err = p.parseStatement(statement)
		if err != nil {
			return nil, fmt.Errorf("解析语句失败: %w", err)
		}
		schemas = append(schemas, schema)
	}
	return
}

func (p *StatementParser) FilterTables(schemas []model.Schema) (filtered []model.Schema) {
	if p.configger.GenerateConfig.AllTables {
		filtered = schemas
		return
	}
	filtered = lo.Filter(schemas, func(schema model.Schema, index int) bool {
		return lo.Contains(p.configger.GenerateConfig.TableNames, schema.Name)
	})
	return
}

func (p *StatementParser) parseStatement(statement string) (schema model.Schema, err error) {
	// 清理语句，去除多余的空白字符
	statement = strings.TrimSpace(statement)
	if statement == "" {
		return schema, nil
	}

	// 1. 提取表名和表注释
	// 匹配: CREATE TABLE IF NOT EXISTS `table_name` ... COMMENT = 'table comment'
	tableRegex := regexp.MustCompile(`CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?` + "`" + `([^` + "`" + `]+)` + "`")
	tableMatches := tableRegex.FindStringSubmatch(statement)
	if len(tableMatches) < 2 {
		return schema, fmt.Errorf("无法解析表名")
	}
	schema.Name = tableMatches[1]

	// 提取表注释
	tableCommentRegex := regexp.MustCompile(`COMMENT\s*=\s*'([^']*)'`)
	tableCommentMatches := tableCommentRegex.FindStringSubmatch(statement)
	if len(tableCommentMatches) >= 2 {
		schema.Comment = tableCommentMatches[1]
	}

	// 2. 提取列定义部分（在括号内的内容）
	contentRegex := regexp.MustCompile(`\(([\s\S]+)\)\s*ENGINE`)
	contentMatches := contentRegex.FindStringSubmatch(statement)
	if len(contentMatches) < 2 {
		return schema, fmt.Errorf("无法解析表内容")
	}
	content := contentMatches[1]

	// 3. 分割每一行定义
	lines := strings.Split(content, "\n")

	// 用于存储主键和索引的列名
	var primaryKeyColumns []string
	var indexes []model.Index
	var uniqueIndexes []model.Index

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || line == "," {
			continue
		}
		// 去除行尾的逗号
		line = strings.TrimSuffix(line, ",")

		// 4. 解析主键定义
		// 匹配: PRIMARY KEY (`id`) 或 PRIMARY KEY (`col1`, `col2`)
		if strings.HasPrefix(line, "PRIMARY KEY") {
			pkRegex := regexp.MustCompile("PRIMARY KEY \\(([^)]+)\\)")
			pkMatches := pkRegex.FindStringSubmatch(line)
			if len(pkMatches) >= 2 {
				// 提取列名，去除反引号
				colsStr := pkMatches[1]
				colsStr = strings.ReplaceAll(colsStr, "`", "")
				primaryKeyColumns = strings.Split(colsStr, ",")
				for i := range primaryKeyColumns {
					primaryKeyColumns[i] = strings.TrimSpace(primaryKeyColumns[i])
				}
			}
			continue
		}

		// 5. 解析唯一索引定义
		// 匹配: UNIQUE KEY `uk_memoryId` (`memoryId`)
		if strings.HasPrefix(line, "UNIQUE KEY") {
			ukRegex := regexp.MustCompile("UNIQUE KEY `([^`]+)` \\(([^)]+)\\)")
			ukMatches := ukRegex.FindStringSubmatch(line)
			if len(ukMatches) >= 3 {
				indexName := ukMatches[1]
				colsStr := strings.ReplaceAll(ukMatches[2], "`", "")
				colNames := strings.Split(colsStr, ",")

				var indexColumns []model.Column
				for _, colName := range colNames {
					colName = strings.TrimSpace(colName)
					indexColumns = append(indexColumns, model.Column{ColumnName: colName})
				}

				uniqueIndexes = append(uniqueIndexes, model.Index{
					IndexName: indexName,
					Columns: indexColumns,
				})
			}
			continue
		}

		// 6. 解析普通索引定义
		// 匹配: KEY `idx_userId_userName` (`userId`, `userName`)
		if strings.HasPrefix(line, "KEY") {
			keyRegex := regexp.MustCompile("KEY `([^`]+)` \\(([^)]+)\\)")
			keyMatches := keyRegex.FindStringSubmatch(line)
			if len(keyMatches) >= 3 {
				indexName := keyMatches[1]
				colsStr := strings.ReplaceAll(keyMatches[2], "`", "")
				colNames := strings.Split(colsStr, ",")

				var indexColumns []model.Column
				for _, colName := range colNames {
					colName = strings.TrimSpace(colName)
					indexColumns = append(indexColumns, model.Column{ColumnName: colName})
				}

				indexes = append(indexes, model.Index{
					IndexName: indexName,
					Columns: indexColumns,
				})
			}
			continue
		}

		// 7. 解析列定义
		// 匹配: `columnName` type [NOT NULL] [DEFAULT value] [AUTO_INCREMENT] [COMMENT 'comment']
		if strings.HasPrefix(line, "`") {
			column := model.Column{}

			// 提取列名
			colNameRegex := regexp.MustCompile("^`([^`]+)`")
			colNameMatches := colNameRegex.FindStringSubmatch(line)
			if len(colNameMatches) < 2 {
				continue
			}
			column.ColumnName = colNameMatches[1]

			// 提取列类型（在列名后的第一个单词或括号表达式）
			typeRegex := regexp.MustCompile("`[^`]+`\\s+([a-zA-Z]+(?:\\([^)]+\\))?)")
			typeMatches := typeRegex.FindStringSubmatch(line)
			if len(typeMatches) >= 2 {
				column.Type = typeMatches[1]
			}

			// 判断是否允许 NULL
			column.IsNullable = !strings.Contains(line, "NOT NULL")

			// 判断是否自增
			column.IsAutoIncrement = strings.Contains(line, "AUTO_INCREMENT")

			// 提取默认值
			defaultRegex := regexp.MustCompile(`DEFAULT\s+([^\s,]+(?:\s+[^\s,]+)?)`)
			defaultMatches := defaultRegex.FindStringSubmatch(line)
			if len(defaultMatches) >= 2 {
				defaultValue := strings.Trim(defaultMatches[1], "'\"")
				// 处理 CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP 的情况
				if strings.Contains(line, "ON UPDATE") {
					defaultValue = strings.Split(defaultValue, " ON ")[0]
					defaultValue = strings.TrimSpace(defaultValue)
				}
				column.Default = &defaultValue
			}

			// 提取列注释
			commentRegex := regexp.MustCompile(`COMMENT\s+'([^']*)'`)
			commentMatches := commentRegex.FindStringSubmatch(line)
			if len(commentMatches) >= 2 {
				column.Comment = commentMatches[1]
			}

			// 判断是否为主键
			column.IsPrimaryKey = lo.Contains(primaryKeyColumns, column.ColumnName)

			schema.Columns = append(schema.Columns, column)
		}
	}

	// 8. 设置主键索引
	if len(primaryKeyColumns) > 0 {
		var pkColumns []model.Column
		for _, pkCol := range primaryKeyColumns {
			pkColumns = append(pkColumns, model.Column{ColumnName: pkCol})
		}
		schema.PrimaryKey = model.Index{
			IndexName: "PRIMARY",
			Columns: pkColumns,
		}
	}

	// 9. 标记有索引的列
	for i := range schema.Columns {
		// 检查是否在普通索引中
		for _, idx := range indexes {
			for _, idxCol := range idx.Columns {
				if idxCol.ColumnName == schema.Columns[i].ColumnName {
					schema.Columns[i].IsIndexed = true
					break
				}
			}
		}

		// 检查是否在唯一索引中
		for _, idx := range uniqueIndexes {
			for _, idxCol := range idx.Columns {
				if idxCol.ColumnName == schema.Columns[i].ColumnName {
					schema.Columns[i].IsIndexed = true
					schema.Columns[i].IsUnique = true
					break
				}
			}
		}
	}

	schema.Indexes = indexes
	schema.UniqueIndex = uniqueIndexes

	return schema, nil
}
","instruction":"补全 parseStatement 方法，使用正则表达式解析 CREATE TABLE SQL 语句，提取表名、列信息、注释、主键和索引","apply_mode":"manual"}},"timestamp":1763391824,"type":"TOOL_CALL_ARGS"}

