import (
	"fmt"
	"model_infrax/config"
	"model_infrax/model"
	"os"
	"strings"

	"github.com/pingcap/tidb/parser"
	"github.com/pingcap/tidb/parser/ast"
	"github.com/pingcap/tidb/parser/mysql"
	_ "github.com/pingcap/tidb/parser/test_driver"
	"github.com/samber/lo"
)

// StatementParser SQL语句解析器，用于从SQL语句解析表结构
type StatementParser struct {
	configger *config.Configger
	sqlText string // 存储要解析的SQL文本
}

// NewStatementParser 创建一个新的SQL语句解析器
// cfg: 配置对象
func NewStatementParser(cfg *config.Configger) *StatementParser {
	return &StatementParser{
		configger: cfg,
	}
}

// ParseFromFile 从SQL文件中解析表结构
// filePath: SQL文件路径
func (p *StatementParser) ParseFromFile(filePath string) ([]model.Schema, error) {
	// 读取SQL文件内容
	data, err := os.ReadFile(filePath)
	if err != nil {
		return nil, fmt.Errorf("读取SQL文件失败: %w", err)
	}

	p.sqlText = string(data)
	return p.Parse()
}

// ParseFromSQL 从SQL字符串中解析表结构
// sql: SQL语句字符串
func (p *StatementParser) ParseFromSQL(sql string) ([]model.Schema, error) {
	p.sqlText = sql
	return p.Parse()
}

// Parse 解析SQL语句，提取表结构信息
// 实现 Parser 接口
func (p *StatementParser) Parse() (schemas []model.Schema, err error) {
	if p.sqlText == "" {
		return nil, fmt.Errorf("SQL文本为空，请先调用 ParseFromFile 或 ParseFromSQL")
	}

	// 创建TiDB Parser实例
	parser := parser.New()

	// 解析SQL语句
	stmts, _, err := parser.Parse(p.sqlText, "", "")
	if err != nil {
		return nil, fmt.Errorf("解析SQL语句失败: %w", err)
	}

	// 遍历所有语句，提取CREATE TABLE语句
	for _, stmt := range stmts {
		// 只处理CREATE TABLE语句
		createTableStmt, ok := stmt.(*ast.CreateTableStmt)
		if !ok {
			continue
		}

		// 解析单个表结构
		schema, err := p.parseCreateTableStmt(createTableStmt)
		if err != nil {
			return nil, fmt.Errorf("解析表 %s 失败: %w", createTableStmt.Table.Name.O, err)
		}

		schemas = append(schemas, schema)
	}

	return schemas, nil
}

// parseCreateTableStmt 解析单个CREATE TABLE语句
// stmt: CREATE TABLE AST节点
func (p *StatementParser) parseCreateTableStmt(stmt *ast.CreateTableStmt) (model.Schema, error) {
	tableName := stmt.Table.Name.O
	tableComment := ""

	// 提取表注释
	for _, opt := range stmt.Options {
		if opt.Tp == ast.TableOptionComment {
			tableComment = opt.StrValue
			break
		}
	}

	// 解析列信息
	var columns []model.Column
	columnMap := make(map[string]*model.Column) // 使用指针以便后续修改

	for _, col := range stmt.Cols {
		column := p.parseColumnDef(col)
		columns = append(columns, column)
		columnMap[column.ColumnName] = &columns[len(columns)-1] // 保存指针引用
	}

	// 解析约束（主键、唯一键、索引等）
	var primaryKey model.Index
	var uniqueIndexes []model.Index
	var indexes []model.Index

	for _, constraint := range stmt.Constraints {
		switch constraint.Tp {
		case ast.ConstraintPrimaryKey:
			// 解析主键
			primaryKey = p.parseIndexConstraint(constraint, columnMap, "PRIMARY")
			// 标记主键列
			for _, col := range primaryKey.Columns {
				if c, ok := columnMap[col.ColumnName]; ok {
					c.IsPrimaryKey = true
					c.IsIndexed = true
				}
			}

		case ast.ConstraintUniq, ast.ConstraintUniqKey, ast.ConstraintUniqIndex:
			// 解析唯一索引
			indexName := constraint.Name
			if indexName == "" {
				indexName = p.generateIndexName(constraint.Keys)
			}
			uniqueIdx := p.parseIndexConstraint(constraint, columnMap, indexName)
			uniqueIndexes = append(uniqueIndexes, uniqueIdx)
			indexes = append(indexes, uniqueIdx)
			// 标记唯一索引列
			for _, col := range uniqueIdx.Columns {
				if c, ok := columnMap[col.ColumnName]; ok {
					c.IsUnique = true
					c.IsIndexed = true
				}
			}

		case ast.ConstraintKey, ast.ConstraintIndex:
			// 解析普通索引
			indexName := constraint.Name
			if indexName == "" {
				indexName = p.generateIndexName(constraint.Keys)
			}
			idx := p.parseIndexConstraint(constraint, columnMap, indexName)
			indexes = append(indexes, idx)
			// 标记索引列
			for _, col := range idx.Columns {
				if c, ok := columnMap[col.ColumnName]; ok {
					c.IsIndexed = true
				}
			}
		}
	}

	// 去重唯一索引（因为可能已经在indexes中）
	uniqueIndexes = lo.UniqBy(uniqueIndexes, func(idx model.Index) string {
		return idx.IndexName
	})

	return model.Schema{
		Name: tableName,
		Comment: tableComment,
		Columns: columns,
		PrimaryKey: primaryKey,
		Indexes: indexes,
		UniqueIndex: uniqueIndexes,
	}, nil
}

// parseColumnDef 解析列定义
// col: 列定义AST节点
func (p *StatementParser) parseColumnDef(col *ast.ColumnDef) model.Column {
	columnName := col.Name.Name.O
	columnType := p.formatColumnType(col.Tp)
	comment := ""
	var defaultValue *string
	isAutoIncrement := false
	isNullable := true // 默认允许NULL

	// 解析列选项
	for _, opt := range col.Options {
		switch opt.Tp {
		case ast.ColumnOptionComment:
			// 提取注释
			comment = opt.Expr.GetDatum().GetString()

		case ast.ColumnOptionDefaultValue:
			// 提取默认值
			if opt.Expr != nil {
				val := opt.Expr.GetDatum().GetString()
				defaultValue = &val
			}

		case ast.ColumnOptionAutoIncrement:
			// 标记自增
			isAutoIncrement = true

		case ast.ColumnOptionNotNull:
			// 标记NOT NULL
			isNullable = false

		case ast.ColumnOptionNull:
			// 标记NULL
			isNullable = true

		case ast.ColumnOptionPrimaryKey:
			// 列级主键定义（会在后续处理约束时再次标记）
			isNullable = false
		}
	}

	return model.Column{
		ColumnName: columnName,
		Collate: p.getCollation(col.Tp),
		Comment: comment,
		Type: columnType,
		Default: defaultValue,
		IsAutoIncrement: isAutoIncrement,
		IsNullable: isNullable,
		IsIndexed: false, // 初始值，后续根据索引信息更新
		IsUnique: false, // 初始值，后续根据索引信息更新
		IsPrimaryKey: false, // 初始值，后续根据索引信息更新
	}
}

// parseIndexConstraint 解析索引约束
// constraint: 约束AST节点
// columnMap: 列名到列对象的映射
// indexName: 索引名称
func (p *StatementParser) parseIndexConstraint(
	constraint *ast.Constraint,
	columnMap map[string]*model.Column,
	indexName string,
) model.Index {
	var indexColumns []model.Column

	for _, key := range constraint.Keys {
		colName := key.Column.Name.O
		if col, ok := columnMap[colName]; ok {
			indexColumns = append(indexColumns, *col)
		}
	}

	return model.Index{
		IndexName: indexName,
		Columns: indexColumns,
	}
}

// formatColumnType 格式化列类型为MySQL格式
// tp: 列类型信息
func (p *StatementParser) formatColumnType(tp *ast.FieldType) string {
	var typeStr strings.Builder

	// 基础类型名称
	typeStr.WriteString(strings.ToLower(mysql.TypeStr(tp.GetType())))

	// 处理长度和精度
	if tp.GetFlen() > 0 {
		typeStr.WriteString(fmt.Sprintf("(%d", tp.GetFlen()))
		if tp.GetDecimal() > 0 {
			typeStr.WriteString(fmt.Sprintf(",%d", tp.GetDecimal()))
		}
		typeStr.WriteString(")")
	}

	// 处理unsigned和zerofill
	if mysql.HasUnsignedFlag(tp.GetFlag()) {
		typeStr.WriteString(" unsigned")
	}
	if mysql.HasZerofillFlag(tp.GetFlag()) {
		typeStr.WriteString(" zerofill")
	}

	return typeStr.String()
}

// getCollation 获取列的字符集校对规则
// tp: 列类型信息
func (p *StatementParser) getCollation(tp *ast.FieldType) string {
	if tp.GetCollate() != "" {
		return tp.GetCollate()
	}
	return ""
}

// generateIndexName 生成索引名称（当未指定时）
// keys: 索引键列表
func (p *StatementParser) generateIndexName(keys []*ast.IndexPartSpecification) string {
	var names []string
	for _, key := range keys {
		names = append(names, key.Column.Name.O)
	}
	return "idx_" + strings.Join(names, "_")
}

// FilterTables 根据配置文件过滤表
// 实现 Parser 接口
func (p *StatementParser) FilterTables(schemas []model.Schema) (filtered []model.Schema) {
	// 如果配置为生成所有表，直接返回
	if p.configger.GenerateConfig.AllTables {
		return schemas
	}

	// 根据配置的表名列表过滤
	filtered = lo.Filter(schemas, func(schema model.Schema, index int) bool {
		return lo.Contains(p.configger.GenerateConfig.TableNames, schema.Name)
	})

	return filtered
}
