import (
	"model_infrax/config"
	"testing"
)

// TestStatementParser_ParseFromSQL 测试从SQL字符串解析表结构
func TestStatementParser_ParseFromSQL(t *testing.T) {
	// 准备测试SQL
	sql := `
CREATE TABLE users (
 id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '用户ID',
 username VARCHAR(100) NOT NULL COMMENT '用户名',
 email VARCHAR(100) UNIQUE COMMENT '邮箱',
 age INT DEFAULT 0 COMMENT '年龄',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
 updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
 INDEX idx_username (username),
 INDEX idx_age (age)
) COMMENT='用户表';

CREATE TABLE orders (
 id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '订单ID',
 user_id BIGINT NOT NULL COMMENT '用户ID',
 order_no VARCHAR(50) NOT NULL UNIQUE COMMENT '订单号',
 amount DECIMAL(10,2) NOT NULL DEFAULT 0.00 COMMENT '订单金额',
 status TINYINT NOT NULL DEFAULT 0 COMMENT '订单状态',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
 INDEX idx_user_id (user_id),
 INDEX idx_order_no (order_no),
 INDEX idx_status (status)
) COMMENT='订单表';
`

	// 创建配置（AllTables=true，解析所有表）
	cfg := &config.Configger{
		GenerateConfig: config.GenerateConfig{
			AllTables: true,
		},
	}

	// 创建解析器
	parser := NewStatementParser(cfg)

	// 解析SQL
	schemas, err := parser.ParseFromSQL(sql)
	if err != nil {
		t.Fatalf("解析SQL失败: %v", err)
	}

	// 验证结果
	if len(schemas) != 2 {
		t.Errorf("期望解析2个表，实际得到 %d 个", len(schemas))
	}

	// 验证第一个表（users）
	if len(schemas) > 0 {
		usersTable := schemas[0]
		t.Logf("表名: %s", usersTable.Name)
		t.Logf("表注释: %s", usersTable.Comment)
		t.Logf("列数: %d", len(usersTable.Columns))
		t.Logf("索引数: %d", len(usersTable.Indexes))
		t.Logf("主键: %s", usersTable.PrimaryKey.IndexName)

		// 打印表结构（JSON格式）
		t.Logf("表结构:\n%s", usersTable.JsonIndent())

		// 验证列信息
		if usersTable.Name != "users" {
			t.Errorf("期望表名为 users，实际为 %s", usersTable.Name)
		}

		if len(usersTable.Columns) != 6 {
			t.Errorf("期望6个列，实际为 %d", len(usersTable.Columns))
		}

		// 验证主键
		if usersTable.PrimaryKey.IndexName != "PRIMARY" {
			t.Errorf("期望主键名为 PRIMARY，实际为 %s", usersTable.PrimaryKey.IndexName)
		}

		// 验证id列是否标记为主键和自增
		for _, col := range usersTable.Columns {
			if col.ColumnName == "id" {
				if !col.IsPrimaryKey {
					t.Error("id列应该被标记为主键")
				}
				if !col.IsAutoIncrement {
					t.Error("id列应该被标记为自增")
				}
				if !col.IsIndexed {
					t.Error("id列应该被标记为索引列")
				}
			}
			if col.ColumnName == "email" {
				if !col.IsUnique {
					t.Error("email列应该被标记为唯一索引")
				}
			}
		}
	}

	// 验证第二个表（orders）
	if len(schemas) > 1 {
		ordersTable := schemas[1]
		t.Logf("\n表名: %s", ordersTable.Name)
		t.Logf("表注释: %s", ordersTable.Comment)
		t.Logf("列数: %d", len(ordersTable.Columns))
		t.Logf("索引数: %d", len(ordersTable.Indexes))

		// 打印表结构（JSON格式）
		t.Logf("表结构:\n%s", ordersTable.JsonIndent())
	}
}

// TestStatementParser_FilterTables 测试表过滤功能
func TestStatementParser_FilterTables(t *testing.T) {
	sql := `
CREATE TABLE users (
 id BIGINT PRIMARY KEY AUTO_INCREMENT
) COMMENT='用户表';

CREATE TABLE orders (
 id BIGINT PRIMARY KEY AUTO_INCREMENT
) COMMENT='订单表';

CREATE TABLE products (
 id BIGINT PRIMARY KEY AUTO_INCREMENT
) COMMENT='产品表';
`

	// 创建配置（只解析指定的表）
	cfg := &config.Configger{
		GenerateConfig: config.GenerateConfig{
			AllTables: false,
			TableNames: []string{"users", "orders"}, // 只要users和orders
		},
	}

	// 创建解析器并解析
	parser := NewStatementParser(cfg)
	schemas, err := parser.ParseFromSQL(sql)
	if err != nil {
		t.Fatalf("解析SQL失败: %v", err)
	}

	// 过滤表
	filtered := parser.FilterTables(schemas)

	// 验证过滤结果
	if len(filtered) != 2 {
		t.Errorf("期望过滤后得到2个表，实际得到 %d 个", len(filtered))
	}

	// 验证过滤的表名
	tableNames := make(map[string]bool)
	for _, schema := range filtered {
		tableNames[schema.Name] = true
	}

	if !tableNames["users"] || !tableNames["orders"] {
		t.Error("过滤结果应该包含 users 和 orders 表")
	}

	if tableNames["products"] {
		t.Error("过滤结果不应该包含 products 表")
	}
}

// TestStatementParser_ComplexTable 测试复杂表结构解析
func TestStatementParser_ComplexTable(t *testing.T) {
	sql := `
CREATE TABLE t_llm_history (
 id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT COMMENT '主键ID',
 session_id VARCHAR(64) NOT NULL COMMENT '会话ID',
 user_id BIGINT UNSIGNED NOT NULL COMMENT '用户ID',
 role VARCHAR(20) NOT NULL COMMENT '角色: user/assistant/system',
 content TEXT NOT NULL COMMENT '消息内容',
 model VARCHAR(50) DEFAULT 'gpt-3.5-turbo' COMMENT '使用的模型',
 tokens INT UNSIGNED DEFAULT 0 COMMENT '消耗的token数',
 created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
 updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
 PRIMARY KEY (id),
 UNIQUE KEY uk_session_id (session_id, created_at),
 KEY idx_user_id (user_id),
 KEY idx_created_at (created_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='LLM对话历史表';
`

	cfg := &config.Configger{
		GenerateConfig: config.GenerateConfig{
			AllTables: true,
		},
	}

	parser := NewStatementParser(cfg)
	schemas, err := parser.ParseFromSQL(sql)
	if err != nil {
		t.Fatalf("解析SQL失败: %v", err)
	}

	if len(schemas) != 1 {
		t.Fatalf("期望解析1个表，实际得到 %d 个", len(schemas))
	}

	table := schemas[0]
	t.Logf("表结构:\n%s", table.JsonIndent())

	// 验证表名和注释
	if table.Name != "t_llm_history" {
		t.Errorf("期望表名为 t_llm_history，实际为 %s", table.Name)
	}

	if table.Comment != "LLM对话历史表" {
		t.Errorf("期望表注释为 'LLM对话历史表'，实际为 '%s'", table.Comment)
	}

	// 验证列数
	if len(table.Columns) != 9 {
		t.Errorf("期望9个列，实际为 %d", len(table.Columns))
	}

	// 验证主键
	if table.PrimaryKey.IndexName != "PRIMARY" {
		t.Errorf("期望主键名为 PRIMARY，实际为 %s", table.PrimaryKey.IndexName)
	}

	// 验证唯一索引
	hasUniqueIndex := false
	for _, idx := range table.UniqueIndex {
		if idx.IndexName == "uk_session_id" {
			hasUniqueIndex = true
			if len(idx.Columns) != 2 {
				t.Errorf("唯一索引 uk_session_id 应该包含2个列，实际为 %d", len(idx.Columns))
			}
		}
	}
	if !hasUniqueIndex {
		t.Error("应该存在唯一索引 uk_session_id")
	}

	// 验证普通索引数量
	if len(table.Indexes) < 2 {
		t.Errorf("期望至少2个索引，实际为 %d", len(table.Indexes))
	}
}
