	"gorm.io/driver/mysql"
	"gorm.io/gorm"
)

// TestDatabaseParser_Parse_WithMock 使用 sqlmock 测试 DatabaseParser.Parse 方法
// 无需真实数据库连接，通过 mock 模拟数据库返回结果
func TestDatabaseParser_Parse_WithMock(t *testing.T) {
	// 1. 创建 sqlmock 实例
	var sqlDB *sql.DB
	var mock sqlmock.Sqlmock
	var err error

	sqlDB, mock, err = sqlmock.New()
	if err != nil {
		t.Fatalf("创建 sqlmock 失败: %v", err)
	}
	defer sqlDB.Close()

	// 2. 使用 sqlmock 创建 GORM DB 实例
	gormDB, err := gorm.Open(mysql.New(mysql.Config{
		Conn: sqlDB,
		SkipInitializeWithVersion: true, // 跳过版本初始化，避免额外的 SQL 查询
	}), &gorm.Config{})
	if err != nil {
		t.Fatalf("创建 GORM DB 失败: %v", err)
	}

	// 3. 创建 DatabaseParser 实例（手动注入 mock DB）
	cfg := &config.Configger{
		GenerateConfig: config.GenerateConfig{
			AllTables: true,
		},
	}
	parser := &DatabaseParser{
		db: gormDB,
		configger: cfg,
	}

	// 4. Mock "show table status" 查询结果
	// 模拟返回两个表：users 和 orders
	tableStatusRows := sqlmock.NewRows([]string{
		"Name", "Engine", "Version", "Row_format", "Rows", "Avg_row_length",
		"Data_length", "Max_data_length", "Index_length", "Data_free",
		"Auto_increment", "Create_time", "Update_time", "Check_time",
		"Collation", "Checksum", "Create_options", "Comment",
	}).
		AddRow(
			"users", "InnoDB", 10, "Dynamic", 100, 1024,
			102400, 0, 16384, 0,
			101, "2024-01-01 00:00:00", "2024-01-02 00:00:00", nil,
			"utf8mb4_unicode_ci", nil, "", "用户表",
		).
		AddRow(
			"orders", "InnoDB", 10, "Dynamic", 50, 2048,
			102400, 0, 16384, 0,
			51, "2024-01-01 00:00:00", "2024-01-02 00:00:00", nil,
			"utf8mb4_unicode_ci", nil, "", "订单表",
		)

	mock.ExpectQuery(regexp.QuoteMeta("show table status")).
		WillReturnRows(tableStatusRows)

	// 5. Mock "show full fields from users" 查询结果
	usersFieldsRows := sqlmock.NewRows([]string{
		"Field", "Type", "Collation", "Null", "Key", "Default", "Extra", "Privileges", "Comment",
	}).
		AddRow("id", "bigint", nil, "NO", "PRI", nil, "auto_increment", "select,insert,update,references", "用户ID").
		AddRow("username", "varchar(100)", "utf8mb4_unicode_ci", "NO", "MUL", nil, "", "select,insert,update,references", "用户名").
		AddRow("email", "varchar(100)", "utf8mb4_unicode_ci", "YES", "UNI", nil, "", "select,insert,update,references", "邮箱").
		AddRow("age", "int", nil, "YES", "", "0", "", "select,insert,update,references", "年龄").
		AddRow("created_at", "timestamp", nil, "NO", "", "CURRENT_TIMESTAMP", "", "select,insert,update,references", "创建时间")

	mock.ExpectQuery(regexp.QuoteMeta("show full fields from `users`")).
		WillReturnRows(usersFieldsRows)

	// 6. Mock "show index from users" 查询结果
	usersIndexRows := sqlmock.NewRows([]string{
		"Table", "Non_unique", "Key_name", "Seq_in_index", "Column_name",
		"Collation", "Cardinality", "Sub_part", "Packed", "Null",
		"Index_type", "Comment", "Index_comment", "Visible", "Expression",
	}).
		AddRow("users", 0, "PRIMARY", 1, "id", "A", 100, nil, nil, "", "BTREE", "", "", "YES", nil).
		AddRow("users", 0, "uk_email", 1, "email", "A", 100, nil, nil, "YES", "BTREE", "", "", "YES", nil).
		AddRow("users", 1, "idx_username", 1, "username", "A", 50, nil, nil, "", "BTREE", "", "", "YES", nil)

	mock.ExpectQuery(regexp.QuoteMeta("show index from `users`")).
		WillReturnRows(usersIndexRows)

	// 7. Mock "show full fields from orders" 查询结果
	ordersFieldsRows := sqlmock.NewRows([]string{
		"Field", "Type", "Collation", "Null", "Key", "Default", "Extra", "Privileges", "Comment",
	}).
		AddRow("id", "bigint", nil, "NO", "PRI", nil, "auto_increment", "select,insert,update,references", "订单ID").
		AddRow("user_id", "bigint", nil, "NO", "MUL", nil, "", "select,insert,update,references", "用户ID").
		AddRow("order_no", "varchar(50)", "utf8mb4_unicode_ci", "NO", "UNI", nil, "", "select,insert,update,references", "订单号").
		AddRow("amount", "decimal(10,2)", nil, "NO", "", "0.00", "", "select,insert,update,references", "订单金额").
		AddRow("status", "tinyint", nil, "NO", "MUL", "0", "", "select,insert,update,references", "订单状态")

	mock.ExpectQuery(regexp.QuoteMeta("show full fields from `orders`")).
		WillReturnRows(ordersFieldsRows)

	// 8. Mock "show index from orders" 查询结果
	ordersIndexRows := sqlmock.NewRows([]string{
		"Table", "Non_unique", "Key_name", "Seq_in_index", "Column_name",
		"Collation", "Cardinality", "Sub_part", "Packed", "Null",
		"Index_type", "Comment", "Index_comment", "Visible", "Expression",
	}).
		AddRow("orders", 0, "PRIMARY", 1, "id", "A", 50, nil, nil, "", "BTREE", "", "", "YES", nil).
		AddRow("orders", 0, "uk_order_no", 1, "order_no", "A", 50, nil, nil, "", "BTREE", "", "", "YES", nil).
		AddRow("orders", 1, "idx_user_id", 1, "user_id", "A", 25, nil, nil, "", "BTREE", "", "", "YES", nil).
		AddRow("orders", 1, "idx_status", 1, "status", "A", 5, nil, nil, "", "BTREE", "", "", "YES", nil)

	mock.ExpectQuery(regexp.QuoteMeta("show index from `orders`")).
		WillReturnRows(ordersIndexRows)

	// 9. 执行解析
	schemas, err := parser.Parse()
	if err != nil {
		t.Fatalf("解析失败: %v", err)
	}

	// 10. 验证结果
	if len(schemas) != 2 {
		t.Errorf("期望解析2个表，实际得到 %d 个", len(schemas))
	}

	// 验证第一个表（users）
	if len(schemas) > 0 {
		usersTable := schemas[0]
		t.Logf("表名: %s", usersTable.Name)
		t.Logf("表注释: %s", usersTable.Comment)
		t.Logf("列数: %d", len(usersTable.Columns))
		t.Logf("索引数: %d", len(usersTable.Indexes))

		// 验证表名和注释
		if usersTable.Name != "users" {
			t.Errorf("期望表名为 users，实际为 %s", usersTable.Name)
		}
		if usersTable.Comment != "用户表" {
			t.Errorf("期望表注释为 '用户表'，实际为 '%s'", usersTable.Comment)
		}

		// 验证列数
		if len(usersTable.Columns) != 5 {
			t.Errorf("期望5个列，实际为 %d", len(usersTable.Columns))
		}

		// 验证主键
		if usersTable.PrimaryKey.IndexName != "PRIMARY" {
			t.Errorf("期望主键名为 PRIMARY，实际为 %s", usersTable.PrimaryKey.IndexName)
		}

		// 验证 id 列的属性
		var idColumn *model.Column
		for i := range usersTable.Columns {
			if usersTable.Columns[i].ColumnName == "id" {
				idColumn = &usersTable.Columns[i]
				break
			}
		}
		if idColumn == nil {
			t.Error("未找到 id 列")
		} else {
			if !idColumn.IsPrimaryKey {
				t.Error("id 列应该被标记为主键")
			}
			if !idColumn.IsAutoIncrement {
				t.Error("id 列应该被标记为自增")
			}
			if !idColumn.IsIndexed {
				t.Error("id 列应该被标记为索引列")
			}
		}

		// 验证 email 列的唯一索引
		var emailColumn *model.Column
		for i := range usersTable.Columns {
			if usersTable.Columns[i].ColumnName == "email" {
				emailColumn = &usersTable.Columns[i]
				break
			}
		}
		if emailColumn == nil {
			t.Error("未找到 email 列")
		} else {
			if !emailColumn.IsUnique {
				t.Error("email 列应该被标记为唯一索引")
			}
		}

		// 打印表结构（JSON格式）
		t.Logf("users 表结构:
%s", usersTable.JsonIndent())
	}

	// 验证第二个表（orders）
	if len(schemas) > 1 {
		ordersTable := schemas[1]
		t.Logf("
表名: %s", ordersTable.Name)
		t.Logf("表注释: %s", ordersTable.Comment)
		t.Logf("列数: %d", len(ordersTable.Columns))
		t.Logf("索引数: %d", len(ordersTable.Indexes))

		// 验证表名
		if ordersTable.Name != "orders" {
			t.Errorf("期望表名为 orders，实际为 %s", ordersTable.Name)
		}

		// 验证列数
		if len(ordersTable.Columns) != 5 {
			t.Errorf("期望5个列，实际为 %d", len(ordersTable.Columns))
		}

		// 打印表结构（JSON格式）
		t.Logf("orders 表结构:
%s", ordersTable.JsonIndent())
	}

	// 11. 验证所有的 mock 期望都被满足
	if err := mock.ExpectationsWereMet(); err != nil {
		t.Errorf("未满足所有 mock 期望: %v", err)
	}
}

// TestDatabaseParser_FilterTables_WithMock 测试表过滤功能（使用 mock）
func TestDatabaseParser_FilterTables_WithMock(t *testing.T) {
	// 创建 sqlmock 实例
	sqlDB, mock, err := sqlmock.New()
	if err != nil {
		t.Fatalf("创建 sqlmock 失败: %v", err)
	}
	defer sqlDB.Close()

	// 创建 GORM DB
	gormDB, err := gorm.Open(mysql.New(mysql.Config{
		Conn: sqlDB,
		SkipInitializeWithVersion: true,
	}), &gorm.Config{})
	if err != nil {
		t.Fatalf("创建 GORM DB 失败: %v", err)
	}

	// 创建配置（只解析指定的表）
	cfg := &config.Configger{
		GenerateConfig: config.GenerateConfig{
			AllTables: false,
			TableNames: []string{"users", "orders"}, // 只要 users 和 orders，不要 products
		},
	}

	parser := &DatabaseParser{
		db: gormDB,
		configger: cfg,
	}

	// Mock "show table status" - 返回3个表
	tableStatusRows := sqlmock.NewRows([]string{
		"Name", "Engine", "Version", "Row_format", "Rows", "Avg_row_length",
		"Data_length", "Max_data_length", "Index_length", "Data_free",
		"Auto_increment", "Create_time", "Update_time", "Check_time",
		"Collation", "Checksum", "Create_options", "Comment",
	}).
		AddRow("users", "InnoDB", 10, "Dynamic", 100, 1024, 102400, 0, 16384, 0, 101, "2024-01-01", nil, nil, "utf8mb4_unicode_ci", nil, "", "用户表").
		AddRow("orders", "InnoDB", 10, "Dynamic", 50, 2048, 102400, 0, 16384, 0, 51, "2024-01-01", nil, nil, "utf8mb4_unicode_ci", nil, "", "订单表").
		AddRow("products", "InnoDB", 10, "Dynamic", 200, 512, 102400, 0, 16384, 0, 201, "2024-01-01", nil, nil, "utf8mb4_unicode_ci", nil, "", "产品表")

	mock.ExpectQuery(regexp.QuoteMeta("show table status")).
		WillReturnRows(tableStatusRows)

	// Mock 每个表的字段和索引查询（简化版）
	for _, tableName := range []string{"users", "orders", "products"} {
		fieldsRows := sqlmock.NewRows([]string{
			"Field", "Type", "Collation", "Null", "Key", "Default", "Extra", "Privileges", "Comment",
		}).AddRow("id", "bigint", nil, "NO", "PRI", nil, "auto_increment", "select", fmt.Sprintf("%s ID", tableName))

		mock.ExpectQuery(regexp.QuoteMeta(fmt.Sprintf("show full fields from `%s`", tableName))).
			WillReturnRows(fieldsRows)

		indexRows := sqlmock.NewRows([]string{
			"Table", "Non_unique", "Key_name", "Seq_in_index", "Column_name",
			"Collation", "Cardinality", "Sub_part", "Packed", "Null",
			"Index_type", "Comment", "Index_comment", "Visible", "Expression",
		}).AddRow(tableName, 0, "PRIMARY", 1, "id", "A", 100, nil, nil, "", "BTREE", "", "", "YES", nil)

		mock.ExpectQuery(regexp.QuoteMeta(fmt.Sprintf("show index from `%s`", tableName))).
			WillReturnRows(indexRows)
	}

	// 执行解析
	schemas, err := parser.Parse()
	if err != nil {
		t.Fatalf("解析失败: %v", err)
	}

	// 过滤表
	filtered := parser.FilterTables(schemas)

	// 验证过滤结果
	if len(filtered) != 2 {
		t.Errorf("期望过滤后得到2个表，实际得到 %d 个", len(filtered))
	}

	// 验证过滤的表名
	tableNames := make(map[string]bool)
	for _, schema := range filtered {
		tableNames[schema.Name] = true
	}

	if !tableNames["users"] || !tableNames["orders"] {
		t.Error("过滤结果应该包含 users 和 orders 表")
	}

	if tableNames["products"] {
		t.Error("过滤结果不应该包含 products 表")
	}

	// 验证 mock 期望
	if err := mock.ExpectationsWereMet(); err != nil {
		t.Errorf("未满足所有 mock 期望: %v", err)
	}
}

// NewDatabaseParserWithMockDB 创建一个使用 mock DB 的 DatabaseParser（用于测试）
// 这是一个辅助函数，方便在其他测试中使用
func NewDatabaseParserWithMockDB(cfg *config.Configger, mockDB *gorm.DB) *DatabaseParser {
	return &DatabaseParser{
		db: mockDB,
		configger: cfg,
	}
}
