import (
	"fmt"
	"model_infrax/config"
	"model_infrax/model"
	"model_infrax/tool"
	"regexp"
	"strings"

	"github.com/samber/lo"
)

// SQLFileParser SQL文件解析器，用于从SQL语句解析表结构
type SQLFileParser struct {
	configger *config.Configger
}

// NewSQLFileParser 创建SQL文件解析器
func NewSQLFileParser(cfg *config.Configger) *SQLFileParser {
	return &SQLFileParser{
		configger: cfg,
	}
}

// ParseFromSQL 从SQL字符串解析表结构
func (p *SQLFileParser) ParseFromSQL(sqlContent string) ([]model.Schema, error) {
	// 清理SQL内容，移除注释和多余空行
	cleanSQL := p.cleanSQL(sqlContent)

	// 提取所有CREATE TABLE语句
	createTableStatements := p.extractCreateTableStatements(cleanSQL)

	if len(createTableStatements) == 0 {
		return nil, fmt.Errorf("未找到CREATE TABLE语句")
	}

	// 解析每个CREATE TABLE语句
	schemas := lo.Map(createTableStatements, func(stmt string, index int) model.Schema {
		return p.parseCreateTableStatement(stmt)
	})

	return schemas, nil
}

// cleanSQL 清理SQL内容，移除注释
func (p *SQLFileParser) cleanSQL(sql string) string {
	// 移除单行注释
	singleLineComment := regexp.MustCompile(`--[^\n]*`)
	sql = singleLineComment.ReplaceAllString(sql, "")

	// 移除多行注释
	multiLineComment := regexp.MustCompile(`/\*[\s\S]*?\*/`)
	sql = multiLineComment.ReplaceAllString(sql, "")

	// 移除多余空行
	sql = strings.TrimSpace(sql)

	return sql
}

// extractCreateTableStatements 提取所有CREATE TABLE语句
func (p *SQLFileParser) extractCreateTableStatements(sql string) []string {
	// 匹配CREATE TABLE语句的正则表达式
	// 支持IF NOT EXISTS和反引号表名
	pattern := regexp.MustCompile(`(?i)CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?`([^`]+)`\s*\(([\s\S]*?)\)(?:\s*;)?`)

	matches := pattern.FindAllStringSubmatch(sql, -1)

	var statements []string
	for _, match := range matches {
		if len(match) >= 3 {
			tableName := strings.Trim(match[1], "`")
			tableDef := match[2]
			statements = append(statements, fmt.Sprintf("CREATE TABLE `%s` (%s)", tableName, tableDef))
		}
	}

	return statements
}

// parseCreateTableStatement 解析单个CREATE TABLE语句
func (p *SQLFileParser) parseCreateTableStatement(stmt string) model.Schema {
	// 提取表名
	tableNamePattern := regexp.MustCompile(`CREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?`([^`]+)`\s*\(`)
	tableNameMatch := tableNamePattern.FindStringSubmatch(stmt)
	tableName := strings.Trim(tableNameMatch[1], "`")

	// 提取表注释
	tableComment := p.extractTableComment(stmt)

	// 提取列定义
	columnDefs := p.extractColumnDefinitions(stmt)
	columns := p.parseColumns(columnDefs)

	// 提取主键
	primaryKey := p.extractPrimaryKey(stmt, columns)

	// 提取索引
	indexes, uniqueIndexes := p.extractIndexes(stmt, columns)

	// 标记列的索引属性
	p.markColumnIndexes(columns, primaryKey, indexes, uniqueIndexes)

	return model.Schema{
		Name: tableName,
		Comment: tableComment,
		Columns: columns,
		PrimaryKey: primaryKey,
		Indexes: indexes,
		UniqueIndex: uniqueIndexes,
	}
}

// extractTableComment 提取表注释
func (p *SQLFileParser) extractTableComment(stmt string) string {
	// 匹配表注释 COMMENT='xxx'
	pattern := regexp.MustCompile(`COMMENT\s*=\s*'([^']*)'`)
	match := pattern.FindStringSubmatch(stmt)
	if len(match) > 1 {
		return match[1]
	}
	return ""
}

// extractColumnDefinitions 提取列定义部分
func (p *SQLFileParser) extractColumnDefinitions(stmt string) string {
	// 提取括号内的内容
	start := strings.Index(stmt, "(")
	end := strings.LastIndex(stmt, ")")
	if start != -1 && end != -1 && end > start {
		return stmt[start+1 : end]
	}
	return ""
}

// parseColumns 解析列定义
func (p *SQLFileParser) parseColumns(columnDefs string) []model.Column {
	// 按行分割列定义
	lines := strings.Split(columnDefs, "\n")

	var columns []model.Column

	for _, line := range lines {
		line = strings.TrimSpace(line)
		if line == "" || strings.HasPrefix(strings.ToUpper(line), "PRIMARY KEY") ||
		 strings.HasPrefix(strings.ToUpper(line), "KEY") || 
		 strings.HasPrefix(strings.ToUpper(line), "UNIQUE KEY") ||
		 strings.HasPrefix(strings.ToUpper(line), "INDEX") {
			continue // 跳过索引定义行
		}

		column := p.parseSingleColumn(line)
		if column.ColumnName != "" {
			columns = append(columns, column)
		}
	}

	return columns
}

// parseSingleColumn 解析单个列定义
func (p *SQLFileParser) parseSingleColumn(line string) model.Column {
	// 移除末尾的逗号
	line = strings.TrimSuffix(line, ",")
	line = strings.TrimSpace(line)

	// 分割列定义部分
	parts := strings.Fields(line)
	if len(parts) < 2 {
		return model.Column{}
	}

	columnName := strings.Trim(parts[0], "`")
	columnType := parts[1]

	column := model.Column{
		ColumnName: columnName,
		Type: columnType,
	}

	// 解析其他属性
	remainingLine := strings.Join(parts[2:], " ")
	column = p.parseColumnAttributes(column, remainingLine)

	return column
}

// parseColumnAttributes 解析列属性
func (p *SQLFileParser) parseColumnAttributes(column model.Column, line string) model.Column {
	// 检查NOT NULL
	if strings.Contains(strings.ToUpper(line), "NOT NULL") {
		column.IsNullable = false
	} else if strings.Contains(strings.ToUpper(line), "NULL") {
		column.IsNullable = true
	}

	// 检查AUTO_INCREMENT
	if strings.Contains(strings.ToUpper(line), "AUTO_INCREMENT") {
		column.IsAutoIncrement = true
	}

	// 提取默认值
	defaultPattern := regexp.MustCompile(`DEFAULT\s+([^\s,]+)`)
	defaultMatch := defaultPattern.FindStringSubmatch(line)
	if len(defaultMatch) > 1 {
		defaultValue := strings.Trim(defaultMatch[1], "'\"")
		column.Default = &defaultValue
	}

	// 提取注释
	commentPattern := regexp.MustCompile(`COMMENT\s+'([^']*)'`)
	commentMatch := commentPattern.FindStringSubmatch(line)
	if len(commentMatch) > 1 {
		column.Comment = commentMatch[1]
	}

	// 提取字符集校对规则
	collatePattern := regexp.MustCompile(`COLLATE\s+(\w+)`)
	collateMatch := collatePattern.FindStringSubmatch(line)
	if len(collateMatch) > 1 {
		column.Collate = collateMatch[1]
	}

	return column
}

// extractPrimaryKey 提取主键信息
func (p *SQLFileParser) extractPrimaryKey(stmt string, columns []model.Column) model.Index {
	// 查找PRIMARY KEY定义
	primaryKeyPattern := regexp.MustCompile(`PRIMARY\s+KEY\s*\(([^)]+)\)`)
	match := primaryKeyPattern.FindStringSubmatch(stmt)

	if len(match) == 0 {
		// 如果没有单独的PRIMARY KEY定义，查找列定义中的PRIMARY KEY
		for _, col := range columns {
			if col.IsPrimaryKey {
				return model.Index{
					IndexName: "PRIMARY",
					Columns: []model.Column{col},
				}
			}
		}
		return model.Index{}
	}

	// 解析主键列名
	columnNames := strings.Split(strings.ReplaceAll(match[1], "`", ""), ",")
	columnNames = lo.Map(columnNames, func(name string, _ int) string {
		return strings.TrimSpace(name)
	})

	var pkColumns []model.Column
	for _, col := range columns {
		if lo.Contains(columnNames, col.ColumnName) {
			col.IsPrimaryKey = true
			pkColumns = append(pkColumns, col)
		}
	}

	return model.Index{
		IndexName: "PRIMARY",
		Columns: pkColumns,
	}
}

// extractIndexes 提取索引信息
func (p *SQLFileParser) extractIndexes(stmt string, columns []model.Column) ([]model.Index, []model.Index) {
	var indexes []model.Index
	var uniqueIndexes []model.Index

	// 匹配KEY/INDEX定义
	keyPattern := regexp.MustCompile(`(?i)(UNIQUE\s+)?(?:KEY|INDEX)\s+`([^`]+)`\s*\(([^)]+)\)`)
	matches := keyPattern.FindAllStringSubmatch(stmt, -1)

	for _, match := range matches {
		if len(match) < 4 {
			continue
		}

		isUnique := strings.ToUpper(match[1]) == "UNIQUE "
		indexName := strings.Trim(match[2], "`")
		columnNamesStr := match[3]

		// 解析索引列名
		columnNames := strings.Split(strings.ReplaceAll(columnNamesStr, "`", ""), ",")
		columnNames = lo.Map(columnNames, func(name string, _ int) string {
			return strings.TrimSpace(name)
		})

		var indexColumns []model.Column
		for _, col := range columns {
			if lo.Contains(columnNames, col.ColumnName) {
				indexColumns = append(indexColumns, col)
			}
		}

		index := model.Index{
			IndexName: indexName,
			Columns: indexColumns,
		}

		if isUnique {
			uniqueIndexes = append(uniqueIndexes, index)
		} else {
			indexes = append(indexes, index)
		}
	}

	return indexes, uniqueIndexes
}

// markColumnIndexes 标记列的索引属性
func (p *SQLFileParser) markColumnIndexes(columns []model.Column, primaryKey model.Index, indexes []model.Index, uniqueIndexes []model.Index) {
	// 标记主键列
	for _, pkCol := range primaryKey.Columns {
		for i := range columns {
			if columns[i].ColumnName == pkCol.ColumnName {
				columns[i].IsPrimaryKey = true
				break
			}
		}
	}

	// 标记唯一索引列
	for _, uniqueIndex := range uniqueIndexes {
		for _, uniqCol := range uniqueIndex.Columns {
			for i := range columns {
				if columns[i].ColumnName == uniqCol.ColumnName {
					columns[i].IsUnique = true
					columns[i].IsIndexed = true
					break
				}
			}
		}
	}

	// 标记普通索引列
	for _, index := range indexes {
		for _, idxCol := range index.Columns {
			for i := range columns {
				if columns[i].ColumnName == idxCol.ColumnName {
					columns[i].IsIndexed = true
					break
				}
			}
		}
	}
}

// FilterTables 根据配置文件过滤表（复用原有逻辑）
func (p *SQLFileParser) FilterTables(schemas []model.Schema) (filtered []model.Schema) {
	if p.configger.GenerateConfig.AllTables {
		filtered = schemas
		return
	}
	filtered = lo.Filter(schemas, func(schema model.Schema, index int) bool {
		return lo.Contains(p.configger.GenerateConfig.TableNames, schema.Name)
	})
	return
