	"testing"
)

// TestSQLFileParser_ParseFromSQL 测试从SQL字符串解析表结构
func TestSQLFileParser_ParseFromSQL(t *testing.T) {
	// 示例SQL内容
	sqlContent := `CREATE TABLE IF NOT EXISTS \`t_user\`
(
 \`id\` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
 \`userId\` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户ID',
 \`userName\` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户名称',
 \`email\` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '邮箱',
 \`createTime\` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
 \`updateTime\` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
 PRIMARY KEY (\`id\`),
 UNIQUE KEY \`uk_userId\` (\`userId\`),
 KEY \`idx_userName\` (\`userName\`),
 KEY \`idx_email\` (\`email\`)
) ENGINE = InnoDB
 DEFAULT CHARSET = utf8mb4
 COLLATE = utf8mb4_unicode_ci COMMENT ='用户表';

CREATE TABLE IF NOT EXISTS \`t_memory\`
(
 \`id\` bigint(20) unsigned NOT NULL AUTO_INCREMENT COMMENT '主键ID',
 \`memoryId\` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '记忆ID',
 \`userId\` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '用户ID',
 \`summary\` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '摘要',
 \`raw_dialog_array\` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '对话的JSON格式，包括了节点的输入输出等',
 \`createTime\` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
 \`updateTime\` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
 PRIMARY KEY (\`id\`),
 UNIQUE KEY \`uk_memoryId\` (\`memoryId\`),
 KEY \`idx_userId\` (\`userId\`)
) ENGINE = InnoDB
 DEFAULT CHARSET = utf8mb4
 COLLATE = utf8mb4_unicode_ci COMMENT ='记忆表';`

	// 创建SQL文件解析器
	parser := NewSQLFileParser(nil) // 这里可以传入配置

	// 解析SQL内容
	schemas, err := parser.ParseFromSQL(sqlContent)
	if err != nil {
		t.Fatalf("解析SQL失败: %v", err)
	}

	// 输出解析结果
	fmt.Printf(" 成功解析出 %d 个表:\n", len(schemas))
	for i, schema := range schemas {
		fmt.Printf("\n 表 %d: %s\n", i+1, schema.Name)
		fmt.Printf(" 注释: %s\n", schema.Comment)
		fmt.Printf(" 列数: %d\n", len(schema.Columns))
		fmt.Printf(" 主键: %s\n", schema.PrimaryKey.IndexName)
		fmt.Printf(" 普通索引数: %d\n", len(schema.Indexes))
		fmt.Printf(" 唯一索引数: %d\n", len(schema.UniqueIndex))

		// 显示列信息
		fmt.Println(" 列详情:")
		for _, col := range schema.Columns {
			flags := []string{}
			if col.IsPrimaryKey {
				flags = append(flags, "PK")
			}
			if col.IsUnique {
				flags = append(flags, "UNIQUE")
			}
			if col.IsIndexed {
				flags = append(flags, "INDEXED")
			}
			if col.IsAutoIncrement {
				flags = append(flags, "AUTO")
			}
			if !col.IsNullable {
				flags = append(flags, "NOT NULL")
			}

			flagStr := ""
			if len(flags) > 0 {
				flagStr = fmt.Sprintf(" [%s]", strings.Join(flags, ", "))
			}

			defaultStr := ""
			if col.Default != nil {
				defaultStr = fmt.Sprintf(" DEFAULT %s", *col.Default)
			}

			commentStr := ""
			if col.Comment != "" {
				commentStr = fmt.Sprintf(" // %s", col.Comment)
			}

			fmt.Printf(" - %s %s%s%s%s\n", col.ColumnName, col.Type, defaultStr, flagStr, commentStr)
		}
	}

	// 验证第一个表
	if len(schemas) > 0 {
		userTable := schemas[0]
		if userTable.Name != "t_user" {
			t.Errorf("期望表名为 't_user'，实际为 '%s'", userTable.Name)
		}

		if userTable.Comment != "用户表" {
			t.Errorf("期望表注释为 '用户表'，实际为 '%s'", userTable.Comment)
		}

		if len(userTable.Columns) != 6 {
			t.Errorf("期望6列，实际为 %d 列", len(userTable.Columns))
		}

		if userTable.PrimaryKey.IndexName != "PRIMARY" {
			t.Errorf("期望主键名为 'PRIMARY'，实际为 '%s'", userTable.PrimaryKey.IndexName)
		}

		if len(userTable.UniqueIndex) != 1 {
			t.Errorf("期望1个唯一索引，实际为 %d 个", len(userTable.UniqueIndex))
		}
	}
}

