		Parser: p,
		Generator: g,
	}
}

// Run 运行应用程序，执行完整的代码生成流程
// 流程包括：
// 1. 解析数据库表结构（从数据库或SQL文件）
// 2. 根据配置过滤需要处理的表
// 3. 生成Model实体类代码
// 4. 生成DTO数据传输对象代码
// 5. 生成DAO数据访问对象代码
// 6. 生成Tool工具类代码
func (a *App) Run() error {
	log.Println(" 开始解析数据库...")

	var schemas []model.Schema
	var err error

	// 根据配置选择解析方式
	if a.Config.GenerateConfig.GenerateMode == "sql_file" {
		log.Printf(" 使用SQL文件模式解析: %s", a.Config.GenerateConfig.SQLFilePath)
		sqlFileParser := a.Parser.(*parser.SQLFileParser)
		schemas, err = sqlFileParser.ParseFromSQLFile(a.Config.GenerateConfig.SQLFilePath)
	} else {
		log.Println("️ 使用数据库连接模式解析")
		dbParser := a.Parser.(*parser.Parser)
		schemas, err = dbParser.AllTables()
	}

	if err != nil {
		return err
	}

	log.Printf("✅ 解析完成，共获取到 %d 个表", len(schemas))

	// 根据配置过滤表
	var filteredSchemas []model.Schema
	if a.Config.GenerateConfig.GenerateMode == "sql_file" {
		sqlFileParser := a.Parser.(*parser.SQLFileParser)
		filteredSchemas = sqlFileParser.FilterTables(schemas)
	} else {
		dbParser := a.Parser.(*parser.Parser)
		filteredSchemas = dbParser.FilterTables(schemas)
	}

	log.Printf(" 过滤后需要处理的表数量: %d", len(filteredSchemas))

	log.Println("️ 开始生成 Model 代码...")

	// 生成Model实体类代码
	// 根据配置决定是生成到一个文件还是分别生成
	if a.Config.GenerateOption.ModelAllInOneFile {
		err = a.Generator.GenerateModel(filteredSchemas, a.Config.GenerateOption.ModelAllInOneFileName)
	} else {
		err = a.Generator.GenerateModelOneByOne(filteredSchemas)
	}
	if err != nil {
		return err
	}

	log.Println("✅ Model 代码生成完成")

	log.Println(" 开始生成 DTO 代码...")

	// 生成DTO数据传输对象代码，用于API接口的数据交换
	err = a.Generator.GenerateDTOOneByOne(filteredSchemas)
	if err != nil {
		return err
	}

	log.Println("✅ DTO 代码生成完成")

	log.Println("️ 开始生成 DAO 代码...")

	// 生成DAO数据访问对象代码，提供数据库操作方法
	err = a.Generator.GenerateDAOOneByOne(filteredSchemas)
	if err != nil {
		return err
	}

	log.Println("✅ DAO 代码生成完成")

	log.Println("️ 开始生成 Tool 工具代码...")

	// 生成Tool工具类代码，提供通用的辅助功能
	err = a.Generator.GenerateAllTools()
	if err != nil {
		return err
	}

	log.Println(" 所有代码生成完成！")

	return nil
}

func main() {

	configPath := flag.StringP("config", "c", "./assert/application.yml", "配置文件路径")

	flag.Parse()

	app, err := InitializeApp(*configPath)
	if err != nil {
		log.Fatalf("初始化应用失败: %v", err)
	}

	if err = app.Run(); err != nil {
		log.Fatalf("运行应用失败: %v", err)
	}
}","instruction":"修改主程序支持SQL文件解析模式，根据配置选择不同的解析器","apply_mode":"manual"}},"timestamp":1763381503,"type":"TOOL_CALL_ARGS"}

