// InitializeApp 初始化应用程序，Wire会自动生成依赖注入代码
// 注意：由于需要根据配置选择不同的解析器，这里返回interface{}
func InitializeApp(configPath string) (*App, error) {
	// 手动初始化，因为需要根据配置选择解析器类型
	cfg, err := config.NewConfigger(configPath)
	if err != nil {
		return nil, err
	}

	// 初始化生成器
	generator, err := generator.NewGenerator(cfg)
	if err != nil {
		return nil, err
	}

	// 根据配置选择解析器
	var parserInstance interface{}
	if cfg.GenerateConfig.GenerateMode == "sql_file" {
		parserInstance = parser.NewSQLFileParser(cfg)
	} else {
		parserInstance, err = parser.NewParser(cfg)
		if err != nil {
			return nil, err
		}
	}

	// 创建应用实例
	app := NewApp(cfg, parserInstance, generator)
	return app, nil
}

// InitializeParser 单独初始化数据库解析器
