{"rawEvent":{"message_id":"019a91b798ec755ea8d35efafc2a315f","conversation_id":"019a91b3f6d3766ba33c0d26cbdd6939","tool_call_id":"call_6c5aa3a1c9f34269ac499f59","document":{"file_path":"/Users/jacklingo/dev/model_infrax/parser/sql_file_parser.go","sub_content":"sql_file_parser.go","sub_content_event":"open_editor","sub_content_event_value":"/Users/jacklingo/dev/model_infrax/parser/sql_file_parser.go","sub_content_tip":"/Users/jacklingo/dev/model_infrax/parser/sql_file_parser.go","apply_content":"// parseSingleColumn 解析单个列定义
func (p *SQLFileParser) parseSingleColumn(line string) model.Column {
	// 移除末尾的逗号
	line = strings.TrimSuffix(line, ",")
	// 处理可能的结尾分号
	line = strings.TrimSuffix(line, ";")
	line = strings.TrimSpace(line)

	// 分割列定义部分 - 使用更智能的分割方式
	fields := p.parseSQLFields(line)
	if len(fields) < 2 {
		return model.Column{}
	}

	columnName := strings.Trim(fields[0], "`")
	columnType := fields[1]

	column := model.Column{
		ColumnName: columnName,
		Type: columnType,
	}

	// 解析其他属性
	remainingLine := strings.Join(fields[2:], " ")
	column = p.parseColumnAttributes(column, remainingLine)

	return column
}

// parseSQLFields 智能解析SQL字段，处理带引号的字段
func (p *SQLFileParser) parseSQLFields(line string) []string {
	var fields []string
	var current strings.Builder
	inQuotes := false
	quoteChar := byte(0)

	for i, char := range line {
		switch {
		case !inQuotes && (char == '\'' || char == '"'):
			inQuotes = true
			quoteChar = byte(char)
			current.WriteByte(byte(char))
		case inQuotes && byte(char) == quoteChar:
			inQuotes = false
			current.WriteByte(byte(char))
			quoteChar = 0
		case !inQuotes && char == ' ':
			if current.Len() > 0 {
				fields = append(fields, current.String())
				current.Reset()
			}
		default:
			current.WriteByte(byte(char))
		}

		// 处理最后一个字段
		if i == len(line)-1 && current.Len() > 0 {
			fields = append(fields, current.String())
		}
	}

	return fields
}","instruction":"改进列定义解析，更好地处理引号和空格分割","apply_mode":"manual"}},"timestamp":1763381568,"type":"TOOL_CALL_ARGS"}

