func (dao *{{ $daoName }}) MustUpdateBy{{ $pkFieldName }}(poBean *{{ $.PoPackageName }}.{{ $entityName }}, {{ $pkParamName }} {{ $pkGoType }}) error {
	if poBean == nil {
